def _build_operator_resolution_happy_path_summary(
    args: argparse.Namespace,
    *,
    artifacts: dict[str, Path],
    stage_reports: dict[str, dict[str, Any]],
    base_intake_unchanged: bool,
    errors: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    errors = errors or []
    validation = stage_reports.get("validation") or {}
    apply_preview = stage_reports.get("apply_preview") or {}
    apply_draft = stage_reports.get("apply_draft") or {}
    draft_gate = stage_reports.get("draft_gate") or {}
    validation_valid_count = int(validation.get("operator_resolution_validation_valid_count") or 0)
    apply_preview_eligible_count = int(apply_preview.get("operator_resolution_apply_preview_eligible_count") or 0)
    apply_draft_applied_count = int(apply_draft.get("operator_resolution_apply_draft_applied_count") or 0)
    draft_gate_ready_count = int(draft_gate.get("document_intake_draft_gate_preview_ready_count") or 0)
    run_chain = bool(getattr(args, "operator_resolution_happy_path_run_chain", True))
    passed = (
        run_chain
        and validation_valid_count == 1
        and apply_preview_eligible_count == 1
        and apply_draft_applied_count == 1
        and draft_gate_ready_count == 1
        and bool(draft_gate.get("document_intake_draft_gate_preview_gate_passed"))
        and base_intake_unchanged
    )
    status = "failed" if errors else "passed" if passed else "warning" if run_chain else "fixtures_generated"
    return {
        "status": status,
        "mode": "operator-resolution-happy-path-synthetic",
        "synthetic_only": True,
        "company_id": str(getattr(args, "operator_resolution_happy_path_company_id", "900001")),
        "company_name": str(getattr(args, "operator_resolution_happy_path_company_name", "Synthetic BondRadar Issuer")),
        "target_reporting_period": str(getattr(args, "operator_resolution_happy_path_report_period", "2025")),
        "required_report_type": str(getattr(args, "operator_resolution_happy_path_report_type", "annual")),
        "required_standard": str(getattr(args, "operator_resolution_happy_path_accounting_standard", "IFRS")),
        "run_chain": run_chain,
        "validation_valid_count": validation_valid_count,
        "apply_preview_eligible_count": apply_preview_eligible_count,
        "apply_draft_applied_count": apply_draft_applied_count,
        "draft_gate_ready_count": draft_gate_ready_count,
        "draft_gate_passed": bool(draft_gate.get("document_intake_draft_gate_preview_gate_passed")),
        "ready_for_value_extraction": bool(draft_gate.get("document_intake_draft_gate_preview_ready_for_value_extraction")),
        "ready_for_import": bool(draft_gate.get("document_intake_draft_gate_preview_ready_for_import")),
        "original_intake_modified": not base_intake_unchanged,
        "draft_intake_created": bool(artifacts.get("exact_document_intake_draft_json") and artifacts["exact_document_intake_draft_json"].is_file()),
        "artifacts": {key: str(path) for key, path in artifacts.items()},
        "stage_reports": stage_reports,
        "warnings": [] if passed or not run_chain else [{"message": "synthetic_happy_path_chain_not_ready"}],
        "errors": errors,
        "next_steps": _next_steps("operator-resolution-happy-path-synthetic", status),
        "would_extract_values": False,
        "would_import_report": False,
        "would_update_database": False,
        "would_update_original_intake": False,
        **SAFETY_FLAGS,
    }


def run_operator_resolution_chain_preview(args: argparse.Namespace) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    artifacts: dict[str, Path] = {}
    output_dir = args.operator_resolution_chain_output_dir
    if output_dir is None:
        errors.append({"message": "operator_resolution_chain_output_dir_required"})
    if args.operator_resolution_input is None:
        errors.append({"message": "operator_resolution_input_required"})
    if args.document_intake_input is None:
        errors.append({"message": "document_intake_input_required"})

    if output_dir is not None:
        artifacts = _operator_resolution_chain_preview_artifacts(output_dir)
        errors.extend(_operator_resolution_chain_preview_collision_errors(args, artifacts))
    if errors:
        return _finish_operator_resolution_chain_preview(
            args,
            artifacts=artifacts,
            stage_reports={},
            completed_stages=[],
            failed_stage=None,
            original_intake_unchanged=True,
            errors=errors,
            write_artifacts=not any(
                error.get("message") == "operator_resolution_chain_output_must_not_equal_input"
                for error in errors
            ),
        )

    try:
        output_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        return _finish_operator_resolution_chain_preview(
            args,
            artifacts=artifacts,
            stage_reports={},
            completed_stages=[],
            failed_stage=None,
            original_intake_unchanged=True,
            errors=[{"message": str(exc)}],
            write_artifacts=False,
        )

    try:
        original_intake_before = args.document_intake_input.read_bytes()
    except OSError as exc:
        return _finish_operator_resolution_chain_preview(
            args,
            artifacts=artifacts,
            stage_reports={},
            completed_stages=[],
            failed_stage=None,
            original_intake_unchanged=True,
            errors=[{"message": str(exc)}],
        )

    chain_args = _clone_args(
        args,
        probe_urls=False,
        seed_probe_urls=False,
        exact_document_probe_urls=False,
        download_documents=False,
        download_source_documents=False,
        exact_document_download_documents=False,
        _internal_official_source_domains=(),
        json_output=None,
        markdown_output=None,
    )
    stage_reports: dict[str, dict[str, Any]] = {}
    completed_stages: list[str] = []
    failed_stage: str | None = None

    validation_args = _clone_args(
        chain_args,
        mode="operator-resolution-validate",
        operator_resolution_validation_output=artifacts["operator_resolution_validation_json"],
        operator_resolution_validation_csv_output=artifacts["operator_resolution_validation_csv"],
        operator_resolution_validation_markdown_output=artifacts["operator_resolution_validation_markdown"],
    )
    stage_reports["validation"] = run_operator_resolution_validate(validation_args)
    completed_stages.append("operator-resolution-validate")
    if stage_reports["validation"].get("status") == "failed":
        failed_stage = "operator-resolution-validate"

    if failed_stage is None:
        apply_preview_args = _clone_args(
            chain_args,
            mode="operator-resolution-apply-preview",
            operator_resolution_validation_input=artifacts["operator_resolution_validation_json"],
            operator_resolution_apply_preview_output=artifacts["operator_resolution_apply_preview_json"],
            operator_resolution_apply_preview_csv_output=artifacts["operator_resolution_apply_preview_csv"],
            operator_resolution_apply_preview_markdown_output=artifacts["operator_resolution_apply_preview_markdown"],
        )
        stage_reports["apply_preview"] = run_operator_resolution_apply_preview(apply_preview_args)
        completed_stages.append("operator-resolution-apply-preview")
        if stage_reports["apply_preview"].get("status") == "failed":
            failed_stage = "operator-resolution-apply-preview"

    if failed_stage is None:
        apply_draft_args = _clone_args(
            chain_args,
            mode="operator-resolution-apply-draft",
            operator_resolution_apply_preview_input=artifacts["operator_resolution_apply_preview_json"],
            document_intake_draft_output=artifacts["exact_document_intake_draft_json"],
            document_intake_draft_csv_output=artifacts["exact_document_intake_draft_csv"],
            operator_resolution_apply_draft_output=artifacts["operator_resolution_apply_draft_json"],
            operator_resolution_apply_draft_csv_output=artifacts["operator_resolution_apply_draft_csv"],
            operator_resolution_apply_draft_markdown_output=artifacts["operator_resolution_apply_draft_markdown"],
        )
        stage_reports["apply_draft"] = run_operator_resolution_apply_draft(apply_draft_args)
        completed_stages.append("operator-resolution-apply-draft")
        if stage_reports["apply_draft"].get("status") == "failed":
            failed_stage = "operator-resolution-apply-draft"

    if failed_stage is None:
        draft_gate_args = _clone_args(
            chain_args,
            mode="document-intake-draft-gate-preview",
            document_intake_draft_input=artifacts["exact_document_intake_draft_json"],
            document_intake_draft_validation_output=artifacts["document_intake_draft_validation_json"],
            document_intake_draft_validation_markdown_output=artifacts["document_intake_draft_validation_markdown"],
            document_intake_draft_gate_output=artifacts["document_intake_draft_gate_json"],
            document_intake_draft_gate_markdown_output=artifacts["document_intake_draft_gate_markdown"],
            document_intake_draft_gate_summary_output=artifacts["document_intake_draft_gate_summary_json"],
            document_intake_draft_gate_summary_csv_output=artifacts["document_intake_draft_gate_summary_csv"],
            document_intake_draft_gate_summary_markdown_output=artifacts["document_intake_draft_gate_summary_markdown"],
        )
        stage_reports["draft_gate"] = run_document_intake_draft_gate_preview(draft_gate_args)
        completed_stages.append("document-intake-draft-gate-preview")
        if stage_reports["draft_gate"].get("status") == "failed":
            failed_stage = "document-intake-draft-gate-preview"

    try:
        original_intake_unchanged = args.document_intake_input.read_bytes() == original_intake_before
    except OSError:
        original_intake_unchanged = False
    if not original_intake_unchanged:
        errors.append({"message": "original_document_intake_modified_unexpectedly"})
    if failed_stage is not None:
        errors.append({"message": "operator_resolution_chain_stage_failed", "stage": failed_stage})

    return _finish_operator_resolution_chain_preview(
        args,
        artifacts=artifacts,
        stage_reports=stage_reports,
        completed_stages=completed_stages,
        failed_stage=failed_stage,
        original_intake_unchanged=original_intake_unchanged,
        errors=errors,
    )


def _operator_resolution_chain_preview_artifacts(output_dir: Path) -> dict[str, Path]:
    return {
        key: output_dir / file_name
        for key, file_name in OPERATOR_RESOLUTION_CHAIN_PREVIEW_ARTIFACT_NAMES.items()
    }


def _operator_resolution_chain_preview_collision_errors(
    args: argparse.Namespace,
    artifacts: dict[str, Path],
) -> list[dict[str, Any]]:
    protected_inputs = [
        path
        for path in (
            args.operator_resolution_input,
            args.operator_resolution_source_pack_input,
            args.document_intake_input,
            args.source_intake_input,
        )
        if path is not None
    ]
    outputs = [
        *artifacts.values(),
        *(
            path
            for path in (
                args.operator_resolution_chain_output_dir,
                args.json_output,
                args.markdown_output,
            )
            if path is not None
        ),
    ]
    errors: list[dict[str, Any]] = []
    for output_path in outputs:
        for input_path in protected_inputs:
            if _paths_equal(output_path, input_path):
                errors.append(
                    {
                        "message": "operator_resolution_chain_output_must_not_equal_input",
                        "output_path": str(output_path),
                        "input_path": str(input_path),
                    }
                )
    return errors


def _finish_operator_resolution_chain_preview(
    args: argparse.Namespace,
    *,
    artifacts: dict[str, Path],
    stage_reports: dict[str, dict[str, Any]],
    completed_stages: list[str],
    failed_stage: str | None,
    original_intake_unchanged: bool,
    errors: list[dict[str, Any]],
    write_artifacts: bool = True,
) -> dict[str, Any]:
    report = _build_operator_resolution_chain_preview_summary(
        args,
        artifacts=artifacts,
        stage_reports=stage_reports,
        completed_stages=completed_stages,
        failed_stage=failed_stage,
        original_intake_unchanged=original_intake_unchanged,
        errors=errors,
    )
    if artifacts and write_artifacts:
        try:
            args.operator_resolution_chain_output_dir.mkdir(parents=True, exist_ok=True)
            write_json_report(report, artifacts["chain_summary_json"])
            write_operator_resolution_chain_preview_summary_csv(report, artifacts["chain_summary_csv"])
            write_operator_resolution_chain_preview_markdown(report, artifacts["chain_summary_markdown"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report.get("errors", []), {"message": str(exc)}]
    return report


def _build_operator_resolution_chain_preview_summary(
    args: argparse.Namespace,
    *,
    artifacts: dict[str, Path],
    stage_reports: dict[str, dict[str, Any]],
    completed_stages: list[str],
    failed_stage: str | None,
    original_intake_unchanged: bool,
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    validation = stage_reports.get("validation") or {}
    apply_preview = stage_reports.get("apply_preview") or {}
    apply_draft = stage_reports.get("apply_draft") or {}
    draft_gate = stage_reports.get("draft_gate") or {}
    warnings = [
        {"stage": stage, **warning}
        for stage, stage_report in stage_reports.items()
        for warning in stage_report.get("warnings") or []
    ]
    stage_errors = [
        {"stage": stage, **error}
        for stage, stage_report in stage_reports.items()
        for error in stage_report.get("errors") or []
    ]
    all_errors = [*errors, *stage_errors]
    passed = (
        not all_errors
        and bool(draft_gate.get("document_intake_draft_gate_preview_gate_passed"))
        and bool(draft_gate.get("document_intake_draft_gate_preview_ready_for_value_extraction"))
        and original_intake_unchanged
    )
    status = "failed" if all_errors else "passed" if passed else "warning"
    return {
        "status": status,
        "mode": "operator-resolution-chain-preview",
        "synthetic_only": False,
        "operator_resolution_chain_output_dir": _path_value(args.operator_resolution_chain_output_dir),
        "operator_resolution_input": _path_value(args.operator_resolution_input),
        "operator_resolution_source_pack_input": _path_value(args.operator_resolution_source_pack_input),
        "document_intake_input": _path_value(args.document_intake_input),
        "source_intake_input": _path_value(args.source_intake_input),
        "target_reporting_period": str(args.report_period),
        "required_report_type": args.report_type,
        "required_standard": args.accounting_standard,
        "completed_stages": completed_stages,
        "failed_stage": failed_stage,
        "validation_row_count": int(validation.get("operator_resolution_validation_row_count") or 0),
        "validation_valid_count": int(validation.get("operator_resolution_validation_valid_count") or 0),
        "validation_incomplete_count": int(validation.get("operator_resolution_validation_incomplete_count") or 0),
        "validation_invalid_count": int(validation.get("operator_resolution_validation_invalid_count") or 0),
        "apply_preview_row_count": int(apply_preview.get("operator_resolution_apply_preview_row_count") or 0),
        "apply_preview_eligible_count": int(apply_preview.get("operator_resolution_apply_preview_eligible_count") or 0),
        "apply_preview_blocked_count": int(apply_preview.get("operator_resolution_apply_preview_blocked_count") or 0),
        "apply_preview_future_apply_allowed_count": int(
            apply_preview.get("operator_resolution_apply_preview_future_apply_allowed_count") or 0
        ),
        "apply_draft_row_count": int(apply_draft.get("operator_resolution_apply_draft_row_count") or 0),
        "apply_draft_applied_count": int(apply_draft.get("operator_resolution_apply_draft_applied_count") or 0),
        "apply_draft_skipped_count": int(apply_draft.get("operator_resolution_apply_draft_skipped_count") or 0),
        "apply_draft_failed_count": int(apply_draft.get("operator_resolution_apply_draft_failed_count") or 0),
        "draft_gate_row_count": int(draft_gate.get("document_intake_draft_gate_preview_row_count") or 0),
        "draft_gate_ready_count": int(draft_gate.get("document_intake_draft_gate_preview_ready_count") or 0),
        "draft_gate_blocked_count": int(draft_gate.get("document_intake_draft_gate_preview_blocked_count") or 0),
        "draft_gate_placeholder_count": int(draft_gate.get("document_intake_draft_gate_preview_placeholder_count") or 0),
        "draft_gate_passed": bool(draft_gate.get("document_intake_draft_gate_preview_gate_passed")),
        "ready_for_value_extraction": bool(
            draft_gate.get("document_intake_draft_gate_preview_ready_for_value_extraction")
        ),
        "ready_for_import": bool(draft_gate.get("document_intake_draft_gate_preview_ready_for_import")),
        "original_intake_modified": not original_intake_unchanged,
        "draft_intake_created": bool(
            artifacts.get("exact_document_intake_draft_json")
            and artifacts["exact_document_intake_draft_json"].is_file()
        ),
        "artifacts": {key: str(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": all_errors,
        "next_steps": _next_steps("operator-resolution-chain-preview", status),
        "would_extract_values": False,
        "would_import_report": False,
        "would_update_database": False,
        "would_update_original_intake": False,
        **SAFETY_FLAGS,
    }


def run_operator_resolution_chain_review_board(args: argparse.Namespace) -> dict[str, Any]:
    summary_path = _operator_resolution_chain_review_board_summary_path(args)
    if summary_path is None:
        return _failed_operator_resolution_chain_review_board(
            [{"message": "operator_resolution_chain_summary_required"}],
        )
    try:
        chain_summary = _load_json_object(summary_path)
    except (OSError, ValueError, json.JSONDecodeError):
        return _failed_operator_resolution_chain_review_board(
            [{"message": "operator_resolution_chain_summary_required", "path": str(summary_path)}],
        )
    if chain_summary.get("mode") != "operator-resolution-chain-preview":
        return _failed_operator_resolution_chain_review_board(
            [{"message": "operator_resolution_chain_summary_required", "path": str(summary_path)}],
        )

    warnings: list[dict[str, Any]] = []
    stage_paths = _operator_resolution_chain_review_board_stage_paths(summary_path, chain_summary)
    stage_reports: dict[str, dict[str, Any]] = {}
    for stage, path in stage_paths.items():
        try:
            stage_reports[stage] = _load_json_object(path)
        except (OSError, ValueError, json.JSONDecodeError):
            warnings.append({"message": f"chain_stage_artifact_missing:{stage}", "path": str(path)})

    operator_rows: list[dict[str, Any]] = []
    if args.operator_resolution_input is not None:
        try:
            operator_rows, _ = load_operator_resolution_input(args.operator_resolution_input)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            warnings.append({"message": f"operator_resolution_input_unreadable:{exc}"})
    validation_rows = list(
        (stage_reports.get("operator_resolution_validation_json") or {}).get("validation_rows") or []
    )
    source_rows: list[dict[str, Any]] = []
    if args.operator_resolution_source_pack_input is not None:
        try:
            source_rows, _ = load_operator_resolution_input(args.operator_resolution_source_pack_input)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            warnings.append({"message": f"source_pack_unreadable_trusted_hosts_unavailable:{exc}"})
    else:
        warnings.append({"message": "source_pack_missing_trusted_hosts_unavailable"})
    if not operator_rows:
        operator_rows = validation_rows or source_rows

    artifacts = _operator_resolution_chain_review_board_artifacts(args, summary_path)
    collision_errors = _operator_resolution_chain_review_board_collision_errors(
        args,
        summary_path=summary_path,
        stage_paths=stage_paths,
        artifacts=artifacts,
    )
    if collision_errors:
        return _failed_operator_resolution_chain_review_board(collision_errors)

    rows = _build_operator_resolution_chain_review_board_rows(
        chain_summary,
        operator_rows=operator_rows,
        source_rows=source_rows,
        validation_rows=validation_rows,
        patch_rows=list((stage_reports.get("operator_resolution_apply_preview_json") or {}).get("patch_rows") or []),
        apply_draft_rows=list(
            (stage_reports.get("operator_resolution_apply_draft_json") or {}).get("apply_draft_rows") or []
        ),
        draft_gate_rows=list(
            (stage_reports.get("document_intake_draft_gate_summary_json") or {}).get("draft_gate_summary_rows") or []
        ),
        warnings=warnings,
    )
    report = _build_operator_resolution_chain_review_board_report(
        args,
        chain_summary=chain_summary,
        summary_path=summary_path,
        stage_paths=stage_paths,
        artifacts=artifacts,
        rows=rows,
        warnings=warnings,
    )
    try:
        write_json_report(report, artifacts["board_json"])
        write_operator_resolution_chain_review_board_csv(rows, artifacts["board_csv"])
        write_operator_resolution_chain_review_board_markdown(report, artifacts["board_markdown"])
        write_operator_resolution_refill_workspace_csv(rows, artifacts["refill_workspace_csv"])
        write_operator_resolution_chain_rerun_markdown(report, artifacts["rerun_markdown"])
    except OSError as exc:
        report["status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": str(exc)}]
    return report


def _operator_resolution_chain_review_board_summary_path(args: argparse.Namespace) -> Path | None:
    if args.operator_resolution_chain_summary_input is not None:
        return args.operator_resolution_chain_summary_input
    if args.operator_resolution_chain_output_dir is not None:
        return (
            args.operator_resolution_chain_output_dir
            / OPERATOR_RESOLUTION_CHAIN_PREVIEW_ARTIFACT_NAMES["chain_summary_json"]
        )
    return None


def _load_json_object(path: Path) -> dict[str, Any]:
    if not path.is_file():
        raise ValueError(f"JSON input does not exist: {path}")
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise ValueError(f"JSON input must be an object: {path}")
    return payload


def _operator_resolution_chain_review_board_stage_paths(
    summary_path: Path,
    chain_summary: dict[str, Any],
) -> dict[str, Path]:
    artifact_map = chain_summary.get("artifacts") or {}
    keys = (
        "operator_resolution_validation_json",
        "operator_resolution_apply_preview_json",
        "operator_resolution_apply_draft_json",
        "document_intake_draft_gate_summary_json",
    )
    resolved: dict[str, Path] = {}
    for key in keys:
        mapped = artifact_map.get(key)
        mapped_path = Path(str(mapped)) if mapped else None
        if mapped_path is not None and not mapped_path.is_absolute():
            mapped_path = summary_path.parent / mapped_path
        sibling = summary_path.parent / OPERATOR_RESOLUTION_CHAIN_PREVIEW_ARTIFACT_NAMES[key]
        resolved[key] = mapped_path if mapped_path is not None and mapped_path.is_file() else sibling
    return resolved


def _operator_resolution_chain_review_board_artifacts(
    args: argparse.Namespace,
    summary_path: Path,
) -> dict[str, Path]:
    output_dir = args.operator_resolution_chain_output_dir or summary_path.parent
    overrides = {
        "board_json": args.operator_resolution_chain_review_board_output,
        "board_csv": args.operator_resolution_chain_review_board_csv_output,
        "board_markdown": args.operator_resolution_chain_review_board_markdown_output,
        "refill_workspace_csv": args.operator_resolution_refill_workspace_csv_output,
        "rerun_markdown": args.operator_resolution_chain_rerun_markdown_output,
    }
    return {
        key: overrides[key] or output_dir / file_name
        for key, file_name in OPERATOR_RESOLUTION_CHAIN_REVIEW_BOARD_ARTIFACT_NAMES.items()
    }


def _operator_resolution_chain_review_board_collision_errors(
    args: argparse.Namespace,
    *,
    summary_path: Path,
    stage_paths: dict[str, Path],
    artifacts: dict[str, Path],
) -> list[dict[str, Any]]:
    protected_inputs = [
        summary_path,
        *stage_paths.values(),
        *(
            path
            for path in (
                args.operator_resolution_input,
                args.operator_resolution_source_pack_input,
            )
            if path is not None
        ),
    ]
    outputs = [
        *artifacts.values(),
        *(path for path in (args.json_output, args.markdown_output) if path is not None),
    ]
    errors: list[dict[str, Any]] = []
    for output_path in outputs:
        for input_path in protected_inputs:
            if _paths_equal(output_path, input_path):
                errors.append(
                    {
                        "message": "operator_resolution_chain_review_board_output_must_not_equal_input",
                        "output_path": str(output_path),
                        "input_path": str(input_path),
                    }
                )
    return errors


def _failed_operator_resolution_chain_review_board(errors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "status": "failed",
        "mode": "operator-resolution-chain-review-board",
        "row_count": 0,
        "ready_count": 0,
        "blocked_count": 0,
        "needs_operator_action_count": 0,
        "invalid_input_count": 0,
        "draft_gate_blocked_count": 0,
        "ready_for_value_extraction_count": 0,
        "overall_status_counts": {},
        "primary_blocker_counts": {},
        "rows": [],
        "warnings": [],
        "errors": errors,
        "would_extract_values": False,
        "would_import_report": False,
        "would_update_database": False,
        "would_update_original_intake": False,
        **SAFETY_FLAGS,
    }


def _build_operator_resolution_chain_review_board_rows(
    chain_summary: dict[str, Any],
    *,
    operator_rows: list[dict[str, Any]],
    source_rows: list[dict[str, Any]],
    validation_rows: list[dict[str, Any]],
    patch_rows: list[dict[str, Any]],
    apply_draft_rows: list[dict[str, Any]],
    draft_gate_rows: list[dict[str, Any]],
    warnings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    source_by_id = _rows_by_resolution_id(source_rows)
    validation_by_id = _rows_by_resolution_id(validation_rows)
    patch_by_id = _rows_by_resolution_id(patch_rows)
    apply_draft_by_id = _rows_by_resolution_id(apply_draft_rows)
    gate_by_company = {_company_key(row): row for row in draft_gate_rows if _company_key(row)}
    base_by_id = _rows_by_resolution_id(operator_rows)
    ordered_ids = list(base_by_id)
    for row_map in (validation_by_id, patch_by_id, apply_draft_by_id, source_by_id):
        for resolution_id in row_map:
            if resolution_id not in ordered_ids:
                ordered_ids.append(resolution_id)
    rows: list[dict[str, Any]] = []
    for resolution_id in ordered_ids:
        base = {
            **source_by_id.get(resolution_id, {}),
            **validation_by_id.get(resolution_id, {}),
            **base_by_id.get(resolution_id, {}),
        }
        validation = validation_by_id.get(resolution_id, {})
        patch = patch_by_id.get(resolution_id, {})
        apply_draft = apply_draft_by_id.get(resolution_id, {})
        gate = gate_by_company.get(_company_key(base), {})
        overall_status = _operator_resolution_chain_review_board_overall_status(
            chain_summary,
            base=base,
            validation=validation,
            patch=patch,
            apply_draft=apply_draft,
            gate=gate,
        )
        blocker = _operator_resolution_chain_review_board_primary_blocker(
            chain_summary,
            overall_status=overall_status,
            validation=validation,
            patch=patch,
            apply_draft=apply_draft,
            gate=gate,
        )
        trusted_hosts = _operator_resolution_chain_review_board_trusted_hosts(
            source_by_id.get(resolution_id, {})
        )
        guidance = _operator_resolution_chain_review_board_guidance(
            overall_status,
            blocker=blocker,
            trusted_hosts=trusted_hosts,
        )
        row = {
            "resolution_id": resolution_id,
            "company_id": base.get("company_id") or "",
            "company_name": base.get("company_name") or "",
            "canonical_company_id": base.get("canonical_company_id") or base.get("company_id") or "",
            "canonical_company_name": base.get("canonical_company_name") or base.get("company_name") or "",
            "target_reporting_period": base.get("target_reporting_period") or chain_summary.get("target_reporting_period") or "",
            "required_report_type": base.get("required_report_type") or chain_summary.get("required_report_type") or "",
            "required_standard": base.get("required_standard") or chain_summary.get("required_standard") or "",
            "resolution_action_type": base.get("resolution_action_type") or "",
            "overall_status": overall_status,
            "primary_blocker": blocker,
            **guidance,
            "validation_status": validation.get("validation_status") or "",
            "validation_reason_codes": _review_board_list(validation.get("validation_reason_codes")),
            "validation_errors": _review_board_list(validation.get("validation_errors")),
            "validation_warnings": _review_board_list(validation.get("validation_warnings")),
            "apply_preview_status": patch.get("patch_status") or "",
            "apply_preview_action": patch.get("patch_action") or "",
            "future_apply_allowed": _operator_resolution_bool(patch.get("future_apply_allowed")),
            "future_apply_blocked_reason": patch.get("future_apply_blocked_reason") or "",
            "apply_draft_status": apply_draft.get("apply_draft_status") or "",
            "apply_draft_action": apply_draft.get("apply_draft_action") or "",
            "draft_gate_status": gate.get("draft_row_status") or "",
            "draft_gate_blocked_reason_codes": _review_board_list(gate.get("blocked_reason_codes")),
            "ready_for_value_extraction": bool(gate.get("ready_for_value_extraction")),
            "ready_for_import": bool(gate.get("ready_for_import")),
            "trusted_source_hosts": trusted_hosts,
            "latest_historical_document_url": source_by_id.get(resolution_id, {}).get(
                "latest_historical_document_url"
            )
            or base.get("latest_historical_document_url")
            or "",
            "latest_historical_period": source_by_id.get(resolution_id, {}).get("latest_historical_period")
            or base.get("latest_historical_period")
            or "",
            "historical_fallback_allowed_as_target_evidence": False,
            "would_update_document_intake": False,
            "would_update_original_intake": False,
            "would_update_database": False,
            "would_promote_seed": False,
            "would_extract_values": False,
            "would_import_report": False,
            "would_mutate_scores": False,
            "would_trigger_paper_trading": False,
        }
        for field in (
            "operator_fill_decision",
            "operator_fill_exact_document_url",
            "operator_fill_document_title",
            "operator_fill_document_date",
            "operator_fill_source_page_url",
            "operator_fill_source_type",
            "operator_fill_report_period",
            "operator_fill_report_type",
            "operator_fill_accounting_standard",
            "operator_fill_notes",
        ):
            row[field] = base.get(field) or ""
        row["operator_fill_report_period"] = row["operator_fill_report_period"] or row["target_reporting_period"]
        row["operator_fill_report_type"] = row["operator_fill_report_type"] or row["required_report_type"]
        row["operator_fill_accounting_standard"] = (
            row["operator_fill_accounting_standard"] or row["required_standard"]
        )
        rows.append(row)
    if not source_rows and not any(
        warning.get("message") == "source_pack_missing_trusted_hosts_unavailable"
        for warning in warnings
    ):
        warnings.append({"message": "source_pack_missing_trusted_hosts_unavailable"})
    return sorted(rows, key=lambda row: str(row.get("resolution_id") or ""))


def _rows_by_resolution_id(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    return {
        str(row.get("resolution_id") or ""): row
        for row in rows
        if str(row.get("resolution_id") or "")
    }


def _review_board_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item) for item in value if str(item)]
    return [item.strip() for item in str(value or "").split(";") if item.strip()]


def _operator_resolution_chain_review_board_trusted_hosts(source_row: dict[str, Any]) -> list[str]:
    hosts: set[str] = set()
    for field in ("current_known_document_url", "current_known_source_page_url"):
        for item in _split_source_context_urls(str(source_row.get(field) or "")):
            parsed = urllib.parse.urlparse(item)
            if parsed.scheme in {"http", "https"} and parsed.netloc:
                host = _host(item)
                if host:
                    hosts.add(host)
    return sorted(hosts)


def _operator_resolution_chain_review_board_overall_status(
    chain_summary: dict[str, Any],
    *,
    base: dict[str, Any],
    validation: dict[str, Any],
    patch: dict[str, Any],
    apply_draft: dict[str, Any],
    gate: dict[str, Any],
) -> str:
    if chain_summary.get("failed_stage"):
        return "chain_stage_failed"
    if gate.get("draft_row_status") == "draft_ready_for_future_extraction_preview":
        return "ready_for_future_extraction_preview"
    validation_status = str(validation.get("validation_status") or "")
    if validation_status == "incomplete_operator_input" and not str(base.get("operator_fill_exact_document_url") or ""):
        return "needs_operator_exact_document_url"
    if validation_status == "invalid_operator_input":
        return "operator_input_invalid"
    if validation_status == "waiting" or (
        validation_status == "valid_for_future_controlled_intake_review"
        and (not patch or not apply_draft or not gate)
    ):
        return "validated_waiting_for_apply_review"
    if patch and patch.get("patch_status") != "eligible_for_future_controlled_apply":
        return "apply_preview_blocked"
    if patch.get("patch_status") == "eligible_for_future_controlled_apply" and not str(
        apply_draft.get("apply_draft_status") or ""
    ).startswith("draft_applied_"):
        return "draft_apply_blocked"
    if str(apply_draft.get("apply_draft_status") or "").startswith("draft_applied_") and gate.get(
        "draft_row_status"
    ) != "draft_ready_for_future_extraction_preview":
        return "draft_gate_blocked"
    return "unknown_chain_state"


def _operator_resolution_chain_review_board_primary_blocker(
    chain_summary: dict[str, Any],
    *,
    overall_status: str,
    validation: dict[str, Any],
    patch: dict[str, Any],
    apply_draft: dict[str, Any],
    gate: dict[str, Any],
) -> str:
    if overall_status == "chain_stage_failed":
        return str(chain_summary.get("failed_stage") or "chain_stage_failed")
    if overall_status == "ready_for_future_extraction_preview":
        return ""
    validation_reasons = _review_board_list(validation.get("validation_reason_codes"))
    validation_errors = _review_board_list(validation.get("validation_errors"))
    if "historical_fallback_url_used_as_exact_document" in [*validation_errors, *validation_reasons]:
        return "historical_fallback_url_used_as_exact_document"
    if overall_status == "needs_operator_exact_document_url":
        return "missing_exact_document_url"
    if overall_status == "operator_input_invalid":
        return next(iter(validation_errors or validation_reasons), "invalid_operator_input")
    if overall_status == "apply_preview_blocked":
        return str(patch.get("future_apply_blocked_reason") or patch.get("patch_status") or "apply_preview_blocked")
    if overall_status == "draft_apply_blocked":
        return str(apply_draft.get("apply_draft_status") or "draft_apply_blocked")
    if overall_status == "draft_gate_blocked":
        return next(iter(_review_board_list(gate.get("blocked_reason_codes"))), "quality_gate_failed")
    if overall_status == "validated_waiting_for_apply_review":
        return "waiting_for_downstream_review"
    return "unknown_chain_state"


def _operator_resolution_chain_review_board_guidance(
    overall_status: str,
    *,
    blocker: str,
    trusted_hosts: list[str],
) -> dict[str, str]:
    trusted = ", ".join(trusted_hosts) if trusted_hosts else "baseline trusted hosts unavailable"
    safe_fill_hint = (
        f"Use an exact official target-period annual IFRS PDF from: {trusted}. "
        "Historical fallback is diagnostic-only and forbidden as target evidence."
    )
    if overall_status == "needs_operator_exact_document_url":
        action = "fill_exact_official_target_period_annual_ifrs_url"
        instruction = (
            "Find and paste the exact official target-period annual IFRS report URL. "
            "Do not paste a landing page, bond prospectus, RAS report, interim report, or historical fallback."
        )
    elif blocker == "historical_fallback_url_used_as_exact_document":
        action = "replace_forbidden_historical_fallback_url"
        instruction = (
            "Do not use latest_historical_document_url as target-period evidence. "
            "Historical fallback is diagnostic-only."
        )
    elif overall_status == "operator_input_invalid":
        action = "correct_invalid_operator_input"
        instruction = "Replace the input with an exact official target-period annual IFRS report URL."
    elif overall_status == "ready_for_future_extraction_preview":
        action = "no_operator_action_required"
        instruction = (
            "No manual correction required. The row is ready for future extraction preview, "
            "but no extraction, import, scoring, or trading has executed."
        )
    elif overall_status == "chain_stage_failed":
        action = "fix_chain_inputs_and_rerun_task124"
        instruction = "Fix the failed Task124 stage inputs, then rerun the preview chain."
    else:
        action = "review_chain_blocker_and_rerun_task124"
        instruction = f"Review blocker `{blocker}` and rerun the preview chain after correction."
    return {
        "next_required_action": action,
        "operator_instruction": instruction,
        "safe_fill_hint": safe_fill_hint,
        "rerun_hint": "Edit the Task125 refill workspace CSV, then rerun Task119 validation and Task124 chain preview.",
    }


def _build_operator_resolution_chain_review_board_report(
    args: argparse.Namespace,
    *,
    chain_summary: dict[str, Any],
    summary_path: Path,
    stage_paths: dict[str, Path],
    artifacts: dict[str, Path],
    rows: list[dict[str, Any]],
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    ready_count = sum(1 for row in rows if row.get("overall_status") == "ready_for_future_extraction_preview")
    blocked_count = len(rows) - ready_count
    status = "passed" if rows and ready_count == len(rows) and not warnings else "warning"
    return {
        "status": status,
        "mode": "operator-resolution-chain-review-board",
        "operator_resolution_chain_summary_input": str(summary_path),
        "operator_resolution_input": _path_value(args.operator_resolution_input),
        "operator_resolution_source_pack_input": _path_value(args.operator_resolution_source_pack_input),
        "document_intake_input": chain_summary.get("document_intake_input"),
        "source_intake_input": chain_summary.get("source_intake_input"),
        "row_count": len(rows),
        "ready_count": ready_count,
        "blocked_count": blocked_count,
        "needs_operator_action_count": sum(
            1 for row in rows if row.get("overall_status") == "needs_operator_exact_document_url"
        ),
        "invalid_input_count": sum(1 for row in rows if row.get("overall_status") == "operator_input_invalid"),
        "draft_gate_blocked_count": sum(1 for row in rows if row.get("overall_status") == "draft_gate_blocked"),
        "ready_for_value_extraction_count": sum(1 for row in rows if row.get("ready_for_value_extraction")),
        "overall_status_counts": _count_by_key(rows, "overall_status"),
        "primary_blocker_counts": _count_by_key(rows, "primary_blocker"),
        "rows": rows,
        "stage_artifacts": {key: str(path) for key, path in stage_paths.items()},
        "artifacts": {key: str(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": [],
        "next_steps": _next_steps("operator-resolution-chain-review-board", status),
        "would_extract_values": False,
        "would_import_report": False,
        "would_update_database": False,
        "would_update_original_intake": False,
        **SAFETY_FLAGS,
    }


def run_operator_resolution_source_trust_workspace(args: argparse.Namespace) -> dict[str, Any]:
    board_path = _operator_resolution_source_trust_board_path(args)
    if board_path is None:
        return _failed_operator_resolution_source_trust_workspace(
            [{"message": "operator_resolution_chain_review_board_required"}],
        )
    try:
        board_report = _load_json_object(board_path)
    except (OSError, ValueError, json.JSONDecodeError):
        return _failed_operator_resolution_source_trust_workspace(
            [{"message": "operator_resolution_chain_review_board_required", "path": str(board_path)}],
        )
    board_rows = board_report.get("rows")
    if board_report.get("mode") != "operator-resolution-chain-review-board" or not isinstance(board_rows, list):
        return _failed_operator_resolution_source_trust_workspace(
            [{"message": "operator_resolution_chain_review_board_required", "path": str(board_path)}],
        )

    warnings: list[dict[str, Any]] = []
    source_rows: list[dict[str, Any]] = []
    if args.operator_resolution_source_pack_input is not None:
        try:
            source_rows, _ = load_operator_resolution_input(args.operator_resolution_source_pack_input)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            warnings.append({"message": f"source_pack_unreadable_trusted_hosts_unavailable:{exc}"})
    else:
        warnings.append({"message": "source_pack_missing_trusted_hosts_unavailable"})

    artifacts = _operator_resolution_source_trust_artifacts(args, board_path)
    collision_errors = _operator_resolution_source_trust_collision_errors(
        args,
        board_path=board_path,
        artifacts=artifacts,
    )
    if collision_errors:
        return _failed_operator_resolution_source_trust_workspace(collision_errors)

    rows = _build_operator_resolution_source_trust_rows(
        board_rows=board_rows,
        source_rows=source_rows,
        source_pack_provided=args.operator_resolution_source_pack_input is not None,
    )
    report = _build_operator_resolution_source_trust_report(
        args,
        board_path=board_path,
        artifacts=artifacts,
        rows=rows,
        warnings=warnings,
    )
    try:
        write_json_report(report, artifacts["workspace_json"])
        write_operator_resolution_source_trust_csv(rows, artifacts["workspace_csv"])
        write_operator_resolution_source_trust_markdown(report, artifacts["workspace_markdown"])
        write_operator_resolution_source_trust_refill_csv(rows, artifacts["refill_csv"])
        write_operator_resolution_source_trust_rerun_markdown(report, artifacts["rerun_markdown"])
    except OSError as exc:
        report["status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": str(exc)}]
    return report


def _operator_resolution_source_trust_board_path(args: argparse.Namespace) -> Path | None:
    if args.operator_resolution_chain_review_board_input is not None:
        return args.operator_resolution_chain_review_board_input
    if args.operator_resolution_chain_output_dir is not None:
        return (
            args.operator_resolution_chain_output_dir
            / OPERATOR_RESOLUTION_CHAIN_REVIEW_BOARD_ARTIFACT_NAMES["board_json"]
        )
    return None


def _operator_resolution_source_trust_artifacts(
    args: argparse.Namespace,
    board_path: Path,
) -> dict[str, Path]:
    output_dir = args.operator_resolution_chain_output_dir or board_path.parent
    overrides = {
        "workspace_json": args.operator_resolution_source_trust_output,
        "workspace_csv": args.operator_resolution_source_trust_csv_output,
        "workspace_markdown": args.operator_resolution_source_trust_markdown_output,
        "refill_csv": args.operator_resolution_source_trust_refill_csv_output,
        "rerun_markdown": args.operator_resolution_source_trust_rerun_markdown_output,
    }
    return {
        key: overrides[key] or output_dir / file_name
        for key, file_name in OPERATOR_RESOLUTION_SOURCE_TRUST_ARTIFACT_NAMES.items()
    }


def _operator_resolution_source_trust_collision_errors(
    args: argparse.Namespace,
    *,
    board_path: Path,
    artifacts: dict[str, Path],
) -> list[dict[str, Any]]:
    protected_inputs = [
        board_path,
        *(
            path
            for path in (args.operator_resolution_source_pack_input,)
            if path is not None
        ),
    ]
    outputs = [
        *artifacts.values(),
        *(path for path in (args.json_output, args.markdown_output) if path is not None),
    ]
    errors: list[dict[str, Any]] = []
    for output_path in outputs:
        for input_path in protected_inputs:
            if _paths_equal(output_path, input_path):
                errors.append(
                    {
                        "message": "operator_resolution_source_trust_output_must_not_equal_input",
                        "output_path": str(output_path),
                        "input_path": str(input_path),
                    }
                )
    return errors


def _failed_operator_resolution_source_trust_workspace(errors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "status": "failed",
        "mode": "operator-resolution-source-trust-workspace",
        "row_count": 0,
        "trusted_source_available_count": 0,
        "trusted_source_missing_count": 0,
        "trusted_source_needs_review_count": 0,
        "trusted_source_conflict_count": 0,
        "needs_baseline_source_context_count": 0,
        "ready_for_document_url_refill_count": 0,
        "source_trust_status_counts": {},
        "rows": [],
        "warnings": [],
        "errors": errors,
        "would_update_source_pack": False,
        "would_update_operator_pack": False,
        "would_update_original_intake": False,
        "would_update_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        **SAFETY_FLAGS,
    }


def _build_operator_resolution_source_trust_rows(
    *,
    board_rows: list[dict[str, Any]],
    source_rows: list[dict[str, Any]],
    source_pack_provided: bool,
) -> list[dict[str, Any]]:
    source_by_id = _rows_by_resolution_id(source_rows)
    source_by_company = {_company_key(row): row for row in source_rows if _company_key(row)}
    rows: list[dict[str, Any]] = []
    for board_row in board_rows:
        resolution_id = str(board_row.get("resolution_id") or "")
        source_row = source_by_id.get(resolution_id) or source_by_company.get(_company_key(board_row)) or {}
        trusted_urls = _operator_resolution_source_trust_urls(source_row)
        trusted_hosts = sorted({_host(url) for url in trusted_urls if _host(url)})
        historical_url = str(
            source_row.get("latest_historical_document_url")
            or board_row.get("latest_historical_document_url")
            or ""
        )
        historical_period = str(
            source_row.get("latest_historical_period")
            or board_row.get("latest_historical_period")
            or ""
        )
        reason_codes = _operator_resolution_source_trust_reason_codes(
            board_row=board_row,
            source_row=source_row,
            trusted_urls=trusted_urls,
            historical_url=historical_url,
            source_pack_provided=source_pack_provided,
        )
        status = _operator_resolution_source_trust_status(
            board_row=board_row,
            source_row=source_row,
            trusted_urls=trusted_urls,
            historical_url=historical_url,
        )
        guidance = _operator_resolution_source_trust_guidance(
            status,
            trusted_hosts=trusted_hosts,
        )
        rows.append(
            {
                "resolution_id": resolution_id,
                "company_id": board_row.get("company_id") or source_row.get("company_id") or "",
                "company_name": board_row.get("company_name") or source_row.get("company_name") or "",
                "canonical_company_id": board_row.get("canonical_company_id")
                or source_row.get("canonical_company_id")
                or board_row.get("company_id")
                or source_row.get("company_id")
                or "",
                "canonical_company_name": board_row.get("canonical_company_name")
                or source_row.get("canonical_company_name")
                or board_row.get("company_name")
                or source_row.get("company_name")
                or "",
                "target_reporting_period": board_row.get("target_reporting_period") or "",
                "required_report_type": board_row.get("required_report_type") or "",
                "required_standard": board_row.get("required_standard") or "",
                "source_trust_status": status,
                "source_trust_severity": "info"
                if status in {"trusted_source_available", "ready_for_document_url_refill"}
                else "warning",
                "trusted_source_hosts": trusted_hosts,
                "trusted_source_urls": trusted_urls,
                "trusted_source_status_reason_codes": reason_codes,
                "current_known_source_page_url": source_row.get("current_known_source_page_url") or "",
                "current_known_document_url": source_row.get("current_known_document_url") or "",
                "latest_historical_document_url": historical_url,
                "latest_historical_period": historical_period,
                "historical_fallback_allowed_as_trusted_source": False,
                "historical_fallback_allowed_as_target_evidence": False,
                "operator_fill_source_page_url": board_row.get("operator_fill_source_page_url") or "",
                "operator_fill_exact_document_url": board_row.get("operator_fill_exact_document_url") or "",
                "review_board_overall_status": board_row.get("overall_status") or "",
                "review_board_primary_blocker": board_row.get("primary_blocker") or "",
                "review_board_next_required_action": board_row.get("next_required_action") or "",
                **guidance,
                "ready_for_exact_document_url_refill": status == "ready_for_document_url_refill",
                "needs_baseline_source_context": status in {"trusted_source_missing", "trusted_source_conflict"},
                "needs_operator_source_review": status
                in {"trusted_source_missing", "trusted_source_needs_review", "trusted_source_conflict"},
                "would_update_source_pack": False,
                "would_update_operator_pack": False,
                "would_update_original_intake": False,
                "would_update_database": False,
                "would_extract_values": False,
                "would_import_report": False,
                "would_mutate_scores": False,
                "would_trigger_paper_trading": False,
            }
        )
    return sorted(rows, key=lambda row: str(row.get("resolution_id") or ""))


def _operator_resolution_source_trust_urls(source_row: dict[str, Any]) -> list[str]:
    urls: set[str] = set()
    for field in (
        "current_known_source_page_url",
        "current_known_document_url",
        "official_source_url",
        "source_url",
    ):
        for item in _split_source_context_urls(str(source_row.get(field) or "")):
            parsed = urllib.parse.urlparse(item)
            if parsed.scheme in {"http", "https"} and parsed.netloc:
                urls.add(item)
    return sorted(urls)


def _operator_resolution_source_trust_status(
    *,
    board_row: dict[str, Any],
    source_row: dict[str, Any],
    trusted_urls: list[str],
    historical_url: str,
) -> str:
    domains = {_source_trust_registrable_domain(_host(url)) for url in trusted_urls}
    domains.discard("")
    if len(domains) > 1 or (not trusted_urls and historical_url):
        return "trusted_source_conflict"
    if not trusted_urls:
        return "trusted_source_missing"
    if _source_trust_has_archive_or_history_url(trusted_urls) or _operator_resolution_source_trust_requires_review(
        board_row,
        source_row,
    ):
        return "trusted_source_needs_review"
    if not str(board_row.get("operator_fill_exact_document_url") or ""):
        return "ready_for_document_url_refill"
    return "trusted_source_available"


def _operator_resolution_source_trust_reason_codes(
    *,
    board_row: dict[str, Any],
    source_row: dict[str, Any],
    trusted_urls: list[str],
    historical_url: str,
    source_pack_provided: bool,
) -> list[str]:
    reasons: list[str] = []
    domains = {_source_trust_registrable_domain(_host(url)) for url in trusted_urls}
    domains.discard("")
    if trusted_urls:
        reasons.append("baseline_trusted_source_available")
    else:
        reasons.append("baseline_trusted_source_missing")
    if len(domains) > 1:
        reasons.append("baseline_source_domain_conflict")
    if _source_trust_has_archive_or_history_url(trusted_urls):
        reasons.append("archive_or_history_baseline_source_needs_review")
    if historical_url:
        if not trusted_urls:
            reasons.append("historical_fallback_only_not_trusted_source")
        reasons.append("historical_fallback_diagnostic_only")
    if board_row.get("operator_fill_source_page_url") or board_row.get("operator_fill_exact_document_url"):
        reasons.append("manual_operator_fill_urls_not_trusted")
    if not source_pack_provided:
        reasons.append("source_pack_missing_trusted_hosts_unavailable")
    if _operator_resolution_source_trust_requires_review(board_row, source_row):
        reasons.append("operator_source_review_required")
    return list(dict.fromkeys(reasons))


def _source_trust_registrable_domain(host: str) -> str:
    labels = [label for label in host.casefold().strip(".").split(".") if label]
    if len(labels) <= 2:
        return ".".join(labels)
    suffix = ".".join(labels[-2:])
    if suffix in SOURCE_TRUST_TWO_PART_PUBLIC_SUFFIXES and len(labels) >= 3:
        return ".".join(labels[-3:])
    return suffix


def _source_trust_has_archive_or_history_url(urls: list[str]) -> bool:
    pattern = re.compile(r"(?:^|[./_-])(archive|archives|history|historical|old)(?:[./?&=_-]|$)", re.IGNORECASE)
    return any(pattern.search(url) for url in urls)


def _operator_resolution_source_trust_requires_review(
    board_row: dict[str, Any],
    source_row: dict[str, Any],
) -> bool:
    return bool(
        _operator_resolution_bool(source_row.get("requires_official_seed_review"))
        or board_row.get("resolution_action_type") == "review_or_promote_official_seed"
        or "source_review" in str(board_row.get("next_required_action") or "").casefold()
    )


def _operator_resolution_source_trust_guidance(
    status: str,
    *,
    trusted_hosts: list[str],
) -> dict[str, str]:
    trusted = ", ".join(trusted_hosts) if trusted_hosts else "baseline trusted hosts unavailable"
    safe_source_fill_hint = (
        "Paste an official issuer reporting, investor-relations, or official disclosure page for later controlled review. "
        "Manual URLs do not become trusted automatically."
    )
    safe_document_fill_hint = (
        f"Use an exact official target-period annual IFRS PDF from baseline hosts: {trusted}. "
        "Historical fallback is diagnostic-only."
    )
    if status == "trusted_source_conflict":
        action = "review_or_replace_conflicting_baseline_source_context"
        instruction = (
            "Review baseline source context before filling an exact document URL. "
            "Historical-only fallback and conflicting official domains cannot establish trusted source context."
        )
    elif status == "trusted_source_missing":
        action = "fill_official_baseline_source_page_for_future_review"
        instruction = (
            "Fill an official issuer reporting or disclosure page in the source trust refill CSV. "
            "A later controlled validation/merge task must review it before it becomes trusted."
        )
    elif status == "trusted_source_needs_review":
        action = "review_baseline_source_context"
        instruction = (
            "Review the baseline source context before document refill. Archive/history context is not automatically trusted "
            "for the current target report."
        )
    elif status == "ready_for_document_url_refill":
        action = "fill_exact_official_target_period_annual_ifrs_url"
        instruction = (
            "Baseline trusted source context is available. Fill the exact official target-period annual IFRS document URL."
        )
    else:
        action = "no_baseline_source_refill_required"
        instruction = "Baseline trusted source context is available. No source-context refill is required."
    return {
        "next_required_action": action,
        "operator_instruction": instruction,
        "safe_source_fill_hint": safe_source_fill_hint,
        "safe_document_fill_hint": safe_document_fill_hint,
    }


def _build_operator_resolution_source_trust_report(
    args: argparse.Namespace,
    *,
    board_path: Path,
    artifacts: dict[str, Path],
    rows: list[dict[str, Any]],
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    allowed_statuses = {"trusted_source_available", "ready_for_document_url_refill"}
    status = "passed" if rows and all(row.get("source_trust_status") in allowed_statuses for row in rows) and not warnings else "warning"
    return {
        "status": status,
        "mode": "operator-resolution-source-trust-workspace",
        "operator_resolution_chain_review_board_input": str(board_path),
        "operator_resolution_source_pack_input": _path_value(args.operator_resolution_source_pack_input),
        "row_count": len(rows),
        "trusted_source_available_count": sum(1 for row in rows if row.get("trusted_source_hosts")),
        "trusted_source_missing_count": sum(1 for row in rows if row.get("source_trust_status") == "trusted_source_missing"),
        "trusted_source_needs_review_count": sum(
            1 for row in rows if row.get("source_trust_status") == "trusted_source_needs_review"
        ),
        "trusted_source_conflict_count": sum(
            1 for row in rows if row.get("source_trust_status") == "trusted_source_conflict"
        ),
        "needs_baseline_source_context_count": sum(1 for row in rows if row.get("needs_baseline_source_context")),
        "ready_for_document_url_refill_count": sum(
            1 for row in rows if row.get("ready_for_exact_document_url_refill")
        ),
        "source_trust_status_counts": _count_by_key(rows, "source_trust_status"),
        "rows": rows,
        "artifacts": {key: str(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": [],
        "next_steps": _next_steps("operator-resolution-source-trust-workspace", status),
        "would_update_source_pack": False,
        "would_update_operator_pack": False,
        "would_update_original_intake": False,
        "would_update_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        **SAFETY_FLAGS,
    }


def run_operator_resolution_source_trust_refill_validate(args: argparse.Namespace) -> dict[str, Any]:
    refill_path = args.operator_resolution_source_trust_refill_input
    if refill_path is None:
        return _failed_operator_resolution_source_trust_refill_validate(
            [{"message": "operator_resolution_source_trust_refill_input_required"}],
        )
    try:
        refill_rows, _ = load_operator_resolution_input(refill_path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return _failed_operator_resolution_source_trust_refill_validate(
            [{"message": f"operator_resolution_source_trust_refill_input_unreadable:{exc}"}],
        )

    warnings: list[dict[str, Any]] = []
    board_path = _operator_resolution_source_trust_refill_board_path(args)
    board_rows: list[dict[str, Any]] = []
    if board_path is not None and board_path.is_file():
        try:
            board_report = _load_json_object(board_path)
            candidate_rows = board_report.get("rows")
            if board_report.get("mode") != "operator-resolution-chain-review-board" or not isinstance(
                candidate_rows,
                list,
            ):
                raise ValueError("Task125 review board JSON is malformed")
            board_rows = candidate_rows
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            warnings.append({"message": f"review_board_context_unreadable:{exc}"})
    else:
        warnings.append({"message": "review_board_context_missing"})

    source_pack_payload: Any = {"status": "warning", "mode": "operator-resolution-pack", "resolutions": []}
    source_rows: list[dict[str, Any]] = []
    source_pack_original_bytes: bytes | None = None
    if args.operator_resolution_source_pack_input is not None:
        try:
            source_pack_original_bytes = args.operator_resolution_source_pack_input.read_bytes()
            source_pack_payload, source_rows = _load_operator_resolution_source_pack_payload(
                args.operator_resolution_source_pack_input,
            )
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            warnings.append({"message": f"source_pack_unreadable:{exc}"})
    else:
        warnings.append({"message": "source_pack_missing"})

    artifacts = _operator_resolution_source_trust_refill_artifacts(args, refill_path)
    collision_errors = _operator_resolution_source_trust_refill_collision_errors(
        args,
        refill_path=refill_path,
        board_path=board_path,
        artifacts=artifacts,
    )
    if collision_errors:
        return _failed_operator_resolution_source_trust_refill_validate(collision_errors)

    validation_rows = _build_operator_resolution_source_trust_validation_rows(
        refill_rows=refill_rows,
        source_rows=source_rows,
        board_rows=board_rows,
    )
    patch_rows = _build_operator_resolution_source_trust_patch_rows(
        validation_rows=validation_rows,
        source_rows=source_rows,
    )
    draft_rows = _build_operator_resolution_source_pack_draft_rows(
        source_rows=source_rows,
        patch_rows=patch_rows,
    )
    patch_report = _build_operator_resolution_source_trust_patch_report(
        patch_rows=patch_rows,
        artifacts=artifacts,
        warnings=warnings,
    )
    report = _build_operator_resolution_source_trust_validation_report(
        args,
        refill_path=refill_path,
        board_path=board_path,
        artifacts=artifacts,
        rows=validation_rows,
        patch_report=patch_report,
        warnings=warnings,
    )
    try:
        write_json_report(report, artifacts["validation_json"])
        write_operator_resolution_source_trust_validation_csv(validation_rows, artifacts["validation_csv"])
        write_operator_resolution_source_trust_validation_markdown(report, artifacts["validation_markdown"])
        write_json_report(patch_report, artifacts["patch_preview_json"])
        write_operator_resolution_source_trust_patch_preview_csv(patch_rows, artifacts["patch_preview_csv"])
        write_operator_resolution_source_trust_patch_preview_markdown(
            patch_report,
            artifacts["patch_preview_markdown"],
        )
        write_operator_resolution_source_pack_draft_json(
            source_pack_payload,
            draft_rows,
            artifacts["source_pack_draft_json"],
        )
        write_operator_resolution_source_pack_draft_csv(draft_rows, artifacts["source_pack_draft_csv"])
    except OSError as exc:
        report["status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": str(exc)}]

    source_pack_path = args.operator_resolution_source_pack_input
    if (
        source_pack_path is not None
        and source_pack_original_bytes is not None
        and source_pack_path.is_file()
        and source_pack_path.read_bytes() != source_pack_original_bytes
    ):
        report["status"] = "failed"
        report["original_source_pack_modified"] = True
        report["errors"] = [
            *report.get("errors", []),
            {"message": "operator_resolution_source_pack_was_modified"},
        ]
    return report


def _operator_resolution_source_trust_refill_board_path(args: argparse.Namespace) -> Path | None:
    if args.operator_resolution_chain_review_board_input is not None:
        return args.operator_resolution_chain_review_board_input
    if args.operator_resolution_chain_output_dir is not None:
        return (
            args.operator_resolution_chain_output_dir
            / OPERATOR_RESOLUTION_CHAIN_REVIEW_BOARD_ARTIFACT_NAMES["board_json"]
        )
    return None


def _operator_resolution_source_trust_refill_artifacts(
    args: argparse.Namespace,
    refill_path: Path,
) -> dict[str, Path]:
    output_dir = args.operator_resolution_chain_output_dir or refill_path.parent
    overrides = {
        "validation_json": args.operator_resolution_source_trust_validation_output,
        "validation_csv": args.operator_resolution_source_trust_validation_csv_output,
        "validation_markdown": args.operator_resolution_source_trust_validation_markdown_output,
        "patch_preview_json": args.operator_resolution_source_trust_patch_preview_output,
        "patch_preview_csv": args.operator_resolution_source_trust_patch_preview_csv_output,
        "patch_preview_markdown": args.operator_resolution_source_trust_patch_preview_markdown_output,
        "source_pack_draft_json": args.operator_resolution_source_pack_draft_output,
        "source_pack_draft_csv": args.operator_resolution_source_pack_draft_csv_output,
    }
    return {
        key: overrides[key] or output_dir / file_name
        for key, file_name in OPERATOR_RESOLUTION_SOURCE_TRUST_REFILL_ARTIFACT_NAMES.items()
    }


def _operator_resolution_source_trust_refill_collision_errors(
    args: argparse.Namespace,
    *,
    refill_path: Path,
    board_path: Path | None,
    artifacts: dict[str, Path],
) -> list[dict[str, Any]]:
    protected_inputs = [
        refill_path,
        *(
            path
            for path in (
                args.operator_resolution_source_pack_input,
                board_path,
            )
            if path is not None
        ),
    ]
    outputs = [
        *artifacts.values(),
        *(path for path in (args.json_output, args.markdown_output) if path is not None),
    ]
    errors: list[dict[str, Any]] = []
    for output_path in outputs:
        for input_path in protected_inputs:
            if _paths_equal(output_path, input_path):
                errors.append(
                    {
                        "message": "operator_resolution_source_trust_refill_output_must_not_equal_input",
                        "output_path": str(output_path),
                        "input_path": str(input_path),
                    }
                )
    return errors


def _load_operator_resolution_source_pack_payload(path: Path) -> tuple[Any, list[dict[str, Any]]]:
    if path.suffix.lower() != ".json":
        rows, _ = load_operator_resolution_input(path)
        return {"status": "warning", "mode": "operator-resolution-pack", "resolutions": rows}, rows
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if isinstance(payload, dict):
        rows = payload.get("resolutions")
        if rows is None:
            rows = payload.get("rows")
    else:
        rows = payload
    if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
        raise ValueError("operator resolution source pack JSON must be a list or object with resolutions/rows")
    return payload, copy.deepcopy(rows)


def _build_operator_resolution_source_trust_validation_rows(
    *,
    refill_rows: list[dict[str, Any]],
    source_rows: list[dict[str, Any]],
    board_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    source_by_id = _rows_by_resolution_id(source_rows)
    source_by_company = {_company_key(row): row for row in source_rows if _company_key(row)}
    board_by_id = _rows_by_resolution_id(board_rows)
    board_by_company = {_company_key(row): row for row in board_rows if _company_key(row)}
    rows: list[dict[str, Any]] = []
    for refill_row in refill_rows:
        resolution_id = str(refill_row.get("resolution_id") or "")
        source_row = source_by_id.get(resolution_id) or source_by_company.get(_company_key(refill_row)) or {}
        board_row = board_by_id.get(resolution_id) or board_by_company.get(_company_key(refill_row)) or {}
        rows.append(
            _build_operator_resolution_source_trust_validation_row(
                refill_row=refill_row,
                source_row=source_row,
                board_row=board_row,
            )
        )
    return sorted(rows, key=lambda row: str(row.get("resolution_id") or ""))


def _build_operator_resolution_source_trust_validation_row(
    *,
    refill_row: dict[str, Any],
    source_row: dict[str, Any],
    board_row: dict[str, Any],
) -> dict[str, Any]:
    page_url = str(refill_row.get("operator_fill_current_known_source_page_url") or "").strip()
    document_url = str(refill_row.get("operator_fill_current_known_document_url") or "").strip()
    review_status = str(refill_row.get("operator_fill_source_review_status") or "").strip()
    notes = str(refill_row.get("operator_fill_source_notes") or "").strip()
    historical_url = str(
        source_row.get("latest_historical_document_url")
        or board_row.get("latest_historical_document_url")
        or refill_row.get("READONLY_latest_historical_document_url")
        or ""
    )
    trusted_urls = _operator_resolution_source_trust_urls(source_row)
    trusted_hosts = sorted({_host(url) for url in trusted_urls if _host(url)})
    baseline_status = _operator_resolution_source_trust_status(
        board_row=board_row,
        source_row=source_row,
        trusted_urls=trusted_urls,
        historical_url=historical_url,
    )
    baseline_available = baseline_status in {"trusted_source_available", "ready_for_document_url_refill"}
    reasons: list[str] = []
    errors: list[str] = []
    warnings: list[str] = []
    page_validation_status = "not_provided"
    document_validation_status = "not_provided"
    page_domain_status = "not_checked"
    document_domain_status = "not_checked"

    if not page_url:
        if document_url:
            reasons.append("source_page_url_required")
            errors.append("source_page_url_required")
            status = "incomplete_source_refill"
        elif review_status or notes:
            reasons.append("operator_source_notes_diagnostic_only")
            status = "source_refill_diagnostic_only"
        elif baseline_available:
            reasons.append("baseline_source_context_already_available")
            status = "source_refill_not_required"
        else:
            reasons.append("source_page_url_required")
            errors.append("source_page_url_required")
            status = "incomplete_source_refill"
    else:
        normalized_page_url = _normalize_candidate_url(page_url)
        if not normalized_page_url:
            parsed = urllib.parse.urlparse(page_url)
            reason = "non_http_source_url" if parsed.scheme and parsed.scheme not in {"http", "https"} else "invalid_or_missing_http_url"
            reasons.append(reason)
            errors.append(reason)
            page_validation_status = "invalid"
        else:
            page_validation_status = "valid_http_url"
            _validate_operator_source_trust_candidate_url(
                normalized_page_url,
                historical_url=historical_url,
                expect_source_page=True,
                reasons=reasons,
                errors=errors,
            )
            page_classification = classify_source_url(normalized_page_url, allow_unknown_source=True)
            page_domain_status = page_classification["status"]
            if page_classification["status"] == "blocked":
                _append_unique(reasons, "blocked_source_url")
                _append_unique(errors, "blocked_source_url")
            elif page_classification["status"] == "unknown_warning":
                _append_unique(reasons, "unknown_source_host_requires_future_review")
                _append_unique(warnings, "unknown_source_host_requires_future_review")

        normalized_document_url = _normalize_candidate_url(document_url) if document_url else ""
        if document_url and not normalized_document_url:
            parsed = urllib.parse.urlparse(document_url)
            reason = "non_http_source_url" if parsed.scheme and parsed.scheme not in {"http", "https"} else "invalid_or_missing_http_url"
            _append_unique(reasons, reason)
            _append_unique(errors, reason)
            document_validation_status = "invalid"
        elif normalized_document_url:
            document_validation_status = "valid_http_url"
            _validate_operator_source_trust_candidate_url(
                normalized_document_url,
                historical_url=historical_url,
                expect_source_page=False,
                reasons=reasons,
                errors=errors,
            )
            document_classification = classify_source_url(normalized_document_url, allow_unknown_source=True)
            document_domain_status = document_classification["status"]
            if document_classification["status"] == "blocked":
                _append_unique(reasons, "blocked_source_url")
                _append_unique(errors, "blocked_source_url")
            if normalized_page_url and _source_trust_registrable_domain(_host(normalized_page_url)) != (
                _source_trust_registrable_domain(_host(normalized_document_url))
            ):
                _append_unique(reasons, "source_document_host_conflict")
                _append_unique(errors, "source_document_host_conflict")
        status = "invalid_source_refill" if errors else "valid_source_candidate_for_future_review"

    if status == "valid_source_candidate_for_future_review":
        severity = "warning" if warnings else "info"
        next_step = "review_source_candidate_before_controlled_merge"
        note = "Manual source context is a pending candidate only; baseline trust is unchanged."
    elif status == "source_refill_not_required":
        severity = "info"
        next_step = "continue_exact_document_url_refill"
        note = "Baseline source context is already available."
    elif status == "source_refill_diagnostic_only":
        severity = "warning"
        next_step = "fill_official_source_page_if_source_context_is_required"
        note = "Operator notes were preserved as diagnostics only."
    else:
        severity = "error" if status == "invalid_source_refill" else "warning"
        next_step = "correct_source_trust_refill"
        note = "Correct the refill row before any future controlled source-pack review."

    return {
        "resolution_id": str(refill_row.get("resolution_id") or ""),
        "company_id": refill_row.get("company_id") or source_row.get("company_id") or "",
        "company_name": refill_row.get("company_name") or source_row.get("company_name") or "",
        "canonical_company_id": refill_row.get("canonical_company_id")
        or source_row.get("canonical_company_id")
        or refill_row.get("company_id")
        or source_row.get("company_id")
        or "",
        "canonical_company_name": refill_row.get("canonical_company_name")
        or source_row.get("canonical_company_name")
        or refill_row.get("company_name")
        or source_row.get("company_name")
        or "",
        "target_reporting_period": refill_row.get("target_reporting_period") or "",
        "required_report_type": refill_row.get("required_report_type") or "",
        "required_standard": refill_row.get("required_standard") or "",
        "baseline_current_known_source_page_url": source_row.get("current_known_source_page_url") or "",
        "baseline_current_known_document_url": source_row.get("current_known_document_url") or "",
        "baseline_trusted_source_hosts": trusted_hosts,
        "latest_historical_document_url": historical_url,
        "operator_fill_current_known_source_page_url": page_url,
        "operator_fill_current_known_document_url": document_url,
        "operator_fill_source_review_status": review_status,
        "operator_fill_source_notes": notes,
        "validation_status": status,
        "validation_severity": severity,
        "validation_reason_codes": list(dict.fromkeys(reasons)),
        "validation_errors": list(dict.fromkeys(errors)),
        "validation_warnings": list(dict.fromkeys(warnings)),
        "source_page_url_validation_status": page_validation_status,
        "source_document_url_validation_status": document_validation_status,
        "source_page_domain_status": page_domain_status,
        "source_document_domain_status": document_domain_status,
        "future_controlled_review_required": status == "valid_source_candidate_for_future_review",
        "operator_next_step": next_step,
        "validation_note": note,
        "would_update_original_source_pack": False,
        "would_trust_manual_source": False,
        "would_promote_source": False,
        "would_update_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_scores": False,
        "would_trigger_paper_trading": False,
    }


def _validate_operator_source_trust_candidate_url(
    url: str,
    *,
    historical_url: str,
    expect_source_page: bool,
    reasons: list[str],
    errors: list[str],
) -> None:
    if _has_blocked_source_hint(url):
        _append_unique(reasons, "blocked_source_url")
        _append_unique(errors, "blocked_source_url")
    historical_normalized = _normalize_candidate_url(historical_url)
    if historical_normalized and url == historical_normalized:
        _append_unique(reasons, "historical_fallback_url_not_allowed")
        _append_unique(errors, "historical_fallback_url_not_allowed")
    if _source_trust_has_archive_or_history_url([url]):
        _append_unique(reasons, "archive_or_history_source_not_allowed")
        _append_unique(errors, "archive_or_history_source_not_allowed")
    if expect_source_page and _url_is_pdf(url):
        _append_unique(reasons, "source_page_expected_but_document_url_provided")
        _append_unique(errors, "source_page_expected_but_document_url_provided")
    if expect_source_page and not _operator_source_page_has_context_signal(url):
        _append_unique(reasons, "ambiguous_source_page")
        _append_unique(errors, "ambiguous_source_page")


def _operator_source_page_has_context_signal(url: str) -> bool:
    parsed = urllib.parse.urlparse(url)
    path_and_query = urllib.parse.unquote(f"{parsed.path}?{parsed.query}").casefold()
    if parsed.path in {"", "/"} and not parsed.query:
        return False
    if _contains_any(
        path_and_query,
        (
            "report",
            "reporting",
            "investor",
            "disclosure",
            "financial",
            "result",
            "statement",
            "accounting",
            "otchet",
            "\u043e\u0442\u0447\u0435\u0442",
            "\u0440\u0430\u0441\u043a\u0440\u044b\u0442",
        ),
    ):
        return True
    segments = [segment for segment in re.split(r"[/_.?&=+\-]+", path_and_query) if segment]
    return "ir" in segments or _host(url).endswith(("e-disclosure.ru", "disclosure.ru"))


def _append_unique(items: list[str], value: str) -> None:
    if value not in items:
        items.append(value)


def _build_operator_resolution_source_trust_patch_rows(
    *,
    validation_rows: list[dict[str, Any]],
    source_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    source_by_id = _rows_by_resolution_id(source_rows)
    source_by_company = {_company_key(row): row for row in source_rows if _company_key(row)}
    rows: list[dict[str, Any]] = []
    for validation in validation_rows:
        resolution_id = str(validation.get("resolution_id") or "")
        source_row = source_by_id.get(resolution_id) or source_by_company.get(_company_key(validation))
        validation_status = str(validation.get("validation_status") or "")
        patch_status = {
            "valid_source_candidate_for_future_review": "eligible_for_source_pack_draft",
            "incomplete_source_refill": "not_eligible_incomplete_source_refill",
            "invalid_source_refill": "not_eligible_invalid_source_refill",
            "source_refill_not_required": "not_eligible_refill_not_required",
            "source_refill_diagnostic_only": "not_eligible_diagnostic_only",
        }.get(validation_status, "not_eligible_invalid_source_refill")
        eligible = patch_status == "eligible_for_source_pack_draft"
        patch_action = (
            "preview_update_source_context_in_draft"
            if eligible and source_row is not None
            else "preview_create_source_context_in_draft"
            if eligible
            else "preview_noop"
        )
        rows.append(
            {
                "patch_id": f"operator_source_trust_patch:{resolution_id}",
                "resolution_id": resolution_id,
                "company_id": validation.get("company_id") or "",
                "company_name": validation.get("company_name") or "",
                "canonical_company_id": validation.get("canonical_company_id") or "",
                "canonical_company_name": validation.get("canonical_company_name") or "",
                "patch_status": patch_status,
                "patch_action": patch_action,
                "patch_reason_codes": validation.get("validation_reason_codes") or [],
                "patch_errors": validation.get("validation_errors") or [],
                "patch_warnings": validation.get("validation_warnings") or [],
                "source_validation_status": validation_status,
                "candidate_current_known_source_page_url": validation.get(
                    "operator_fill_current_known_source_page_url"
                )
                or "",
                "candidate_current_known_document_url": validation.get(
                    "operator_fill_current_known_document_url"
                )
                or "",
                "candidate_operator_fill_source_review_status": validation.get(
                    "operator_fill_source_review_status"
                )
                or "",
                "candidate_source_notes": validation.get("operator_fill_source_notes") or "",
                "future_controlled_review_required": eligible,
                "future_chain_rerun_required": eligible,
                "would_change_source_pack_draft": eligible,
                "would_update_original_source_pack": False,
                "would_trust_manual_source": False,
                "would_promote_source": False,
                "would_update_database": False,
                "would_extract_values": False,
                "would_import_report": False,
                "would_mutate_scores": False,
                "would_trigger_paper_trading": False,
                "operator_next_step": validation.get("operator_next_step") or "",
                "patch_note": "Preview-only source-pack draft candidate; manual source trust is not applied.",
            }
        )
    return rows


def _build_operator_resolution_source_pack_draft_rows(
    *,
    source_rows: list[dict[str, Any]],
    patch_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    draft_rows = copy.deepcopy(source_rows)
    for patch in patch_rows:
        if patch.get("patch_status") != "eligible_for_source_pack_draft":
            continue
        draft_row = _find_operator_resolution_source_pack_draft_row(draft_rows, patch)
        if draft_row is None:
            draft_row = {
                "resolution_id": patch.get("resolution_id") or "",
                "company_id": patch.get("company_id") or "",
                "company_name": patch.get("company_name") or "",
                "canonical_company_id": patch.get("canonical_company_id") or patch.get("company_id") or "",
                "canonical_company_name": patch.get("canonical_company_name") or patch.get("company_name") or "",
                "current_known_source_page_url": "",
                "current_known_document_url": "",
            }
            draft_rows.append(draft_row)
        draft_row.update(
            {
                "candidate_current_known_source_page_url": patch.get(
                    "candidate_current_known_source_page_url"
                )
                or "",
                "candidate_current_known_document_url": patch.get("candidate_current_known_document_url") or "",
                "candidate_operator_fill_source_review_status": patch.get(
                    "candidate_operator_fill_source_review_status"
                )
                or "",
                "candidate_source_notes": patch.get("candidate_source_notes") or "",
                "source_context_status": "operator_source_candidate_for_future_controlled_review",
                "operator_source_review_status": "pending_future_controlled_review",
                "source_context_origin": "operator_resolution_source_trust_refill_task127",
                "trusted_host_status": "not_trusted_until_future_review",
            }
        )
    return draft_rows


def _find_operator_resolution_source_pack_draft_row(
    rows: list[dict[str, Any]],
    patch: dict[str, Any],
) -> dict[str, Any] | None:
    resolution_id = str(patch.get("resolution_id") or "")
    company_key = _company_key(patch)
    for row in rows:
        if resolution_id and str(row.get("resolution_id") or "") == resolution_id:
            return row
    for row in rows:
        if company_key and _company_key(row) == company_key:
            return row
    return None


def _build_operator_resolution_source_trust_validation_report(
    args: argparse.Namespace,
    *,
    refill_path: Path,
    board_path: Path | None,
    artifacts: dict[str, Path],
    rows: list[dict[str, Any]],
    patch_report: dict[str, Any],
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    status = (
        "passed"
        if rows
        and all(
            row.get("validation_status")
            in {"valid_source_candidate_for_future_review", "source_refill_not_required"}
            for row in rows
        )
        and not warnings
        else "warning"
    )
    return {
        "status": status,
        "mode": "operator-resolution-source-trust-refill-validate",
        "operator_resolution_source_trust_refill_input": str(refill_path),
        "operator_resolution_source_pack_input": _path_value(args.operator_resolution_source_pack_input),
        "operator_resolution_chain_review_board_input": _path_value(board_path),
        "row_count": len(rows),
        "valid_candidate_count": sum(
            1 for row in rows if row.get("validation_status") == "valid_source_candidate_for_future_review"
        ),
        "incomplete_count": sum(1 for row in rows if row.get("validation_status") == "incomplete_source_refill"),
        "invalid_count": sum(1 for row in rows if row.get("validation_status") == "invalid_source_refill"),
        "not_required_count": sum(
            1 for row in rows if row.get("validation_status") == "source_refill_not_required"
        ),
        "diagnostic_only_count": sum(
            1 for row in rows if row.get("validation_status") == "source_refill_diagnostic_only"
        ),
        "source_pack_draft_candidate_count": patch_report.get("eligible_count", 0),
        "validation_status_counts": _count_by_key(rows, "validation_status"),
        "validation_error_counts": _count_list_values(rows, "validation_errors"),
        "rows": rows,
        "patch_preview_summary": patch_report.get("summary") or {},
        "source_pack_draft_created": True,
        "original_source_pack_modified": False,
        "artifacts": {key: str(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": [],
        "next_steps": _next_steps("operator-resolution-source-trust-refill-validate", status),
        "would_update_original_source_pack": False,
        "would_trust_manual_source": False,
        "would_promote_source": False,
        "would_update_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        **SAFETY_FLAGS,
    }


def _build_operator_resolution_source_trust_patch_report(
    *,
    patch_rows: list[dict[str, Any]],
    artifacts: dict[str, Path],
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    summary = {
        "row_count": len(patch_rows),
        "eligible_count": sum(1 for row in patch_rows if row.get("patch_status") == "eligible_for_source_pack_draft"),
        "blocked_count": sum(1 for row in patch_rows if row.get("patch_status") != "eligible_for_source_pack_draft"),
        "update_count": sum(
            1 for row in patch_rows if row.get("patch_action") == "preview_update_source_context_in_draft"
        ),
        "create_count": sum(
            1 for row in patch_rows if row.get("patch_action") == "preview_create_source_context_in_draft"
        ),
        "patch_status_counts": _count_by_key(patch_rows, "patch_status"),
        "patch_action_counts": _count_by_key(patch_rows, "patch_action"),
    }
    return {
        "status": "passed" if summary["blocked_count"] == 0 and not warnings else "warning",
        "mode": "operator-resolution-source-trust-patch-preview",
        "summary": summary,
        **summary,
        "patch_rows": patch_rows,
        "source_pack_draft_output": str(artifacts["source_pack_draft_json"]),
        "warnings": warnings,
        "errors": [],
        "would_update_original_source_pack": False,
        "would_trust_manual_source": False,
        "would_promote_source": False,
        "would_update_database": False,
        "would_extract_values": False,
        "would_import_report": False,
        **SAFETY_FLAGS,
    }


def _count_list_values(rows: list[dict[str, Any]], key: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        values = row.get(key) or []
        if not isinstance(values, list):
            values = [values]
        for value in values:
            text = str(value or "")
            if text:
                counts[text] = counts.get(text, 0) + 1
    return counts


