def _rzd_validation_html_response_link_discovery_preservation_fields(
    *,
    inputs: dict[str, Path | None],
    snapshots: dict[Path, bytes],
    input_hashes: dict[str, str],
) -> dict[str, bool]:
    fields: dict[str, bool] = {}
    all_preserved = True
    for role, path in inputs.items():
        preserved = False
        if path is not None and path in snapshots:
            try:
                current = path.read_bytes()
                preserved = current == snapshots[path] and hashlib.sha256(current).hexdigest() == input_hashes.get(role)
            except OSError:
                preserved = False
        fields[f"{role}_input_preserved"] = bool(preserved)
        all_preserved = all_preserved and preserved
    fields["input_bytes_unchanged"] = bool(all_preserved)
    return fields


def _rzd_validation_html_response_link_discovery_blocker_row(row: dict[str, Any], code: str, *, candidate_id: str | None = None) -> dict[str, Any]:
    return {
        "blocker_id": f"rzd_validation_html_response_link_discovery_blocker:{candidate_id or row.get('html_link_discovery_candidate_id') or 'unknown'}:{code}",
        "html_link_discovery_candidate_id": candidate_id or row.get("html_link_discovery_candidate_id") or "",
        "source_validation_fetch_id": row.get("source_validation_fetch_id") or "",
        "company_id": row.get("company_id") or "18",
        "company_name": row.get("company_name") or "RZD",
        "candidate_url": row.get("candidate_url") or row.get("source_validation_candidate_url") or "",
        "candidate_type": row.get("candidate_type") or "",
        "candidate_status": row.get("candidate_status") or "blocked_validation_html_candidate",
        "blocker_code": code,
        "blocker_severity": "error" if code in {"task166_raw_validation_response_missing", "task166_raw_validation_response_hash_mismatch", "input_drift_detected"} else "warning",
        "operator_action": "review_task167_static_blocker_before_any_future_validation",
        "safe_hint": "Task167 performs local HTML inspection only; it never fetches discovered links or downloads documents.",
    }


def _rzd_validation_html_response_link_discovery_count_fields(
    *,
    loaded: dict[str, Any] | None,
    candidate_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    status: str,
    raw_stats: dict[str, int] | None = None,
) -> dict[str, int]:
    raw_stats = raw_stats or {}
    unique_urls = {str(row.get("candidate_url") or "") for row in candidate_rows if str(row.get("candidate_url") or "")}
    type_counts = _count_by_key(candidate_rows, "candidate_type")
    confidence_counts = _count_by_key(candidate_rows, "discovery_confidence")
    return {
        "input_html_response_count": int(raw_stats.get("input_html_response_count") or 0),
        "raw_html_response_inspected_count": int(raw_stats.get("raw_html_response_inspected_count") or 0),
        "raw_html_response_hash_verified_count": int(raw_stats.get("raw_html_response_hash_verified_count") or 0),
        "discovery_candidate_count": len(candidate_rows),
        "unique_candidate_count": len(unique_urls),
        "candidate_row_count": len(candidate_rows),
        "future_validation_candidate_count": sum(1 for row in candidate_rows if _as_bool(row.get("future_candidate_validation_required"))),
        "blocked_candidate_count": sum(1 for row in candidate_rows if row.get("discovery_blocker_codes") or not _as_bool(row.get("future_candidate_validation_required"))),
        "failed_count": 1 if status == "failed" else 0,
        "direct_document_candidate_count": int(type_counts.get("direct_document_candidate") or 0),
        "document_download_candidate_count": int(type_counts.get("document_download_candidate") or 0),
        "api_media_resource_candidate_count": int(type_counts.get("api_media_resource_candidate") or 0),
        "api_metadata_candidate_count": int(type_counts.get("api_metadata_candidate") or 0),
        "candidate_page_count": int(type_counts.get("candidate_page") or 0),
        "cms_element_candidate_count": int(type_counts.get("cms_element_candidate") or 0),
        "target_year_aligned_candidate_count": sum(1 for row in candidate_rows if _as_bool(row.get("target_year_aligned"))),
        "mixed_year_context_candidate_count": sum(1 for row in candidate_rows if _as_bool(row.get("mixed_year_context"))),
        "target_year_missing_candidate_count": sum(1 for row in candidate_rows if "candidate_target_year_missing" in (row.get("discovery_blocker_codes") or [])),
        "stale_year_mismatch_candidate_count": sum(1 for row in candidate_rows if _as_bool(row.get("stale_year_mismatch"))),
        "unknown_year_candidate_count": sum(1 for row in candidate_rows if _as_bool(row.get("unknown_year_candidate"))),
        "known_image_resource_candidate_count": sum(1 for row in candidate_rows if "candidate_known_image_resource_from_task166" in (row.get("discovery_blocker_codes") or [])),
        "high_confidence_candidate_count": int(confidence_counts.get("high") or 0),
        "medium_confidence_candidate_count": int(confidence_counts.get("medium") or 0),
        "low_confidence_candidate_count": int(confidence_counts.get("low") or 0),
        "reject_candidate_count": int(confidence_counts.get("reject") or 0),
        "blocked_count": len(blocker_rows),
    }


def _build_rzd_validation_html_response_link_discovery_report(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    input_hashes: dict[str, str],
    preservation: dict[str, bool],
    loaded: dict[str, Any],
    candidate_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
    raw_stats: dict[str, int],
    forced_status: str,
) -> dict[str, Any]:
    status = "failed" if errors else forced_status
    counts = _rzd_validation_html_response_link_discovery_count_fields(
        loaded=loaded,
        candidate_rows=candidate_rows,
        blocker_rows=blocker_rows,
        status=status,
        raw_stats=raw_stats,
    )
    ready_rows = [row for row in candidate_rows if _as_bool(row.get("future_candidate_validation_required"))]
    report = {
        "status": status,
        "mode": "rzd-validation-html-response-link-discovery-preview-v2",
        "target_report_year": RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_DEFAULTS["target_report_year"],
        "candidate_rows": candidate_rows,
        "blocker_rows": blocker_rows,
        "candidate_type_counts": _count_by_key(candidate_rows, "candidate_type"),
        "discovery_confidence_counts": _count_by_key(candidate_rows, "discovery_confidence"),
        "blocker_code_counts": _count_by_key(blocker_rows, "blocker_code"),
        "warnings": warnings,
        "errors": errors,
        "artifacts": {role: str(path) for role, path in artifacts.items() if path is not None},
        "next_steps": _next_steps("rzd-validation-html-response-link-discovery-preview-v2", status),
        "rzd_validation_html_links_discovered": bool(candidate_rows),
        "rzd_document_candidate_found": bool(ready_rows),
        "rzd_ready_for_future_candidate_validation": bool(ready_rows),
        "rzd_ready_for_future_document_download_plan": any(_as_bool(row.get("future_document_download_plan_required")) for row in ready_rows),
        "rzd_document_download_ready": False,
        "rzd_document_parse_ready": False,
        "rzd_import_ready": False,
        **{f"{role}_input_path": str(path or "") for role, path in inputs.items()},
        **{f"{role}_input_sha256": input_hashes.get(role, "") for role in inputs},
        **preservation,
        **_rzd_validation_html_response_link_discovery_safety_flags(),
        **counts,
    }
    for field in RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_REQUIRED_BOOL_FIELDS:
        report[field] = bool(report.get(field))
    for field in RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_REQUIRED_COUNT_FIELDS:
        report[field] = int(report.get(field) or 0)
    return report


def _rzd_validation_html_response_link_discovery_failed_report(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    input_hashes: dict[str, str],
    errors: list[dict[str, Any]],
    write_outputs: bool,
) -> dict[str, Any]:
    blocker_rows = [
        _rzd_validation_html_response_link_discovery_blocker_row({}, str(error.get("message") or "unknown_readiness"), candidate_id=f"preflight:{index}")
        for index, error in enumerate(errors, start=1)
    ]
    report = _build_rzd_validation_html_response_link_discovery_report(
        args,
        inputs=inputs,
        artifacts=artifacts,
        input_hashes=input_hashes,
        preservation=_rzd_validation_html_response_link_discovery_missing_preservation(),
        loaded={},
        candidate_rows=[],
        blocker_rows=blocker_rows,
        warnings=[],
        errors=errors,
        raw_stats={},
        forced_status="failed",
    )
    if write_outputs:
        try:
            _rzd_validation_html_response_link_discovery_write_safe_outputs(report, artifacts)
        except OSError as exc:
            report["errors"] = [*report.get("errors", []), {"message": "rzd_validation_html_response_link_discovery_write_failed", "error": str(exc)}]
    return report


def _rzd_validation_html_response_link_discovery_write_safe_outputs(report: dict[str, Any], artifacts: dict[str, Path | None]) -> None:
    _write_optional_json_report(report, artifacts["discovery_json"])
    _write_optional_flat_csv(report.get("candidate_rows") or [], RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_FIELDS, artifacts["discovery_csv"])
    if artifacts["discovery_markdown"] is not None:
        write_rzd_validation_html_response_link_discovery_markdown(report, artifacts["discovery_markdown"])
    _write_optional_json_report(
        {
            "status": report["status"],
            "mode": "rzd-validation-html-response-link-discovery-candidates-v2",
            "row_count": len(report.get("candidate_rows") or []),
            "candidate_rows": report.get("candidate_rows") or [],
            **_rzd_validation_html_response_link_discovery_safety_flags(),
        },
        artifacts["candidates_json"],
    )
    _write_optional_flat_csv(report.get("candidate_rows") or [], RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_FIELDS, artifacts["candidates_csv"])
    _write_optional_json_report(
        {
            "status": report["status"],
            "mode": "rzd-validation-html-response-link-discovery-blockers-v2",
            "row_count": len(report.get("blocker_rows") or []),
            "blocker_rows": report.get("blocker_rows") or [],
            **_rzd_validation_html_response_link_discovery_safety_flags(),
        },
        artifacts["blockers_json"],
    )
    _write_optional_flat_csv(report.get("blocker_rows") or [], RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_BLOCKER_FIELDS, artifacts["blockers_csv"])
    if artifacts["rerun_markdown"] is not None:
        write_rzd_validation_html_response_link_discovery_rerun_markdown(report, artifacts["rerun_markdown"])


def _rzd_validation_html_response_link_discovery_finalize_report(
    report: dict[str, Any],
    *,
    artifacts: dict[str, Path | None],
    inputs: dict[str, Path | None],
    snapshots: dict[Path, bytes],
    input_hashes: dict[str, str],
) -> dict[str, Any]:
    try:
        _rzd_validation_html_response_link_discovery_write_safe_outputs(report, artifacts)
    except OSError as exc:
        report["status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": "rzd_validation_html_response_link_discovery_write_failed", "error": str(exc)}]
        return report
    preservation = _rzd_validation_html_response_link_discovery_preservation_fields(inputs=inputs, snapshots=snapshots, input_hashes=input_hashes)
    report.update(preservation)
    if not preservation["input_bytes_unchanged"]:
        report["status"] = "failed"
        if not any(error.get("message") == "rzd_validation_html_response_link_discovery_input_drift_detected" for error in report.get("errors") or []):
            report["errors"] = [*report.get("errors", []), {"message": "rzd_validation_html_response_link_discovery_input_drift_detected"}]
        if not any(row.get("blocker_code") == "input_drift_detected" for row in report.get("blocker_rows") or []):
            report["blocker_rows"] = [*report.get("blocker_rows", []), _rzd_validation_html_response_link_discovery_blocker_row({}, "input_drift_detected", candidate_id="input_drift")]
    report.update(
        _rzd_validation_html_response_link_discovery_count_fields(
            loaded={},
            candidate_rows=list(report.get("candidate_rows") or []),
            blocker_rows=list(report.get("blocker_rows") or []),
            status=str(report.get("status") or ""),
            raw_stats={
                "input_html_response_count": int(report.get("input_html_response_count") or 0),
                "raw_html_response_inspected_count": int(report.get("raw_html_response_inspected_count") or 0),
                "raw_html_response_hash_verified_count": int(report.get("raw_html_response_hash_verified_count") or 0),
            },
        )
    )
    report["candidate_type_counts"] = _count_by_key(report.get("candidate_rows") or [], "candidate_type")
    report["discovery_confidence_counts"] = _count_by_key(report.get("candidate_rows") or [], "discovery_confidence")
    report["blocker_code_counts"] = _count_by_key(report.get("blocker_rows") or [], "blocker_code")
    for field in RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_REQUIRED_BOOL_FIELDS:
        report[field] = bool(report.get(field))
    for field in RZD_VALIDATION_HTML_RESPONSE_LINK_DISCOVERY_REQUIRED_COUNT_FIELDS:
        report[field] = int(report.get(field) or 0)
    try:
        _rzd_validation_html_response_link_discovery_write_safe_outputs(report, artifacts)
    except OSError as exc:
        report["status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": "rzd_validation_html_response_link_discovery_write_failed", "error": str(exc)}]
    return report


def run_rzd_manual_official_pdf_evidence_registration_preview_v2(args: argparse.Namespace) -> dict[str, Any]:
    inputs = _rzd_manual_official_pdf_evidence_registration_inputs(args)
    artifacts = _rzd_manual_official_pdf_evidence_registration_artifacts(args)
    copy_dir = _rzd_manual_official_pdf_evidence_controlled_copy_dir(args)
    errors = _rzd_manual_official_pdf_evidence_registration_output_errors(args, inputs=inputs, artifacts=artifacts, copy_dir=copy_dir)
    if errors:
        return _rzd_manual_official_pdf_evidence_registration_failed_report(args, inputs=inputs, artifacts=artifacts, input_hashes={}, errors=errors, write_outputs=False)
    loaded, snapshots, input_hashes, errors = _rzd_manual_official_pdf_evidence_registration_load_inputs(args, inputs)
    if errors:
        return _rzd_manual_official_pdf_evidence_registration_failed_report(args, inputs=inputs, artifacts=artifacts, input_hashes=input_hashes, errors=errors, write_outputs=True)
    evidence_rows, blocker_rows, warnings, forced_status = _rzd_manual_official_pdf_evidence_registration_rows(args, loaded=loaded, copy_dir=copy_dir)
    report = _build_rzd_manual_official_pdf_evidence_registration_report(
        args,
        inputs=inputs,
        artifacts=artifacts,
        copy_dir=copy_dir,
        input_hashes=input_hashes,
        preservation=_rzd_manual_official_pdf_evidence_registration_missing_preservation(),
        evidence_rows=evidence_rows,
        blocker_rows=blocker_rows,
        warnings=warnings,
        errors=[],
        forced_status=forced_status,
    )
    return _rzd_manual_official_pdf_evidence_registration_finalize_report(report, artifacts=artifacts, inputs=inputs, snapshots=snapshots, input_hashes=input_hashes)


def _rzd_manual_official_pdf_evidence_registration_inputs(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    return {
        "manual_official_pdf": args.manual_official_pdf_input,
        "source_trust_controlled_source_pack": args.source_trust_controlled_source_pack_input
        or (output_dir / SOURCE_TRUST_RECOVERY_CONTROLLED_APPLY_ARTIFACT_NAMES["controlled_source_pack_json"] if output_dir else None),
    }


def _rzd_manual_official_pdf_evidence_registration_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "registration_json": args.rzd_manual_official_pdf_evidence_registration_output,
        "registration_csv": args.rzd_manual_official_pdf_evidence_registration_csv_output,
        "registration_markdown": args.rzd_manual_official_pdf_evidence_registration_markdown_output,
        "evidence_json": args.rzd_manual_official_pdf_evidence_registration_evidence_output,
        "evidence_csv": args.rzd_manual_official_pdf_evidence_registration_evidence_csv_output,
        "blockers_json": args.rzd_manual_official_pdf_evidence_registration_blockers_output,
        "blockers_csv": args.rzd_manual_official_pdf_evidence_registration_blockers_csv_output,
        "hash_manifest_json": args.rzd_manual_official_pdf_evidence_registration_hash_manifest_output,
        "rerun_markdown": args.rzd_manual_official_pdf_evidence_registration_rerun_markdown_output,
    }
    return {
        role: overrides[role] or (output_dir / filename if output_dir is not None else None)
        for role, filename in RZD_MANUAL_OFFICIAL_PDF_EVIDENCE_ARTIFACT_NAMES.items()
    }


def _rzd_manual_official_pdf_evidence_controlled_copy_dir(args: argparse.Namespace) -> Path | None:
    if args.manual_official_pdf_controlled_copy_dir is not None:
        return args.manual_official_pdf_controlled_copy_dir
    output_dir = args.operator_resolution_chain_output_dir
    return output_dir / "rzd_manual_official_pdf_evidence_task168" if output_dir else None


def _rzd_manual_official_pdf_evidence_registration_output_errors(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    copy_dir: Path | None,
) -> list[dict[str, Any]]:
    outputs = [path for path in [*artifacts.values(), args.json_output, args.markdown_output, copy_dir] if path is not None]
    protected_inputs = [path for path in inputs.values() if path is not None]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "rzd_manual_official_pdf_evidence_registration_output_must_not_equal_input"}]
        if any(_paths_equal(output, input_path) for input_path in protected_inputs):
            return [{"message": "rzd_manual_official_pdf_evidence_registration_output_must_not_equal_input"}]
    max_pages = _as_int(getattr(args, "manual_official_pdf_preview_max_pages", None))
    if max_pages is None or max_pages < 0:
        return [{"message": "invalid_rzd_manual_official_pdf_evidence_registration_config:manual_official_pdf_preview_max_pages"}]
    return []


def _rzd_manual_official_pdf_evidence_registration_load_inputs(
    args: argparse.Namespace,
    inputs: dict[str, Path | None],
) -> tuple[dict[str, Any], dict[Path, bytes], dict[str, str], list[dict[str, Any]]]:
    loaded: dict[str, Any] = {
        "manual_official_pdf_bytes": b"",
        "manual_official_pdf_path": inputs.get("manual_official_pdf"),
        "source_trust_controlled_source_pack": {},
        "source_trust_controlled_source_pack_rows": [],
    }
    snapshots: dict[Path, bytes] = {}
    input_hashes: dict[str, str] = {}
    errors: list[dict[str, Any]] = []
    if not str(getattr(args, "manual_official_source_page_url", "") or "").strip():
        errors.append({"message": "manual_official_source_page_url_required"})
    if not str(getattr(args, "manual_official_company_id", "") or "").strip():
        errors.append({"message": "manual_official_company_id_required"})
    if not str(getattr(args, "manual_official_company_name", "") or "").strip():
        errors.append({"message": "manual_official_company_name_required"})
    if not _as_int(getattr(args, "manual_official_report_year", None)):
        errors.append({"message": "manual_official_report_year_required"})
    pdf_path = inputs.get("manual_official_pdf")
    if pdf_path is None:
        errors.append({"message": "manual_official_pdf_input_required"})
    elif not pdf_path.exists():
        errors.append({"message": "manual_official_pdf_input_not_found"})
    elif not pdf_path.is_file():
        errors.append({"message": "manual_official_pdf_input_not_file"})
    else:
        try:
            pdf_bytes = pdf_path.read_bytes()
        except OSError as exc:
            errors.append({"message": "manual_official_pdf_input_not_found", "error": str(exc)})
        else:
            if not pdf_bytes:
                errors.append({"message": "manual_official_pdf_input_empty"})
            elif not pdf_bytes.startswith(b"%PDF"):
                errors.append({"message": "manual_official_pdf_input_not_pdf"})
            else:
                loaded["manual_official_pdf_bytes"] = pdf_bytes
                snapshots[pdf_path] = pdf_bytes
                input_hashes["manual_official_pdf"] = hashlib.sha256(pdf_bytes).hexdigest()
    source_pack_path = inputs.get("source_trust_controlled_source_pack")
    if source_pack_path is None or not source_pack_path.is_file():
        errors.append({"message": "source_trust_controlled_source_pack_input_required"})
    else:
        try:
            data = source_pack_path.read_bytes()
            payload = json.loads(data.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            errors.append({"message": "source_trust_controlled_source_pack_input_required", "error": str(exc)})
        else:
            if not isinstance(payload, dict):
                errors.append({"message": "source_trust_controlled_source_pack_input_required"})
            else:
                loaded["source_trust_controlled_source_pack"] = payload
                loaded["source_trust_controlled_source_pack_rows"] = _rzd_reporting_hub_embedded_source_pack_rows(payload)
                snapshots[source_pack_path] = data
                input_hashes["source_trust_controlled_source_pack"] = hashlib.sha256(data).hexdigest()
    return loaded, snapshots, input_hashes, errors


def _rzd_manual_official_pdf_evidence_registration_rows(
    args: argparse.Namespace,
    *,
    loaded: dict[str, Any],
    copy_dir: Path | None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]], str]:
    pdf_path = loaded.get("manual_official_pdf_path")
    pdf_bytes = loaded.get("manual_official_pdf_bytes") if isinstance(loaded.get("manual_official_pdf_bytes"), bytes) else b""
    source_pack_rows = [row for row in loaded.get("source_trust_controlled_source_pack_rows") or [] if _rzd_manual_official_pdf_source_pack_row_is_rzd(row)]
    trusted_hosts = _rzd_reporting_hub_embedded_trusted_hosts(source_pack_rows)
    source_page_url = _normalize_candidate_url(str(args.manual_official_source_page_url or ""))
    source_host = _host(source_page_url)
    source_trusted = _source_trust_recovery_draft_review_host_trusted(source_host, trusted_hosts)
    blocker_codes: list[str] = []
    warning_codes: list[str] = []
    warnings: list[dict[str, Any]] = []
    if not source_pack_rows or "company.rzd.ru" not in trusted_hosts:
        blocker_codes.append("source_trust_company_rzd_missing")
    if not source_trusted:
        blocker_codes.append("manual_official_source_page_host_not_trusted")
    original_sha = hashlib.sha256(pdf_bytes).hexdigest()
    copy_path = (copy_dir / f"rzd_manual_official_pdf_evidence_sha_{original_sha[:12]}.pdf") if copy_dir is not None else None
    copy_created = False
    copy_size = 0
    copy_sha = ""
    if not blocker_codes and copy_path is not None and isinstance(pdf_path, Path):
        try:
            copy_path.parent.mkdir(parents=True, exist_ok=True)
            if _paths_equal(copy_path, pdf_path):
                raise OSError("controlled copy path equals source PDF")
            shutil.copyfile(pdf_path, copy_path)
            copy_bytes = copy_path.read_bytes()
            copy_size = len(copy_bytes)
            copy_sha = hashlib.sha256(copy_bytes).hexdigest()
            copy_created = copy_sha == original_sha
        except OSError:
            blocker_codes.append("manual_official_pdf_controlled_copy_failed")
    elif not blocker_codes:
        blocker_codes.append("manual_official_pdf_controlled_copy_failed")
    metadata = _rzd_manual_official_pdf_preview_metadata(pdf_path, int(_as_int(args.manual_official_pdf_preview_max_pages) or 0)) if isinstance(pdf_path, Path) else {"available": False, "text": "", "warnings": ["manual_official_pdf_text_extraction_unavailable"]}
    text = str(metadata.get("text") or "")
    extraction_available = bool(metadata.get("available")) and bool(text.strip())
    metadata_warning_codes = [str(code) for code in (metadata.get("warnings") or []) if str(code)]
    if not extraction_available:
        if metadata_warning_codes:
            warning_codes.extend(metadata_warning_codes)
        if "manual_official_pdf_text_extraction_unavailable" not in warning_codes:
            warning_codes.append("manual_official_pdf_text_extraction_unavailable")
        for code in warning_codes:
            if code.startswith("manual_official_pdf_text_extraction"):
                warnings.append({"message": code})
    signals = _rzd_manual_official_pdf_evidence_text_signals(text, int(args.manual_official_report_year or 0))
    if extraction_available:
        if not signals["company_identity_verified"]:
            blocker_codes.append("manual_official_pdf_company_identity_mismatch")
        if not signals["report_year_verified"]:
            blocker_codes.append("manual_official_pdf_report_year_mismatch")
        if not signals["document_kind_verified"]:
            blocker_codes.append("manual_official_pdf_document_kind_mismatch")
        if not signals["report_standard_verified"]:
            warning_codes.append("manual_official_pdf_report_standard_not_detected_in_preview")
        if not signals["auditor_detected"]:
            warning_codes.append("manual_official_pdf_auditor_not_detected")
        if not signals["document_date_detected"]:
            warning_codes.append("manual_official_pdf_document_date_not_detected")
        if signals["financial_statement_sections_count"] < 2:
            warning_codes.append("manual_official_pdf_financial_sections_partially_detected")
    blocker_codes = list(dict.fromkeys(blocker_codes))
    warning_codes = list(dict.fromkeys(warning_codes))
    strong_identity_without_standard = (
        extraction_available
        and signals["company_identity_verified"]
        and signals["report_year_verified"]
        and signals["document_kind_verified"]
        and str(args.manual_official_report_standard or "").casefold() == "ifrs"
    )
    confidence = (
        "reject"
        if blocker_codes
        else "high"
        if extraction_available and signals["pdf_identity_verified"] and copy_created and source_trusted
        else "medium"
        if not extraction_available or strong_identity_without_standard
        else "reject"
    )
    if confidence == "reject" and not blocker_codes:
        blocker_codes.append("manual_official_pdf_unknown_readiness")
    status = "registered_manual_official_pdf_evidence" if confidence in {"high", "medium"} else "blocked_manual_official_pdf_evidence"
    target_year_aligned = signals["report_year_verified"] if extraction_available else True
    evidence_id = f"rzd_manual_official_pdf_evidence:{original_sha[:16]}"
    row = {
        "evidence_id": evidence_id,
        "company_id": str(args.manual_official_company_id or ""),
        "company_name": str(args.manual_official_company_name or ""),
        "manual_source": True,
        "operator_supplied": True,
        "source_page_url": source_page_url,
        "source_page_host": source_host,
        "source_page_trusted": source_trusted,
        "source_page_fetch_required": False,
        "source_page_fetched": False,
        "document_url": _normalize_candidate_url(str(args.manual_official_document_url or "")) if str(args.manual_official_document_url or "").strip() else "",
        "document_url_known": bool(str(args.manual_official_document_url or "").strip()),
        "document_url_fetch_required": False,
        "document_url_fetched": False,
        "original_pdf_input_path": str(pdf_path or ""),
        "original_pdf_filename": pdf_path.name if isinstance(pdf_path, Path) else "",
        "original_pdf_size_bytes": len(pdf_bytes),
        "original_pdf_sha256": original_sha,
        "controlled_pdf_copy_path": str(copy_path or ""),
        "controlled_pdf_copy_filename": copy_path.name if copy_path is not None else "",
        "controlled_pdf_copy_size_bytes": copy_size,
        "controlled_pdf_copy_sha256": copy_sha,
        "controlled_pdf_copy_created": copy_created,
        "pdf_magic_header_valid": pdf_bytes.startswith(b"%PDF"),
        "pdf_page_count": int(metadata.get("page_count") or 0),
        "pdf_text_extraction_available": extraction_available,
        "pdf_text_extraction_backend": str(metadata.get("backend") or ""),
        "pdf_text_extraction_warning_codes": metadata_warning_codes,
        "pdf_raw_stream_rejected": bool(metadata.get("raw_stream_rejected")),
        "pdf_preview_page_count": int(metadata.get("preview_page_count") or 0),
        "pdf_preview_text_sha256": hashlib.sha256(text.encode("utf-8")).hexdigest() if text else "",
        "pdf_preview_text_char_count": len(text),
        "pdf_preview_text_normalized_char_count": len(signals["normalized_text"]),
        "pdf_preview_text_signal_sample": signals["signal_sample"],
        "company_signal_matches": signals["company_signal_matches"],
        "year_signal_matches": signals["year_signal_matches"],
        "standard_signal_matches": signals["standard_signal_matches"],
        "document_kind_signal_matches": signals["document_kind_signal_matches"],
        "financial_section_signal_matches": signals["financial_section_signal_matches"],
        "target_report_year": int(args.manual_official_report_year or 0),
        "detected_report_years": signals["detected_report_years"],
        "primary_detected_report_year": signals["primary_detected_report_year"],
        "target_year_aligned": target_year_aligned,
        "stale_year_mismatch": bool(signals["detected_report_years"] and not target_year_aligned),
        "unknown_year_candidate": bool(extraction_available and not signals["detected_report_years"]),
        "year_alignment_status": "target_year_aligned" if target_year_aligned else "stale_year_mismatch",
        "report_standard": str(args.manual_official_report_standard or ""),
        "detected_standard_hints": signals["detected_standard_hints"],
        "document_language": str(args.manual_official_document_language or ""),
        "document_kind": str(args.manual_official_document_kind or ""),
        "detected_document_kind_hints": signals["detected_document_kind_hints"],
        "company_name_detected": signals["company_name_detected"],
        "company_identity_verified_from_text": signals["company_identity_verified"],
        "report_year_verified_from_text": signals["report_year_verified"],
        "report_standard_verified_from_text": signals["report_standard_verified"],
        "document_kind_verified_from_text": signals["document_kind_verified"],
        "pdf_identity_verified_from_text": signals["pdf_identity_verified"],
        "document_title_detected": signals["document_title_detected"],
        "document_date_detected": signals["document_date_detected"],
        "auditor_detected": signals["auditor_detected"],
        "auditor_opinion_detected": signals["auditor_opinion_detected"],
        "financial_statement_sections_detected": signals["financial_statement_sections_detected"],
        "financial_statement_sections_count": signals["financial_statement_sections_count"],
        "manual_evidence_registration_status": status,
        "manual_evidence_registration_confidence": confidence,
        "manual_evidence_registration_reason_codes": _rzd_manual_official_pdf_evidence_reason_codes(row_status=status, extraction_available=extraction_available, source_trusted=source_trusted, copy_created=copy_created),
        "manual_evidence_registration_blocker_codes": blocker_codes,
        "manual_evidence_registration_warning_codes": warning_codes,
        "future_pdf_parse_plan_required": confidence in {"high", "medium"},
        "future_financial_value_extraction_required": False,
        "future_document_intake_registration_required": confidence in {"high", "medium"},
        "future_import_required": False,
        "future_scoring_required": False,
        "future_paper_trading_required": False,
        "would_fetch_source_page": False,
        "would_fetch_document_url": False,
        "would_download_document": False,
        "would_parse_financial_values": False,
        "would_mutate_document_intake": False,
        "would_mutate_database": False,
        "would_import_report": False,
        "would_mutate_scores": False,
        "would_trigger_paper_trading": False,
        "would_delete_files": False,
        "source_page_fetched_flag": False,
        "document_url_fetched_flag": False,
        "documents_downloaded": False,
        "documents_parsed": False,
        "financial_values_extracted": False,
        "document_intake_mutated": False,
        "database_mutated": False,
        "import_executed": False,
        "paper_trading_called": False,
        "files_deleted": False,
        "operator_action": "review_registered_manual_pdf_evidence_before_future_parse_plan",
        "safe_hint": "Task168 registers a local PDF evidence copy only; it does not fetch, download, parse financial values, import, or mutate production state.",
    }
    for field in RZD_MANUAL_OFFICIAL_PDF_EVIDENCE_ROW_BOOL_FIELDS:
        row[field] = bool(row.get(field))
    blocker_rows = [_rzd_manual_official_pdf_evidence_registration_blocker_row(row, code) for code in blocker_codes]
    if blocker_codes:
        forced_status = "failed"
    elif confidence == "high" and not warning_codes:
        forced_status = "passed"
    else:
        forced_status = "warning"
    warnings.extend({"message": code} for code in warning_codes if not any(item.get("message") == code for item in warnings))
    return [row], blocker_rows, warnings, forced_status


def _rzd_manual_official_pdf_preview_metadata(path: Path, max_pages: int) -> dict[str, Any]:
    for module_name in ("pypdf", "PyPDF2"):
        try:
            module = __import__(module_name)
            reader = module.PdfReader(str(path))
            pages = list(getattr(reader, "pages", []) or [])
            texts: list[str] = []
            for page in pages[:max_pages]:
                try:
                    texts.append(str(page.extract_text() or ""))
                except Exception:
                    continue
            text = "\n".join(texts)
            if text.strip():
                return {"available": True, "page_count": len(pages), "preview_page_count": min(len(pages), max_pages), "text": text, "warnings": []}
        except Exception:
            continue
    try:
        data = path.read_bytes()[:500_000]
    except OSError:
        data = b""
    fallback = data.decode("utf-8", errors="ignore")
    fallback = fallback if len(fallback.strip()) > 80 and any(term in fallback.casefold() for term in ("rzd", "ifrs", "мсфо", "2025", "report", "отчет", "отчёт")) else ""
    return {
        "available": bool(fallback),
        "page_count": 0,
        "preview_page_count": 0,
        "text": fallback,
        "warnings": [] if fallback else ["manual_official_pdf_text_extraction_unavailable"],
    }


def _rzd_manual_official_pdf_preview_extractors() -> list[tuple[str, Any]]:
    return [
        ("pypdf", lambda path, max_pages: _rzd_manual_official_pdf_preview_with_pypdf(path, max_pages, "pypdf")),
        ("PyPDF2", lambda path, max_pages: _rzd_manual_official_pdf_preview_with_pypdf(path, max_pages, "PyPDF2")),
        ("pdfminer.six", _rzd_manual_official_pdf_preview_with_pdfminer),
        ("pymupdf", _rzd_manual_official_pdf_preview_with_pymupdf),
        ("pdftotext", _rzd_manual_official_pdf_preview_with_pdftotext),
    ]


def _rzd_manual_official_pdf_preview_with_pypdf(path: Path, max_pages: int, module_name: str) -> dict[str, Any]:
    module = __import__(module_name)
    reader = module.PdfReader(str(path))
    pages = list(getattr(reader, "pages", []) or [])
    texts: list[str] = []
    for page in pages[:max_pages]:
        try:
            texts.append(str(page.extract_text() or ""))
        except Exception:
            continue
    return {
        "page_count": len(pages),
        "preview_page_count": min(len(pages), max_pages),
        "text": "\n".join(texts),
        "warnings": [],
    }


def _rzd_manual_official_pdf_preview_with_pdfminer(path: Path, max_pages: int) -> dict[str, Any]:
    high_level = __import__("pdfminer.high_level", fromlist=["extract_text"])
    text = high_level.extract_text(str(path), page_numbers=list(range(max_pages)))
    return {"page_count": 0, "preview_page_count": max_pages, "text": str(text or ""), "warnings": []}


def _rzd_manual_official_pdf_preview_with_pymupdf(path: Path, max_pages: int) -> dict[str, Any]:
    fitz = __import__("fitz")
    document = fitz.open(str(path))
    try:
        page_count = int(getattr(document, "page_count", len(document)))
        texts = [str(document.load_page(index).get_text("text") or "") for index in range(min(page_count, max_pages))]
        return {
            "page_count": page_count,
            "preview_page_count": min(page_count, max_pages),
            "text": "\n".join(texts),
            "warnings": [],
        }
    finally:
        document.close()


def _rzd_manual_official_pdf_preview_with_pdftotext(path: Path, max_pages: int) -> dict[str, Any]:
    executable = shutil.which("pdftotext")
    if not executable:
        return {"page_count": 0, "preview_page_count": 0, "text": "", "warnings": []}
    command = [executable, "-f", "1", "-l", str(max_pages), "-layout", "-enc", "UTF-8", str(path), "-"]
    result = subprocess.run(command, check=False, capture_output=True, timeout=30)
    text = result.stdout.decode("utf-8", errors="replace") if result.stdout else ""
    return {
        "page_count": 0,
        "preview_page_count": max_pages,
        "text": text,
        "warnings": [] if result.returncode == 0 else ["manual_official_pdf_text_extraction_unavailable"],
    }


def _rzd_pdf_preview_text_looks_like_raw_pdf(text: str) -> bool:
    folded = str(text or "").casefold()
    if not folded.strip():
        return False
    raw_tokens = ("%pdf-", " obj", "endobj", "stream", "endstream", "xref", "trailer", "startxref", "/flatedecode", "/linearized")
    token_count = sum(folded.count(token) for token in raw_tokens)
    return folded.lstrip().startswith("%pdf-") or token_count >= 4


def _rzd_pdf_preview_text_has_human_text(text: str) -> bool:
    value = str(text or "")
    non_space_count = len(re.sub(r"\s+", "", value))
    letter_count = len(re.findall(r"[A-Za-zА-Яа-яЁё]", value))
    if non_space_count < 100 or letter_count < 30:
        return False
    raw_token_count = sum(value.casefold().count(token) for token in (" obj", "endobj", "stream", "endstream", "xref", "startxref"))
    return raw_token_count < max(4, letter_count // 20)


def _rzd_manual_official_pdf_preview_metadata(path: Path, max_pages: int) -> dict[str, Any]:
    warnings: list[str] = []
    raw_stream_rejected = False
    for backend_name, extractor in _rzd_manual_official_pdf_preview_extractors():
        try:
            metadata = extractor(path, max_pages)
        except Exception:
            continue
        if not isinstance(metadata, dict):
            continue
        warnings.extend(str(code) for code in (metadata.get("warnings") or []) if str(code))
        text = str(metadata.get("text") or "")
        if not text.strip():
            continue
        if _rzd_pdf_preview_text_looks_like_raw_pdf(text):
            raw_stream_rejected = True
            warnings.append("manual_official_pdf_text_extraction_returned_raw_pdf_stream")
            continue
        if not _rzd_pdf_preview_text_has_human_text(text):
            warnings.append("manual_official_pdf_text_extraction_unavailable")
            continue
        return {
            "available": True,
            "backend": backend_name,
            "page_count": int(metadata.get("page_count") or 0),
            "preview_page_count": int(metadata.get("preview_page_count") or 0),
            "text": text,
            "warnings": list(dict.fromkeys(warnings)),
            "raw_stream_rejected": raw_stream_rejected,
        }
    if raw_stream_rejected:
        warnings.append("manual_official_pdf_text_extraction_returned_raw_pdf_stream")
    warnings.append("manual_official_pdf_text_extraction_unavailable")
    return {
        "available": False,
        "backend": "",
        "page_count": 0,
        "preview_page_count": 0,
        "text": "",
        "warnings": list(dict.fromkeys(warnings)),
        "raw_stream_rejected": raw_stream_rejected,
    }


def _rzd_manual_official_pdf_source_pack_row_is_rzd(row: dict[str, Any]) -> bool:
    identifiers = " ".join(
        str(row.get(key) or "")
        for key in (
            "company_id",
            "canonical_company_id",
            "company_name",
            "canonical_company_name",
            "issuer_name",
            "resolution_id",
        )
    ).casefold()
    return (
        "18" in {str(row.get("company_id") or ""), str(row.get("canonical_company_id") or "")}
        or "rzd" in identifiers
        or "ржд" in identifiers
        or "russian railways" in identifiers
    )


def _normalize_pdf_preview_text_for_signal_detection(text: str) -> dict[str, str]:
    normalized = unicodedata.normalize("NFKC", str(text or ""))
    replacements = {
        "\u00ad": "",
        "\ufeff": "",
        "\ufffe": "",
        "\u200b": "",
        "\u200c": "",
        "\u200d": "",
        "\xa0": " ",
        "“": '"',
        "”": '"',
        "„": '"',
        "«": '"',
        "»": '"',
        "‘": "'",
        "’": "'",
        "ё": "е",
        "Ё": "е",
    }
    for old, new in replacements.items():
        normalized = normalized.replace(old, new)
    normalized = normalized.casefold()
    normalized = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]+", " ", normalized)
    normalized = re.sub(r"(?<=[0-9a-zа-я])[\-‐‑‒–—]\s*(?=[a-zа-я])", "", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    compact = re.sub(r"[^0-9a-zа-я]+", "", normalized)
    return {"normalized_text": normalized, "compact_text": compact}


def _rzd_manual_official_pdf_phrase_found(phrase: str, normalized: str, compact: str) -> bool:
    prepared = _normalize_pdf_preview_text_for_signal_detection(phrase)
    return bool(
        (prepared["normalized_text"] and prepared["normalized_text"] in normalized)
        or (prepared["compact_text"] and prepared["compact_text"] in compact)
    )


def _rzd_manual_official_pdf_signal_matches(
    patterns: Sequence[tuple[str, str]],
    *,
    normalized: str,
    compact: str,
) -> list[str]:
    matches: list[str] = []
    for label, pattern in patterns:
        found = False
        if pattern.startswith("re:"):
            found = re.search(pattern[3:], normalized, flags=re.IGNORECASE | re.DOTALL) is not None
        else:
            found = _rzd_manual_official_pdf_phrase_found(pattern, normalized, compact)
        if found:
            matches.append(label)
    return matches


def _rzd_manual_official_pdf_evidence_text_signals(text: str, target_year: int) -> dict[str, Any]:
    prepared = _normalize_pdf_preview_text_for_signal_detection(text)
    normalized = prepared["normalized_text"]
    compact = prepared["compact_text"]
    years = sorted({int(match) for match in re.findall(r"\b(20[0-9]{2})\b", normalized)})
    company_patterns = (
        ("russian_railways_ru_nom", "российские железные дороги"),
        ("russian_railways_ru_gen", "российских железных дорог"),
        ("rzd_oao_plain", "оао ржд"),
        ("rzd_oao_quoted", 'оао "ржд"'),
        ("russian_railways_en", "russian railways"),
    )
    year_patterns = (
        ("december_31_ru", rf"re:31\s*декабр[яь]\s*{target_year}"),
        ("date_numeric", rf"re:31\s*[.]\s*12\s*[.]\s*{target_year}"),
        ("target_year_ru_short", rf"re:{target_year}\s*(?:г|год)"),
        ("year_ended_ru", rf"re:за\s+год[,\s\S]{{0,120}}31\s*декабр[яь]\s*{target_year}"),
        ("year_ended_numeric", rf"re:за\s+год[,\s\S]{{0,120}}31\s*[.]\s*12\s*[.]\s*{target_year}"),
        ("december_31_en", rf"re:31\s+december\s+{target_year}|december\s+31,\s*{target_year}"),
    )
    standard_patterns = (
        ("ifrs", "ifrs"),
        ("msfo", "мсфо"),
        ("mfso_typo", "мфсо"),
        ("international_financial_reporting_standards", "международные стандарты финансовой отчетности"),
        ("international_financial_reporting_standards_case", "международным стандартам финансовой отчетности"),
        ("standards_msfo", "стандарты финансовой отчетности мсфо"),
        ("iasb_msfo", "советом по мсфо"),
    )
    auditor_patterns = (
        ("auditor_report_ru", "аудиторское заключение"),
        ("independent_auditor_ru", "независимого аудитора"),
        ("independent_auditor_en", "independent auditor"),
        ("auditor_report_en", "auditor report"),
    )
    consolidated_patterns = (
        ("consolidated_financial_reporting_ru", "консолидированной финансовой отчетности"),
        ("consolidated_financial_statements_ru", "консолидированная финансовая отчетность"),
        ("consolidated_financial_statements_en", "consolidated financial statements"),
    )
    section_patterns = {
        "statement_of_financial_position": (
            "консолидированный отчет о финансовом положении",
            "statement of financial position",
            "financial position",
        ),
        "profit_or_loss": (
            "консолидированный отчет о прибылях и убытках",
            "profit or loss",
        ),
        "other_comprehensive_income": (
            "консолидированный отчет о прочем совокупном доходе",
            "comprehensive income",
        ),
        "changes_in_equity": (
            "консолидированный отчет об изменениях капитала",
            "changes in equity",
        ),
        "cash_flows": (
            "консолидированный отчет о движении денежных средств",
            "cash flows",
        ),
        "notes": (
            "примечания к консолидированной финансовой отчетности",
            "notes to financial statements",
            "notes to the consolidated financial statements",
        ),
    }
    company_matches = _rzd_manual_official_pdf_signal_matches(company_patterns, normalized=normalized, compact=compact)
    year_matches = _rzd_manual_official_pdf_signal_matches(year_patterns, normalized=normalized, compact=compact)
    standard_matches = _rzd_manual_official_pdf_signal_matches(standard_patterns, normalized=normalized, compact=compact)
    auditor_matches = _rzd_manual_official_pdf_signal_matches(auditor_patterns, normalized=normalized, compact=compact)
    consolidated_matches = _rzd_manual_official_pdf_signal_matches(consolidated_patterns, normalized=normalized, compact=compact)
    section_matches: list[str] = []
    for section, phrases in section_patterns.items():
        if any(_rzd_manual_official_pdf_phrase_found(phrase, normalized, compact) for phrase in phrases):
            section_matches.append(section)
    rzd_context = bool(consolidated_matches) and bool(year_matches) and ("дочерн" in normalized or "subsidiar" in normalized or bool(section_matches))
    rzd_abbrev_in_text = _rzd_manual_official_pdf_phrase_found("ржд", normalized, compact)
    company_verified = bool(company_matches) or (rzd_abbrev_in_text and rzd_context)
    year_verified = bool(year_matches) or (target_year in years and (bool(consolidated_matches) or bool(section_matches)))
    standard_verified = bool(standard_matches)
    kind_verified = bool(auditor_matches) and bool(consolidated_matches) and bool(section_matches)
    date_match = re.search(rf"(31\s+декабр[яь]\s+{target_year}|31\s+december\s+{target_year}|december\s+31,\s*{target_year}|март\s+20\d{{2}}|20\d{{2}}\s*г\.)", normalized, flags=re.IGNORECASE)
    title_match = re.search(r"(аудиторское заключение.{0,160}|consolidated financial statements.{0,160})", normalized, flags=re.IGNORECASE | re.DOTALL)
    kind_matches = [*auditor_matches, *consolidated_matches]
    return {
        "detected_report_years": years,
        "primary_detected_report_year": years[0] if years else 0,
        "detected_standard_hints": standard_matches,
        "detected_document_kind_hints": kind_matches,
        "company_name_detected": "Russian Railways/RZD" if company_verified else "",
        "company_identity_verified": company_verified,
        "report_year_verified": year_verified,
        "report_standard_verified": standard_verified,
        "document_kind_verified": kind_verified,
        "pdf_identity_verified": company_verified and year_verified and standard_verified and kind_verified,
        "document_title_detected": title_match.group(0).strip() if title_match else "",
        "document_date_detected": date_match.group(0).strip() if date_match else "",
        "auditor_detected": bool(auditor_matches),
        "auditor_opinion_detected": bool(auditor_matches),
        "financial_statement_sections_detected": section_matches,
        "financial_statement_sections_count": len(section_matches),
        "normalized_text": normalized,
        "signal_sample": normalized[:1000],
        "company_signal_matches": company_matches + (["rzd_abbrev_with_context"] if not company_matches and rzd_abbrev_in_text and rzd_context else []),
        "year_signal_matches": year_matches,
        "standard_signal_matches": standard_matches,
        "document_kind_signal_matches": kind_matches,
        "financial_section_signal_matches": section_matches,
    }


def _rzd_manual_official_pdf_evidence_reason_codes(*, row_status: str, extraction_available: bool, source_trusted: bool, copy_created: bool) -> list[str]:
    codes = ["manual_official_pdf_evidence_registration_preview"]
    if source_trusted:
        codes.append("trusted_source_page_context")
    if copy_created:
        codes.append("controlled_pdf_copy_created")
    if extraction_available:
        codes.append("pdf_text_preview_extracted")
    if row_status == "registered_manual_official_pdf_evidence":
        codes.append("future_pdf_parse_plan_candidate_only")
    return codes


