def _rzd_controlled_value_extraction_is_tax_note_context(text: str, page_row: dict[str, Any]) -> bool:
    prepared = _normalize_pdf_preview_text_for_signal_detection(
        " ".join(
            [
                str(page_row.get("detected_section_title") or ""),
                str(page_row.get("detected_section_type") or ""),
                str(text or ""),
            ]
        )
    )
    normalized = prepared["normalized_text"]
    compact = prepared["compact_text"]
    tax_terms = (
        "income tax",
        "tax expense",
        "deferred tax",
        "current tax",
        "налог на прибыль",
        "отложенный налог",
        "текущий налог",
    )
    note_terms = (
        "notes",
        "note ",
        "примечания",
        "в составе статьи",
        "за год, закончившийся 31 декабря",
        "консолидированного отчета о прибылях и убытках",
    )
    return bool(
        _rzd_controlled_value_extraction_phrase_count(tax_terms, normalized, compact)
        and (_as_bool(page_row.get("is_notes_page")) or _rzd_controlled_value_extraction_phrase_count(note_terms, normalized, compact))
    )


def _rzd_controlled_value_extraction_scan_target_value_rows(
    target_type: str,
    text: str,
    *,
    page_number: int = 0,
    is_contents_page: bool = False,
) -> dict[str, Any]:
    specs = _rzd_manual_official_pdf_controlled_value_extraction_metric_specs().get(target_type, [])
    target_metric_keys = _rzd_controlled_value_extraction_target_metric_keys(target_type)
    broad_pl_keys = _rzd_controlled_value_extraction_profit_or_loss_broad_metric_keys()
    metric_keys: set[str] = set()
    broad_metric_keys: set[str] = set()
    scanned_count = 0
    matched_count = 0
    rejected_count = 0
    date_rejected_count = 0
    contents_rejected_count = 0
    small_rejected_count = 0
    for raw_line in str(text or "").splitlines():
        stripped_line = raw_line.strip()
        if not stripped_line:
            continue
        scanned_count += 1
        if _rzd_controlled_value_extraction_is_contents_or_navigation_line(raw_line, is_contents_page=is_contents_page):
            contents_rejected_count += 1
            rejected_count += 1
            continue
        if _rzd_controlled_value_extraction_is_date_or_period_line(raw_line):
            columns = _rzd_controlled_value_extraction_value_columns(raw_line)
            values = [columns.get("value_2025"), columns.get("value_2024")]
            if sum(1 for value in values if isinstance(value, int) and abs(value) >= 100) < 2:
                date_rejected_count += 1
                rejected_count += 1
                continue
        for spec in specs:
            metric_key = str(spec.get("metric_key") or "")
            if metric_key in metric_keys or metric_key not in target_metric_keys:
                continue
            if not _rzd_manual_official_pdf_controlled_value_extraction_line_matches_metric(raw_line, spec):
                continue
            matched_count += 1
            columns = _rzd_controlled_value_extraction_value_columns(raw_line)
            value_2025 = columns.get("value_2025")
            value_2024 = columns.get("value_2024")
            if not isinstance(value_2025, int) and not isinstance(value_2024, int):
                rejected_count += 1
                continue
            reject_code = _rzd_controlled_value_extraction_reject_value_columns(
                line=raw_line,
                page_number=page_number,
                value_2025=value_2025 if isinstance(value_2025, int) else None,
                value_2024=value_2024 if isinstance(value_2024, int) else None,
                primary_statement_page_accepted=True,
            )
            if reject_code:
                if reject_code == "date_period_line_value_rejected":
                    date_rejected_count += 1
                else:
                    small_rejected_count += 1
                rejected_count += 1
                continue
            metric_keys.add(metric_key)
            if metric_key in broad_pl_keys:
                broad_metric_keys.add(metric_key)
    return {
        "metric_keys": sorted(metric_keys),
        "broad_profit_or_loss_metric_keys": sorted(broad_metric_keys),
        "value_row_count": len(metric_keys),
        "broad_profit_or_loss_value_row_count": len(broad_metric_keys),
        "candidate_line_scanned_count": scanned_count,
        "candidate_line_matched_count": matched_count,
        "candidate_line_rejected_count": rejected_count,
        "contents_navigation_line_rejected_count": contents_rejected_count,
        "date_period_line_rejected_count": date_rejected_count,
        "small_page_or_note_number_value_rejected_count": small_rejected_count,
    }


def _rzd_controlled_value_extraction_internal_candidate_rows_from_text(
    target_type: str,
    text: str,
    *,
    page_number: int,
    is_contents_page: bool = False,
    title_match_info: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    title_match_info = title_match_info if isinstance(title_match_info, dict) else {}
    title_anchored = _as_bool(title_match_info.get("target_title_matched")) and not _as_bool(title_match_info.get("cross_target_title_detected"))
    diagnostics = _rzd_controlled_value_extraction_table_parser_diagnostics()
    specs = _rzd_manual_official_pdf_controlled_value_extraction_metric_specs().get(target_type, [])
    target_metric_keys = _rzd_controlled_value_extraction_target_metric_keys(target_type)
    table_rows, table_diagnostics = _rzd_controlled_value_extraction_parse_primary_statement_table_rows(
        target_type=target_type,
        page_number=page_number,
        page_text=text,
        text_source="",
        text_backend="",
        is_contents_page=is_contents_page,
    )
    rows: list[dict[str, Any]] = list(table_rows)
    matched_metrics: set[str] = {str(row.get("metric_key") or "") for row in rows if row.get("metric_key")}
    parser_line_hashes: set[str] = {str(row.get("raw_line_sha256") or "") for row in rows if row.get("raw_line_sha256")}
    for key, value in table_diagnostics.items():
        if isinstance(value, bool):
            diagnostics[key] = bool(value)
        elif isinstance(value, int):
            diagnostics[key] = int(diagnostics.get(key) or 0) + int(value)
        elif isinstance(value, list):
            diagnostics[key] = list(dict.fromkeys([*(diagnostics.get(key) or []), *value]))
        else:
            diagnostics[key] = value
    for line_number, raw_line in enumerate(str(text or "").splitlines(), start=1):
        stripped_line = raw_line.strip()
        if not stripped_line:
            continue
        if hashlib.sha256(raw_line.encode("utf-8")).hexdigest() in parser_line_hashes:
            continue
        diagnostics["candidate_line_scanned_count"] += 1
        if target_type == "other_comprehensive_income" and _rzd_controlled_value_extraction_is_wide_equity_movement_line(raw_line):
            diagnostics["wide_equity_movement_line_rejected_count"] += 1
            diagnostics["wide_equity_movement_value_rejected_count"] += 1
            diagnostics["candidate_line_rejected_count"] += 1
            continue
        if _rzd_controlled_value_extraction_is_contents_or_navigation_line(raw_line, is_contents_page=is_contents_page):
            diagnostics["contents_navigation_line_rejected_count"] += 1
            diagnostics["candidate_line_rejected_count"] += 1
            continue
        if _rzd_controlled_value_extraction_is_date_or_period_line(raw_line):
            columns = _rzd_controlled_value_extraction_value_columns(raw_line)
            values = [columns.get("value_2025"), columns.get("value_2024")]
            if sum(1 for value in values if isinstance(value, int) and abs(value) >= 100) < 2:
                diagnostics["date_period_line_rejected_count"] += 1
                diagnostics["date_number_value_rejected_count"] += 1
                diagnostics["candidate_line_rejected_count"] += 1
                continue
        for spec in specs:
            metric_key = str(spec.get("metric_key") or "")
            if metric_key in matched_metrics or metric_key not in target_metric_keys:
                continue
            if not _rzd_manual_official_pdf_controlled_value_extraction_line_matches_metric(raw_line, spec):
                continue
            diagnostics["candidate_line_matched_count"] += 1
            columns = _rzd_controlled_value_extraction_value_columns(raw_line)
            raw_2025 = str(columns.get("raw_2025") or "")
            value_2025 = columns.get("value_2025")
            raw_2024 = str(columns.get("raw_2024") or "")
            value_2024 = columns.get("value_2024")
            numbers = [(raw_2025, value_2025)] if value_2024 is None else [(raw_2025, value_2025), (raw_2024, value_2024)]
            numbers = [(raw, value) for raw, value in numbers if value is not None]
            if len(numbers) < 1:
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            if len(numbers) == 1:
                value = numbers[0][1]
                prepared_line = _normalize_pdf_preview_text_for_signal_detection(raw_line)
                has_year_columns = "2025" in prepared_line["normalized_text"] or "2024" in prepared_line["normalized_text"]
                has_unit_context = any(
                    _rzd_manual_official_pdf_phrase_found(term, prepared_line["normalized_text"], prepared_line["compact_text"])
                    for term in ("million rubles", "млн руб", "миллионах рублей")
                )
                if value is not None and 0 < abs(value) < 300 and not has_year_columns and not has_unit_context:
                    diagnostics["page_number_value_rejected_count"] += 1
                    diagnostics["candidate_line_rejected_count"] += 1
                    continue
            raw_2025, value_2025 = numbers[-2] if len(numbers) >= 2 else numbers[-1]
            raw_2024, value_2024 = numbers[-1] if len(numbers) >= 2 else ("", None)
            reject_code = _rzd_controlled_value_extraction_reject_value_columns(
                line=raw_line,
                page_number=page_number,
                value_2025=value_2025 if isinstance(value_2025, int) else None,
                value_2024=value_2024 if isinstance(value_2024, int) else None,
                primary_statement_page_accepted=True,
            )
            if reject_code:
                if reject_code == "date_period_line_value_rejected":
                    diagnostics["date_period_line_rejected_count"] += 1
                    diagnostics["date_number_value_rejected_count"] += 1
                else:
                    diagnostics["small_page_or_note_number_value_rejected_count"] += 1
                    diagnostics["page_number_value_rejected_count"] += 1
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            note_match = re.search(r"\b(?:note|примечание)\s*(\d+[A-Za-zА-Яа-я]?)", raw_line, re.IGNORECASE)
            metric_role = _rzd_controlled_value_extraction_metric_role(target_type, metric_key)
            aggregate_priority = _rzd_controlled_value_extraction_aggregate_match_priority(target_type, metric_key, raw_line)
            precision_codes = _rzd_controlled_value_extraction_bad_aggregate_precision_codes(
                {
                    "target_type": target_type,
                    "metric_key": metric_key,
                    "metric_role": metric_role,
                    "aggregate_match_priority": aggregate_priority,
                    "raw_line": raw_line,
                    "value_2025": value_2025,
                    "value_2024": value_2024,
                }
            )
            if precision_codes:
                diagnostics["bad_aggregate_precision_row_count"] += 1
                if "component_row_mapped_to_aggregate_rejected" in precision_codes:
                    diagnostics["component_row_mapped_to_aggregate_rejected_count"] += 1
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            semantic_reject_codes = _rzd_controlled_value_extraction_semantic_reject_metric(target_type, metric_key, raw_line)
            if semantic_reject_codes:
                if "semantic_component_oci_row_rejected" in semantic_reject_codes:
                    diagnostics["semantic_component_oci_row_rejected_count"] += 1
                if "semantic_wrong_aggregate_row_rejected" in semantic_reject_codes:
                    diagnostics["semantic_wrong_aggregate_row_rejected_count"] += 1
                if "semantic_cash_flow_starting_profit_row_rejected" in semantic_reject_codes:
                    diagnostics["semantic_cash_flow_starting_profit_row_rejected_count"] += 1
                if "semantic_cash_flow_component_row_rejected" in semantic_reject_codes:
                    diagnostics["semantic_cash_flow_component_row_rejected_count"] += 1
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            confidence = "high" if value_2025 is not None and value_2024 is not None else "medium"
            rows.append(
                {
                    "target_type": target_type,
                    "metric_key": metric_key,
                    "metric_role": metric_role,
                    "aggregate_match_priority": aggregate_priority,
                    "metric_name_ru": spec.get("name_ru") or "",
                    "metric_name_en": spec.get("name_en") or "",
                    "page_number": page_number,
                    "statement_page": page_number,
                    "line_number": line_number,
                    "line_number_on_page": line_number,
                    "raw_line": raw_line.strip(),
                    "raw_line_sha256": hashlib.sha256(raw_line.encode("utf-8")).hexdigest(),
                    "raw_value_2025": raw_2025,
                    "value_2025": value_2025,
                    "value_2025_present": value_2025 is not None,
                    "raw_value_2024": raw_2024,
                    "value_2024": value_2024,
                    "value_2024_present": value_2024 is not None,
                    "unit": "RUB million",
                    "scale": 1000000,
                "note_reference": str(columns.get("note_reference") or (note_match.group(1) if note_match else "")),
                "row_label": raw_line.strip()[:160],
                "extraction_method": "controlled_static_line_metric_match",
                "value_extraction_method": "controlled_static_line_metric_match",
                "extraction_confidence": confidence,
                    "extraction_status": "candidate_value_extracted_for_human_review",
                    "reason_codes": ["metric_label_matched", "controlled_value_extraction_preview_only"],
                    "warning_codes": ["controlled_value_extraction_human_review_required"] if confidence == "medium" else [],
                    "blocker_codes": [],
                    "generic_metric": False,
                    "title_anchored_value": bool(title_anchored),
                    "cross_target_page_value": False,
                }
            )
            matched_metrics.add(metric_key)
    if target_type in {"statement_of_financial_position", "profit_or_loss"} and title_anchored:
        existing_line_hashes = {str(row.get("raw_line_sha256") or "") for row in rows}
        for line_number, raw_line in enumerate(str(text or "").splitlines(), start=1):
            stripped_line = raw_line.strip()
            if not stripped_line:
                continue
            raw_line_hash = hashlib.sha256(raw_line.encode("utf-8")).hexdigest()
            if raw_line_hash in existing_line_hashes:
                continue
            if target_type == "other_comprehensive_income" and _rzd_controlled_value_extraction_is_wide_equity_movement_line(raw_line):
                continue
            if _rzd_controlled_value_extraction_is_contents_or_navigation_line(raw_line, is_contents_page=is_contents_page):
                continue
            if _rzd_controlled_value_extraction_is_date_or_period_line(raw_line):
                continue
            line_prepared = _normalize_pdf_preview_text_for_signal_detection(raw_line)
            if _rzd_controlled_value_extraction_phrase_count(
                _rzd_controlled_value_extraction_statement_title_terms(target_type),
                line_prepared["normalized_text"],
                line_prepared["compact_text"],
            ):
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            if not re.search(r"[A-Za-zА-Яа-я]", raw_line):
                continue
            columns = _rzd_controlled_value_extraction_value_columns(raw_line)
            raw_2025 = str(columns.get("raw_2025") or "")
            value_2025 = columns.get("value_2025")
            raw_2024 = str(columns.get("raw_2024") or "")
            value_2024 = columns.get("value_2024")
            if not isinstance(value_2025, int) or not isinstance(value_2024, int):
                continue
            reject_code = _rzd_controlled_value_extraction_reject_value_columns(
                line=raw_line,
                page_number=page_number,
                value_2025=value_2025,
                value_2024=value_2024,
                primary_statement_page_accepted=True,
            )
            if reject_code:
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            if target_type == "profit_or_loss" and _rzd_controlled_value_extraction_is_tax_note_context(raw_line, {}):
                diagnostics["candidate_line_rejected_count"] += 1
                continue
            is_false_generic, false_generic_codes = _rzd_controlled_value_extraction_is_false_generic_statement_row(
                target_type,
                raw_line,
                columns,
                text,
            )
            if is_false_generic:
                diagnostics["false_generic_statement_row_rejected_count"] += 1
                diagnostics["candidate_line_rejected_count"] += 1
                if "generic_row_fx_rate_rejected" in false_generic_codes:
                    diagnostics["generic_row_fx_rate_rejected_count"] += 1
                if "generic_row_percent_or_discount_rejected" in false_generic_codes:
                    diagnostics["generic_row_percent_or_discount_rejected_count"] += 1
                if "generic_row_statement_reference_rejected" in false_generic_codes:
                    diagnostics["generic_row_statement_reference_rejected_count"] += 1
                    if _rzd_controlled_value_extraction_is_statement_body_reference(raw_line):
                        diagnostics["body_reference_title_value_rejected_count"] += 1
                if "generic_row_date_or_period_rejected" in false_generic_codes:
                    diagnostics["generic_row_date_or_period_rejected_count"] += 1
                continue
            slug = re.sub(r"[^a-z0-9]+", "_", line_prepared["normalized_text"])
            slug = slug.strip("_")[:40] or hashlib.sha1(raw_line.encode("utf-8")).hexdigest()[:10]
            metric_prefix = "generic_profit_or_loss" if target_type == "profit_or_loss" else "generic_statement_of_financial_position"
            metric_key = f"{metric_prefix}_{slug}_{hashlib.sha1(raw_line.encode('utf-8')).hexdigest()[:8]}"
            diagnostics["candidate_line_matched_count"] += 1
            rows.append(
                {
                    "target_type": target_type,
                    "metric_key": metric_key,
                    "metric_name_ru": raw_line.strip()[:120],
                    "metric_name_en": raw_line.strip()[:120],
                    "page_number": page_number,
                    "statement_page": page_number,
                    "line_number": line_number,
                    "line_number_on_page": line_number,
                    "raw_line": raw_line.strip(),
                    "raw_line_sha256": raw_line_hash,
                    "raw_value_2025": raw_2025,
                    "value_2025": value_2025,
                    "value_2025_present": True,
                    "raw_value_2024": raw_2024,
                    "value_2024": value_2024,
                    "value_2024_present": True,
                    "unit": "RUB million",
                    "scale": 1000000,
                    "note_reference": str(columns.get("note_reference") or ""),
                    "row_label": raw_line.strip()[:160],
                    "extraction_method": "controlled_static_title_anchored_generic_line_match",
                    "value_extraction_method": "controlled_static_title_anchored_generic_line_match",
                    "extraction_confidence": "medium",
                    "extraction_status": "candidate_value_extracted_for_human_review",
                    "reason_codes": [
                        "generic_title_anchored_primary_statement_row",
                        "valid_generic_profit_or_loss_row" if target_type == "profit_or_loss" else "valid_generic_primary_statement_row",
                        "controlled_value_extraction_preview_only",
                    ],
                    "warning_codes": ["controlled_value_extraction_human_review_required"],
                    "blocker_codes": [],
                    "generic_metric": True,
                    "title_anchored_value": True,
                    "cross_target_page_value": False,
                }
            )
            existing_line_hashes.add(raw_line_hash)
    return rows, diagnostics


def _rzd_controlled_value_extraction_discover_candidate_rows_for_target(
    target_type: str,
    candidate_pages: list[int],
    page_texts: dict[int, dict],
    page_map_by_page: dict[int, dict],
    allow_notes_pages: bool,
    candidate_metadata_by_page: dict[int, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    candidate_metadata_by_page = candidate_metadata_by_page or {}
    unique_pages = [page for page in dict.fromkeys(int(page) for page in candidate_pages if int(page) > 0)]
    bounded_pages = unique_pages[:RZD_CONTROLLED_VALUE_EXTRACTION_MAX_DISCOVERY_PAGES_PER_TARGET]
    candidate_rows_by_page: dict[int, list[dict[str, Any]]] = {}
    page_scores: dict[int, dict[str, Any]] = {}
    page_reject_reason_codes: dict[int, list[str]] = {}
    title_matches_by_page: dict[int, dict[str, Any]] = {}
    rejected_page_count = 0
    rejected_line_count = 0
    title_anchor_page_count = 0
    cross_target_page_rejected_count = 0
    cross_target_value_rejected_count = 0
    wide_equity_movement_line_rejected_count = 0
    wide_equity_movement_value_rejected_count = 0
    tax_note_page_rejected_count = 0
    false_generic_statement_row_rejected_count = 0
    generic_row_fx_rate_rejected_count = 0
    generic_row_percent_or_discount_rejected_count = 0
    generic_row_statement_reference_rejected_count = 0
    generic_row_date_or_period_rejected_count = 0
    body_reference_title_rejected_count = 0
    body_reference_title_value_rejected_count = 0
    semantic_component_oci_row_rejected_count = 0
    semantic_wrong_aggregate_row_rejected_count = 0
    semantic_cash_flow_starting_profit_row_rejected_count = 0
    semantic_cash_flow_component_row_rejected_count = 0
    bad_aggregate_precision_row_count = 0
    component_row_mapped_to_aggregate_rejected_count = 0
    toc_notes_range_page_rejected_count = 0
    toc_notes_range_value_rejected_count = 0
    page_map_false_statement_flag_rejected_count = 0
    contents_page_primary_rejected_count = 0
    primary_statement_table_row_parser_attempt_count = 0
    primary_statement_table_row_parser_success_count = 0
    primary_statement_table_row_parser_failed_count = 0
    primary_statement_table_row_value_count = 0
    primary_statement_table_row_parser_zero_value_page_count = 0
    for page_number in bounded_pages:
        page_row = page_map_by_page.get(page_number) or {}
        page_meta = candidate_metadata_by_page.get(page_number) or {}
        reject_codes: list[str] = []
        if _as_bool(page_row.get("is_contents_page")):
            reject_codes.append("contents_page_not_primary_statement")
        if _as_bool(page_meta.get("contents_page_rejected_as_primary")):
            reject_codes.append("contents_page_not_primary_statement")
            contents_page_primary_rejected_count += 1
        if _as_bool(page_row.get("is_auditor_report_page")):
            reject_codes.append("auditor_report_page_not_primary_statement")
        if _as_bool(page_row.get("is_notes_page")) and not allow_notes_pages:
            reject_codes.append("notes_page_not_primary_statement")
        if _as_bool(page_meta.get("toc_notes_range_rejected")):
            reject_codes.append("toc_notes_range_not_primary_statement")
            toc_notes_range_page_rejected_count += 1
        if _as_bool(page_meta.get("page_map_false_statement_flag_rejected")):
            reject_codes.append("page_map_false_statement_flag_rejected")
            page_map_false_statement_flag_rejected_count += 1
        text = str((page_texts.get(page_number) or {}).get("text") or page_row.get("page_text_sample") or "")
        title_match = _rzd_controlled_value_extraction_statement_title_match(target_type, text, page_row)
        title_matches_by_page[page_number] = title_match
        body_reference_title_rejected_count += int(title_match.get("body_reference_title_rejected_count") or 0)
        wide_rejected = 0
        if _as_bool(title_match.get("target_title_matched")) and not _as_bool(title_match.get("cross_target_title_detected")):
            title_anchor_page_count += 1
        if _as_bool(title_match.get("cross_target_title_detected")):
            reject_codes = list(dict.fromkeys([*reject_codes, "controlled_value_extraction_cross_target_page_rejected"]))
            cross_target_page_rejected_count += 1
            if target_type == "other_comprehensive_income":
                wide_rejected = sum(
                    1
                    for line in str(text or "").splitlines()
                    if _rzd_controlled_value_extraction_is_wide_equity_movement_line(line)
                )
        title_score = 20 * _rzd_controlled_value_extraction_phrase_count(
            _rzd_controlled_value_extraction_statement_title_terms(target_type),
            _normalize_pdf_preview_text_for_signal_detection(text)["normalized_text"],
            _normalize_pdf_preview_text_for_signal_detection(text)["compact_text"],
        )
        hint_bonus = 0
        if _as_bool(page_row.get(f"is_{target_type}_page")):
            hint_bonus += 30
        if page_row.get("detected_section_type") == target_type:
            hint_bonus += 20
        toc_enforced_effective_text = _as_bool(page_meta.get("toc_primary_page_enforced_extraction")) and bool(text.strip())
        if reject_codes and toc_enforced_effective_text:
            candidate_rows, diagnostics = _rzd_controlled_value_extraction_parse_primary_statement_table_rows(
                target_type=target_type,
                page_number=page_number,
                page_text=text,
                text_source=str((page_texts.get(page_number) or {}).get("effective_page_text_source") or "toc_enforced_effective_page_text"),
                text_backend=str((page_texts.get(page_number) or {}).get("effective_page_text_backend") or (page_texts.get(page_number) or {}).get("backend") or ""),
                is_contents_page=False,
            )
            reject_codes = []
        elif reject_codes:
            candidate_rows: list[dict[str, Any]] = []
            if _rzd_controlled_value_extraction_is_tax_note_context(text, page_row):
                tax_note_page_rejected_count += 1
            diagnostics = _rzd_controlled_value_extraction_table_parser_diagnostics()
            diagnostics["wide_equity_movement_line_rejected_count"] = wide_rejected
            diagnostics["wide_equity_movement_value_rejected_count"] = wide_rejected
            if _as_bool(title_match.get("cross_target_title_detected")):
                cross_target_value_rejected_count += len(_rzd_controlled_value_extraction_numeric_groups(text))
            if _as_bool(page_meta.get("toc_notes_range_rejected")):
                toc_notes_range_value_rejected_count += len(_rzd_controlled_value_extraction_numeric_groups(text))
            rejected_page_count += 1
        else:
            candidate_rows, diagnostics = _rzd_controlled_value_extraction_internal_candidate_rows_from_text(
                target_type,
                text,
                page_number=page_number,
                is_contents_page=_as_bool(page_row.get("is_contents_page")),
                title_match_info=title_match,
            )
        text_info = page_texts.get(page_number) or {}
        value_text_source = str(text_info.get("effective_page_text_source") or ("controlled_pdf_selected_page_text" if text.strip() else ""))
        value_text_backend = str(text_info.get("effective_page_text_backend") or text_info.get("backend") or "")
        for candidate_row in candidate_rows:
            candidate_row["value_text_source"] = value_text_source
            candidate_row["value_text_backend"] = value_text_backend
        metric_keys = {str(row.get("metric_key") or "") for row in candidate_rows}
        broad_metric_keys = metric_keys & _rzd_controlled_value_extraction_profit_or_loss_broad_metric_keys()
        table_score = len(metric_keys) * 50 + sum(1 for row in candidate_rows if row.get("value_2025_present") and row.get("value_2024_present")) * 10
        note_penalty = 75 if _rzd_controlled_value_extraction_is_tax_note_context(text, page_row) else 0
        page_total_score = int(table_score + title_score + hint_bonus - note_penalty)
        rejected_line_count += int(diagnostics.get("candidate_line_rejected_count") or 0)
        wide_equity_movement_line_rejected_count += int(diagnostics.get("wide_equity_movement_line_rejected_count") or 0)
        wide_equity_movement_value_rejected_count += int(diagnostics.get("wide_equity_movement_value_rejected_count") or 0)
        false_generic_statement_row_rejected_count += int(diagnostics.get("false_generic_statement_row_rejected_count") or 0)
        generic_row_fx_rate_rejected_count += int(diagnostics.get("generic_row_fx_rate_rejected_count") or 0)
        generic_row_percent_or_discount_rejected_count += int(diagnostics.get("generic_row_percent_or_discount_rejected_count") or 0)
        generic_row_statement_reference_rejected_count += int(diagnostics.get("generic_row_statement_reference_rejected_count") or 0)
        generic_row_date_or_period_rejected_count += int(diagnostics.get("generic_row_date_or_period_rejected_count") or 0)
        body_reference_title_value_rejected_count += int(diagnostics.get("body_reference_title_value_rejected_count") or 0)
        semantic_component_oci_row_rejected_count += int(diagnostics.get("semantic_component_oci_row_rejected_count") or 0)
        semantic_wrong_aggregate_row_rejected_count += int(diagnostics.get("semantic_wrong_aggregate_row_rejected_count") or 0)
        semantic_cash_flow_starting_profit_row_rejected_count += int(
            diagnostics.get("semantic_cash_flow_starting_profit_row_rejected_count") or 0
        )
        semantic_cash_flow_component_row_rejected_count += int(
            diagnostics.get("semantic_cash_flow_component_row_rejected_count") or 0
        )
        bad_aggregate_precision_row_count += int(diagnostics.get("bad_aggregate_precision_row_count") or 0)
        component_row_mapped_to_aggregate_rejected_count += int(
            diagnostics.get("component_row_mapped_to_aggregate_rejected_count") or 0
        )
        if _as_bool(diagnostics.get("primary_statement_table_row_parser_attempted")):
            primary_statement_table_row_parser_attempt_count += 1
            if _as_bool(diagnostics.get("primary_statement_table_row_parser_success")):
                primary_statement_table_row_parser_success_count += 1
            else:
                primary_statement_table_row_parser_failed_count += 1
            parser_value_count = int(diagnostics.get("primary_statement_table_row_parser_value_count") or 0)
            primary_statement_table_row_value_count += parser_value_count
            if parser_value_count == 0:
                primary_statement_table_row_parser_zero_value_page_count += 1
        candidate_rows_by_page[page_number] = candidate_rows
        page_reject_reason_codes[page_number] = reject_codes
        page_scores[page_number] = {
            "page_value_row_count": len(candidate_rows),
            "page_required_metric_hit_count": len(metric_keys),
            "page_broad_metric_hit_count": len(broad_metric_keys),
            "page_title_score": int(title_score),
            "page_table_score": int(table_score),
            "page_note_penalty": int(note_penalty),
            "page_total_discovery_score": page_total_score,
            "target_title_matched": _as_bool(title_match.get("target_title_matched")),
            "cross_target_title_detected": _as_bool(title_match.get("cross_target_title_detected")),
            "cross_target_title_type": str(title_match.get("cross_target_title_type") or ""),
            "candidate_line_scanned_count": int(diagnostics.get("candidate_line_scanned_count") or 0),
            "candidate_line_matched_count": int(diagnostics.get("candidate_line_matched_count") or 0),
            "candidate_line_rejected_count": int(diagnostics.get("candidate_line_rejected_count") or 0),
            "contents_navigation_line_rejected_count": int(diagnostics.get("contents_navigation_line_rejected_count") or 0),
            "page_number_value_rejected_count": int(diagnostics.get("page_number_value_rejected_count") or 0),
            "date_period_line_rejected_count": int(diagnostics.get("date_period_line_rejected_count") or 0),
            "date_number_value_rejected_count": int(diagnostics.get("date_number_value_rejected_count") or 0),
            "small_page_or_note_number_value_rejected_count": int(diagnostics.get("small_page_or_note_number_value_rejected_count") or 0),
            "wide_equity_movement_line_rejected_count": int(diagnostics.get("wide_equity_movement_line_rejected_count") or 0),
            "wide_equity_movement_value_rejected_count": int(diagnostics.get("wide_equity_movement_value_rejected_count") or 0),
            "false_generic_statement_row_rejected_count": int(diagnostics.get("false_generic_statement_row_rejected_count") or 0),
            "generic_row_fx_rate_rejected_count": int(diagnostics.get("generic_row_fx_rate_rejected_count") or 0),
            "generic_row_percent_or_discount_rejected_count": int(diagnostics.get("generic_row_percent_or_discount_rejected_count") or 0),
            "generic_row_statement_reference_rejected_count": int(diagnostics.get("generic_row_statement_reference_rejected_count") or 0),
            "generic_row_date_or_period_rejected_count": int(diagnostics.get("generic_row_date_or_period_rejected_count") or 0),
            "body_reference_title_rejected_count": int(title_match.get("body_reference_title_rejected_count") or 0),
            "body_reference_title_value_rejected_count": int(diagnostics.get("body_reference_title_value_rejected_count") or 0),
            "semantic_component_oci_row_rejected_count": int(diagnostics.get("semantic_component_oci_row_rejected_count") or 0),
            "semantic_wrong_aggregate_row_rejected_count": int(diagnostics.get("semantic_wrong_aggregate_row_rejected_count") or 0),
            "semantic_cash_flow_starting_profit_row_rejected_count": int(
                diagnostics.get("semantic_cash_flow_starting_profit_row_rejected_count") or 0
            ),
            "semantic_cash_flow_component_row_rejected_count": int(
                diagnostics.get("semantic_cash_flow_component_row_rejected_count") or 0
            ),
            "bad_aggregate_precision_row_count": int(diagnostics.get("bad_aggregate_precision_row_count") or 0),
            "component_row_mapped_to_aggregate_rejected_count": int(
                diagnostics.get("component_row_mapped_to_aggregate_rejected_count") or 0
            ),
            "primary_statement_table_row_parser_attempted": _as_bool(diagnostics.get("primary_statement_table_row_parser_attempted")),
            "primary_statement_table_row_parser_success": _as_bool(diagnostics.get("primary_statement_table_row_parser_success")),
            "primary_statement_table_row_parser_value_count": int(diagnostics.get("primary_statement_table_row_parser_value_count") or 0),
            "primary_statement_table_row_parser_failure_reason_codes": list(
                diagnostics.get("primary_statement_table_row_parser_failure_reason_codes") or []
            ),
            "toc_primary_page_candidate": _as_bool(page_meta.get("toc_primary_page_candidate")),
            "toc_primary_page_target_type": str(page_meta.get("toc_primary_page_target_type") or ""),
            "toc_primary_page_anchor_used": _as_bool(page_meta.get("toc_primary_page_anchor_used")),
            "toc_primary_page_continuation_used": _as_bool(page_meta.get("toc_primary_page_continuation_used")),
            "toc_primary_page_enforced_extraction": _as_bool(page_meta.get("toc_primary_page_enforced_extraction")),
            "toc_primary_page_enforced_extraction_reason_codes": list(
                page_meta.get("toc_primary_page_enforced_extraction_reason_codes") or []
            ),
            "toc_notes_range_rejected": _as_bool(page_meta.get("toc_notes_range_rejected")),
            "toc_notes_range_value_rejected_count": len(_rzd_controlled_value_extraction_numeric_groups(text))
            if _as_bool(page_meta.get("toc_notes_range_rejected"))
            else 0,
            "page_map_false_statement_flag_rejected": _as_bool(page_meta.get("page_map_false_statement_flag_rejected")),
            "contents_page_rejected_as_primary": _as_bool(page_meta.get("contents_page_rejected_as_primary")),
        }
    return {
        "target_type": target_type,
        "scanned_page_count": len(bounded_pages),
        "candidate_row_count": sum(len(rows) for rows in candidate_rows_by_page.values()),
        "candidate_rows_by_page": candidate_rows_by_page,
        "page_scores": page_scores,
        "page_reject_reason_codes": page_reject_reason_codes,
        "title_matches_by_page": title_matches_by_page,
        "diagnostics": {
            "candidate_discovery_rejected_page_count": rejected_page_count,
            "candidate_discovery_rejected_line_count": rejected_line_count,
            "candidate_discovery_pages_truncated": len(unique_pages) > len(bounded_pages),
            "title_anchor_page_count": title_anchor_page_count,
            "cross_target_page_rejected_count": cross_target_page_rejected_count,
            "cross_target_value_rejected_count": cross_target_value_rejected_count,
            "wide_equity_movement_line_rejected_count": wide_equity_movement_line_rejected_count,
            "wide_equity_movement_value_rejected_count": wide_equity_movement_value_rejected_count,
            "tax_note_page_rejected_count": tax_note_page_rejected_count,
            "false_generic_statement_row_rejected_count": false_generic_statement_row_rejected_count,
            "generic_row_fx_rate_rejected_count": generic_row_fx_rate_rejected_count,
            "generic_row_percent_or_discount_rejected_count": generic_row_percent_or_discount_rejected_count,
            "generic_row_statement_reference_rejected_count": generic_row_statement_reference_rejected_count,
            "generic_row_date_or_period_rejected_count": generic_row_date_or_period_rejected_count,
            "body_reference_title_rejected_count": body_reference_title_rejected_count,
            "body_reference_title_value_rejected_count": body_reference_title_value_rejected_count,
            "semantic_component_oci_row_rejected_count": semantic_component_oci_row_rejected_count,
            "semantic_wrong_aggregate_row_rejected_count": semantic_wrong_aggregate_row_rejected_count,
            "semantic_cash_flow_starting_profit_row_rejected_count": semantic_cash_flow_starting_profit_row_rejected_count,
            "semantic_cash_flow_component_row_rejected_count": semantic_cash_flow_component_row_rejected_count,
            "bad_aggregate_precision_row_count": bad_aggregate_precision_row_count,
            "component_row_mapped_to_aggregate_rejected_count": component_row_mapped_to_aggregate_rejected_count,
            "primary_statement_table_row_parser_attempt_count": primary_statement_table_row_parser_attempt_count,
            "primary_statement_table_row_parser_success_count": primary_statement_table_row_parser_success_count,
            "primary_statement_table_row_parser_failed_count": primary_statement_table_row_parser_failed_count,
            "primary_statement_table_row_value_count": primary_statement_table_row_value_count,
            "primary_statement_table_row_parser_zero_value_page_count": primary_statement_table_row_parser_zero_value_page_count,
            "toc_notes_range_page_rejected_count": toc_notes_range_page_rejected_count,
            "toc_notes_range_value_rejected_count": toc_notes_range_value_rejected_count,
            "page_map_false_statement_flag_rejected_count": page_map_false_statement_flag_rejected_count,
            "contents_page_primary_rejected_count": contents_page_primary_rejected_count,
        },
    }


def _rzd_controlled_value_extraction_build_toc_enforced_plan(
    toc_info: dict[str, Any],
    *,
    target_types: Sequence[str],
    pdf_page_count: int,
) -> list[dict[str, Any]]:
    if not (_as_bool(toc_info.get("toc_primary_page_override_used")) and _as_bool(toc_info.get("toc_primary_page_order_valid"))):
        return []
    notes_start_page = int(toc_info.get("toc_notes_start_page") or 0)
    target_page_fields = {
        "statement_of_financial_position": "toc_statement_of_financial_position_page",
        "profit_or_loss": "toc_profit_or_loss_page",
        "other_comprehensive_income": "toc_other_comprehensive_income_page",
        "cash_flows": "toc_cash_flows_page",
    }
    rows: list[dict[str, Any]] = []
    for target_type in target_types:
        field = target_page_fields.get(str(target_type or ""))
        if not field:
            continue
        primary_page = int(toc_info.get(field) or 0)
        if primary_page <= 0:
            continue
        candidate_pages = [primary_page]
        if target_type == "statement_of_financial_position":
            continuation = primary_page + 1
            if (not notes_start_page or continuation < notes_start_page) and (not pdf_page_count or continuation <= pdf_page_count):
                candidate_pages.append(continuation)
        if target_type == "cash_flows":
            continuation = primary_page + 1
            if (not notes_start_page or continuation < notes_start_page) and (not pdf_page_count or continuation <= pdf_page_count):
                candidate_pages.append(continuation)
        for page_number in dict.fromkeys(candidate_pages):
            is_continuation = int(page_number) != primary_page
            rows.append(
                {
                    "target_type": str(target_type),
                    "page_number": int(page_number),
                    "from_toc": True,
                    "is_continuation": bool(is_continuation),
                    "effective_page_text_char_count": 0,
                    "effective_page_text_backend": "",
                    "effective_page_text_source": "",
                    "parser_attempted": False,
                    "parser_value_count": 0,
                    "accepted": False,
                    "reject_reason_codes": [],
                    "reason_codes": [
                        "valid_toc_primary_page_enforced_extraction_continuation"
                        if is_continuation
                        else "valid_toc_primary_page_enforced_extraction"
                    ],
                    "safe_hint": "TOC-enforced page inspection plan only. Task170 does not import values.",
                }
            )
    return rows


def _rzd_controlled_value_extraction_merge_toc_enforced_candidate_pages(
    candidate_pages: list[dict[str, Any]],
    toc_enforced_plan_rows: Sequence[dict[str, Any]],
    *,
    page_map_by_page: dict[int, dict[str, Any]],
    target_rows_by_type: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    if not toc_enforced_plan_rows:
        return candidate_pages
    merged = list(candidate_pages)
    by_key: dict[tuple[str, int], dict[str, Any]] = {
        (str(item.get("target_type") or ""), int(item.get("page_number") or 0)): item
        for item in merged
        if int(item.get("page_number") or 0) > 0
    }
    for plan_row in toc_enforced_plan_rows:
        target_type = str(plan_row.get("target_type") or "")
        page_number = int(plan_row.get("page_number") or 0)
        if not target_type or page_number <= 0:
            continue
        key = (target_type, page_number)
        is_continuation = _as_bool(plan_row.get("is_continuation"))
        item = by_key.get(key)
        if item is None:
            item = {
                "target_type": target_type,
                "page_number": page_number,
                "page_map_row": page_map_by_page.get(page_number, {"page_number": page_number}),
                "target_row": target_rows_by_type.get(target_type, {}),
                "selection_score": 0,
                "selection_source": "toc_primary_page_continuation" if is_continuation else "toc_primary_page",
                "selection_priority_rank": 1 if is_continuation else 0,
                "target_start_page_used": False,
                "target_candidate_page_used": False,
                "target_exact_page_flag_used": False,
                "fallback_page_used": False,
                "toc_info": {},
            }
            merged.append(item)
            by_key[key] = item
        item["toc_primary_page_candidate"] = True
        item["toc_primary_page_target_type"] = target_type
        item["toc_primary_page_enforced_extraction"] = True
        reason_codes = list(item.get("toc_primary_page_enforced_extraction_reason_codes") or [])
        reason_codes.append(
            "valid_toc_primary_page_enforced_extraction_continuation"
            if is_continuation
            else "valid_toc_primary_page_enforced_extraction"
        )
        item["toc_primary_page_enforced_extraction_reason_codes"] = list(dict.fromkeys(reason_codes))
        if is_continuation:
            item["toc_primary_page_continuation_used"] = True
            if int(item.get("selection_priority_rank") or 99) > 1:
                item["selection_priority_rank"] = 1
                item["selection_source"] = "toc_primary_page_continuation"
        else:
            item["toc_primary_page_anchor_used"] = True
            item["selection_priority_rank"] = 0
            item["selection_source"] = "toc_primary_page"
    return merged


def _rzd_controlled_value_extraction_finalize_toc_enforced_plan_rows(
    rows: Sequence[dict[str, Any]],
    *,
    text_by_page: dict[int, dict[str, Any]],
    discovery_by_target: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    finalized: list[dict[str, Any]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        target_type = str(row.get("target_type") or "")
        page_number = int(row.get("page_number") or 0)
        text_info = text_by_page.get(page_number) if page_number > 0 else {}
        page_scores = (discovery_by_target.get(target_type) or {}).get("page_scores")
        page_score = page_scores.get(page_number) if isinstance(page_scores, dict) else {}
        text = str((text_info or {}).get("text") or "")
        reject_reason_codes = list(row.get("reject_reason_codes") or [])
        parser_attempted = _as_bool((page_score or {}).get("primary_statement_table_row_parser_attempted"))
        parser_value_count = int((page_score or {}).get("primary_statement_table_row_parser_value_count") or 0)
        if not text.strip():
            reject_reason_codes.append("toc_primary_page_enforced_text_missing")
        elif parser_attempted and parser_value_count == 0:
            reject_reason_codes.append("primary_statement_table_parser_zero_value_rows")
        accepted = bool(parser_attempted and parser_value_count > 0 and not reject_reason_codes)
        finalized.append(
            {
                "target_type": target_type,
                "page_number": page_number,
                "from_toc": True,
                "is_continuation": _as_bool(row.get("is_continuation")),
                "effective_page_text_char_count": len(text),
                "effective_page_text_backend": str((text_info or {}).get("effective_page_text_backend") or (text_info or {}).get("backend") or ""),
                "effective_page_text_source": str((text_info or {}).get("effective_page_text_source") or ""),
                "parser_attempted": bool(parser_attempted),
                "parser_value_count": int(parser_value_count),
                "accepted": bool(accepted),
                "reject_reason_codes": list(dict.fromkeys(reject_reason_codes)),
                "reason_codes": list(row.get("reason_codes") or []),
                "safe_hint": str(row.get("safe_hint") or "TOC-enforced page inspection plan only. Task170 does not import values."),
            }
        )
    return finalized


def _rzd_controlled_value_extraction_post_ocr_toc_parser_pass(
    rows: Sequence[dict[str, Any]],
    *,
    text_by_page: dict[int, dict[str, Any]],
    discovery_by_target: dict[str, dict[str, Any]],
) -> dict[str, int]:
    stats = {
        "candidate_discovery_row_count": 0,
        "primary_statement_table_row_parser_attempt_count": 0,
        "primary_statement_table_row_parser_success_count": 0,
        "primary_statement_table_row_parser_failed_count": 0,
        "primary_statement_table_row_value_count": 0,
        "primary_statement_table_row_parser_zero_value_page_count": 0,
        "candidate_discovery_rejected_line_count": 0,
        "semantic_component_oci_row_rejected_count": 0,
        "semantic_wrong_aggregate_row_rejected_count": 0,
        "semantic_cash_flow_starting_profit_row_rejected_count": 0,
        "semantic_cash_flow_component_row_rejected_count": 0,
    }
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        target_type = str(row.get("target_type") or "")
        page_number = int(row.get("page_number") or 0)
        if not target_type or page_number <= 0:
            continue
        text_info = text_by_page.get(page_number) or {}
        text = str(text_info.get("text") or "")
        if not text.strip():
            continue
        discovery = discovery_by_target.setdefault(target_type, {"target_type": target_type})
        page_scores = discovery.setdefault("page_scores", {})
        page_score = page_scores.get(page_number) if isinstance(page_scores, dict) else {}
        if _as_bool((page_score or {}).get("primary_statement_table_row_parser_attempted")):
            continue
        parser_rows, diagnostics = _rzd_controlled_value_extraction_parse_primary_statement_table_rows(
            target_type=target_type,
            page_number=page_number,
            page_text=text,
            text_source=str(text_info.get("effective_page_text_source") or text_info.get("backend") or "toc_enforced_effective_page_text"),
            text_backend=str(text_info.get("effective_page_text_backend") or text_info.get("backend") or ""),
            is_contents_page=False,
        )
        candidate_rows_by_page = discovery.setdefault("candidate_rows_by_page", {})
        existing_rows = list(candidate_rows_by_page.get(page_number) or [])
        existing_hashes = {str(candidate.get("raw_line_sha256") or "") for candidate in existing_rows}
        merged_rows = [*existing_rows]
        for parser_row in parser_rows:
            line_hash = str(parser_row.get("raw_line_sha256") or "")
            if line_hash and line_hash in existing_hashes:
                continue
            merged_rows.append(parser_row)
            if line_hash:
                existing_hashes.add(line_hash)
        candidate_rows_by_page[page_number] = merged_rows
        metric_keys = {str(candidate.get("metric_key") or "") for candidate in merged_rows if candidate.get("metric_key")}
        broad_metric_keys = metric_keys & _rzd_controlled_value_extraction_profit_or_loss_broad_metric_keys()
        base_score = dict(page_score or {})
        base_score.update(
            {
                "page_value_row_count": len(merged_rows),
                "page_required_metric_hit_count": len(metric_keys),
                "page_broad_metric_hit_count": len(broad_metric_keys),
                "page_table_score": max(int(base_score.get("page_table_score") or 0), len(metric_keys) * 50 + len(merged_rows) * 10),
                "page_total_discovery_score": max(
                    int(base_score.get("page_total_discovery_score") or 0),
                    len(metric_keys) * 50 + len(merged_rows) * 10 + 100,
                ),
                "candidate_line_scanned_count": int(diagnostics.get("candidate_line_scanned_count") or 0),
                "candidate_line_matched_count": int(diagnostics.get("candidate_line_matched_count") or 0),
                "candidate_line_rejected_count": int(diagnostics.get("candidate_line_rejected_count") or 0),
                "contents_navigation_line_rejected_count": int(diagnostics.get("contents_navigation_line_rejected_count") or 0),
                "page_number_value_rejected_count": int(diagnostics.get("page_number_value_rejected_count") or 0),
                "date_period_line_rejected_count": int(diagnostics.get("date_period_line_rejected_count") or 0),
                "date_number_value_rejected_count": int(diagnostics.get("date_number_value_rejected_count") or 0),
                "small_page_or_note_number_value_rejected_count": int(diagnostics.get("small_page_or_note_number_value_rejected_count") or 0),
                "wide_equity_movement_line_rejected_count": int(diagnostics.get("wide_equity_movement_line_rejected_count") or 0),
                "wide_equity_movement_value_rejected_count": int(diagnostics.get("wide_equity_movement_value_rejected_count") or 0),
                "false_generic_statement_row_rejected_count": int(diagnostics.get("false_generic_statement_row_rejected_count") or 0),
                "generic_row_fx_rate_rejected_count": int(diagnostics.get("generic_row_fx_rate_rejected_count") or 0),
                "generic_row_percent_or_discount_rejected_count": int(diagnostics.get("generic_row_percent_or_discount_rejected_count") or 0),
                "generic_row_statement_reference_rejected_count": int(diagnostics.get("generic_row_statement_reference_rejected_count") or 0),
                "generic_row_date_or_period_rejected_count": int(diagnostics.get("generic_row_date_or_period_rejected_count") or 0),
                "body_reference_title_value_rejected_count": int(diagnostics.get("body_reference_title_value_rejected_count") or 0),
                "semantic_component_oci_row_rejected_count": int(diagnostics.get("semantic_component_oci_row_rejected_count") or 0),
                "semantic_wrong_aggregate_row_rejected_count": int(diagnostics.get("semantic_wrong_aggregate_row_rejected_count") or 0),
                "semantic_cash_flow_starting_profit_row_rejected_count": int(
                    diagnostics.get("semantic_cash_flow_starting_profit_row_rejected_count") or 0
                ),
                "semantic_cash_flow_component_row_rejected_count": int(diagnostics.get("semantic_cash_flow_component_row_rejected_count") or 0),
                "primary_statement_table_row_parser_attempted": _as_bool(diagnostics.get("primary_statement_table_row_parser_attempted")),
                "primary_statement_table_row_parser_success": _as_bool(diagnostics.get("primary_statement_table_row_parser_success")),
                "primary_statement_table_row_parser_value_count": int(diagnostics.get("primary_statement_table_row_parser_value_count") or 0),
                "primary_statement_table_row_parser_failure_reason_codes": list(
                    diagnostics.get("primary_statement_table_row_parser_failure_reason_codes") or []
                ),
                "toc_primary_page_enforced_extraction": True,
                "toc_primary_page_candidate": True,
            }
        )
        page_scores[page_number] = base_score
        discovery.setdefault("page_reject_reason_codes", {})[page_number] = []
        title_matches = discovery.setdefault("title_matches_by_page", {})
        title_matches.setdefault(
            page_number,
            {
                "target_title_matched": True,
                "matched_title": "toc_enforced_effective_page_text",
                "matched_title_line_number": 0,
                "cross_target_title_detected": False,
                "cross_target_title_type": "",
                "title_match_reason_codes": ["toc_primary_page_enforced_extraction"],
                "title_reject_reason_codes": [],
            },
        )
        stats["candidate_discovery_row_count"] += len(parser_rows)
        stats["primary_statement_table_row_parser_attempt_count"] += 1
        if _as_bool(diagnostics.get("primary_statement_table_row_parser_success")):
            stats["primary_statement_table_row_parser_success_count"] += 1
        else:
            stats["primary_statement_table_row_parser_failed_count"] += 1
        parser_value_count = int(diagnostics.get("primary_statement_table_row_parser_value_count") or 0)
        stats["primary_statement_table_row_value_count"] += parser_value_count
        if parser_value_count == 0:
            stats["primary_statement_table_row_parser_zero_value_page_count"] += 1
        stats["candidate_discovery_rejected_line_count"] += int(diagnostics.get("candidate_line_rejected_count") or 0)
        for key in (
            "semantic_component_oci_row_rejected_count",
            "semantic_wrong_aggregate_row_rejected_count",
            "semantic_cash_flow_starting_profit_row_rejected_count",
            "semantic_cash_flow_component_row_rejected_count",
        ):
            stats[key] += int(diagnostics.get(key) or 0)
    return stats


def _rzd_controlled_value_extraction_verify_table_bearing_primary_page(
    target_type: str,
    page_text: str,
    page_map_row: dict[str, Any],
    target_row: dict[str, Any] | None,
    *,
    selection_source: str = "",
    allow_notes: bool = False,
) -> dict[str, Any]:
    target_row = target_row if isinstance(target_row, dict) else {}
    prepared = _normalize_pdf_preview_text_for_signal_detection(
        " ".join([str(page_map_row.get("detected_section_title") or ""), str(page_text or "")])
    )
    normalized = prepared["normalized_text"]
    compact = prepared["compact_text"]
    reject_codes: list[str] = []
    accepted_reason_codes: list[str] = []
    if _as_bool(page_map_row.get("is_contents_page")):
        reject_codes.append("contents_page_not_primary_statement")
    if _as_bool(page_map_row.get("is_auditor_report_page")):
        reject_codes.append("auditor_report_page_not_primary_statement")
    if _as_bool(page_map_row.get("is_notes_page")) and not allow_notes:
        reject_codes.append("notes_page_not_primary_statement")

    high_confidence_start_page = (
        selection_source == "target_start_page"
        and str(target_row.get("confidence") or "").casefold() == "high"
        and bool(str(page_text or "").strip())
        and not reject_codes
    )
    target_exact_section = (
        page_map_row.get("detected_section_type") == target_type
        or _as_bool(page_map_row.get(f"is_{target_type}_page"))
    )
    title_match = _rzd_controlled_value_extraction_phrase_count(
        _rzd_controlled_value_extraction_statement_title_terms(target_type),
        normalized,
        compact,
    ) > 0
    if high_confidence_start_page or target_exact_section:
        title_match = True
    if high_confidence_start_page:
        accepted_reason_codes.append("accepted_from_task169_high_confidence_start_page")
    required_term_count = _rzd_controlled_value_extraction_phrase_count(
        _rzd_controlled_value_extraction_target_required_terms(target_type),
        normalized,
        compact,
    )
    scan = _rzd_controlled_value_extraction_scan_target_value_rows(
        target_type,
        page_text,
        page_number=int(page_map_row.get("page_number") or 0),
        is_contents_page=_as_bool(page_map_row.get("is_contents_page")),
    )
    value_row_count = int(scan.get("value_row_count") or 0)
    required_metric_count = _rzd_controlled_value_extraction_target_required_metric_count(target_type)
    if not title_match:
        reject_codes.append("primary_statement_title_missing")
    if required_term_count < 1 and value_row_count < required_metric_count:
        reject_codes.append("primary_statement_required_terms_missing")
    if value_row_count < required_metric_count:
        reject_codes.append("primary_statement_table_rows_missing")
    if target_type == "profit_or_loss":
        if _rzd_controlled_value_extraction_is_tax_note_context(page_text, page_map_row):
            reject_codes.append("primary_profit_or_loss_page_tax_note_only")
        elif int(scan.get("broad_profit_or_loss_value_row_count") or 0) < 1:
            reject_codes.append("primary_profit_or_loss_broad_statement_row_missing")
    accepted = not reject_codes
    if accepted:
        accepted_reason_codes.append("table_bearing_primary_page_verified")
    return {
        "accepted": bool(accepted),
        "table_bearing_primary_page": bool(accepted),
        "reject_reason_codes": list(dict.fromkeys(reject_codes)),
        "reason_codes": list(dict.fromkeys(accepted_reason_codes)),
        "accepted_reason_codes": list(dict.fromkeys(accepted_reason_codes)),
        "page_title_detected": _rzd_controlled_value_extraction_page_title(target_type, page_text, page_map_row),
        "table_row_candidate_count": value_row_count,
        "target_specific_value_row_count": value_row_count,
        "target_specific_required_metric_count": required_metric_count,
        "table_bearing_primary_page_score": value_row_count * 20 + (20 if title_match else 0) + (10 if target_exact_section else 0),
        "title_match": bool(title_match),
        "required_term_count": int(required_term_count),
        "metric_keys": scan.get("metric_keys") or [],
        "scan_diagnostics": scan,
    }


def _rzd_controlled_value_extraction_primary_statement_assessment(
    target_type: str,
    *,
    text: str,
    page_row: dict[str, Any],
    target_row: dict[str, Any] | None = None,
    selection_source: str = "",
    allow_notes: bool,
) -> dict[str, Any]:
    return _rzd_controlled_value_extraction_verify_table_bearing_primary_page(
        target_type,
        text,
        page_row,
        target_row,
        selection_source=selection_source,
        allow_notes=allow_notes,
    )
    target_row = target_row if isinstance(target_row, dict) else {}
    prepared = _normalize_pdf_preview_text_for_signal_detection(" ".join([str(page_row.get("detected_section_title") or ""), str(text or "")]))
    normalized = prepared["normalized_text"]
    compact = prepared["compact_text"]
    title = _rzd_controlled_value_extraction_page_title(target_type, text, page_row)
    table_rows = _rzd_controlled_value_extraction_table_row_candidate_count(text)
    reject_codes: list[str] = []
    if _as_bool(page_row.get("is_contents_page")):
        reject_codes.append("contents_page_not_primary_statement")
    if _as_bool(page_row.get("is_auditor_report_page")):
        reject_codes.append("auditor_report_page_not_primary_statement")
    if _as_bool(page_row.get("is_notes_page")) and not allow_notes:
        reject_codes.append("notes_page_not_primary_statement")
    high_confidence_start_page = (
        selection_source == "target_start_page"
        and str(target_row.get("confidence") or "").casefold() == "high"
        and bool(str(text or "").strip())
        and not reject_codes
    )
    title_terms = {
        "statement_of_financial_position": ("консолидированный отчет о финансовом положении", "отчет о финансовом положении", "statement of financial position", "financial position"),
        "profit_or_loss": ("консолидированный отчет о прибылях и убытках", "отчет о прибылях и убытках", "statement of profit or loss", "profit or loss"),
        "other_comprehensive_income": ("консолидированный отчет о прочем совокупном доходе", "прочий совокупный доход", "other comprehensive income"),
        "cash_flows": ("консолидированный отчет о движении денежных средств", "отчет о движении денежных средств", "statement of cash flows", "cash flows"),
    }.get(target_type, ())
    required_terms = {
        "statement_of_financial_position": ("активы", "обязательства", "капитал", "итого активы", "итого капитал и обязательства", "assets", "liabilities", "equity", "total assets", "total equity and liabilities"),
        "profit_or_loss": ("выручка", "операционная прибыль", "прибыль до налогообложения", "налог на прибыль", "чистая прибыль", "прибыль за год", "revenue", "operating profit", "profit before tax", "income tax", "net profit", "profit for the year"),
        "other_comprehensive_income": ("прибыль за год", "чистая прибыль за год", "прочий совокупный доход", "profit for the year", "other comprehensive income"),
        "cash_flows": ("операционная деятельность", "инвестиционная деятельность", "финансовая деятельность", "денежные средства на начало", "денежные средства на конец", "operating activities", "investing activities", "financing activities", "cash and cash equivalents"),
    }.get(target_type, ())
    title_match = _rzd_controlled_value_extraction_phrase_count(title_terms, normalized, compact) > 0
    required_count = _rzd_controlled_value_extraction_phrase_count(required_terms, normalized, compact)
    if high_confidence_start_page:
        title_match = True
        required_count = max(required_count, 2)
    if not title_match:
        reject_codes.append("primary_statement_title_missing")
    if target_type == "other_comprehensive_income":
        if required_count < 2:
            reject_codes.append("primary_statement_required_terms_missing")
    elif required_count < 2:
        reject_codes.append("primary_statement_required_terms_missing")
    descriptive_note_terms = (
        "в составе статьи",
        "за год, закончившийся 31 декабря",
        "консолидированного отчета о прибылях и убытках",
    )
    if target_type == "profit_or_loss" and _rzd_controlled_value_extraction_phrase_count(descriptive_note_terms, normalized, compact) and table_rows < 2:
        reject_codes.append("profit_or_loss_notes_description_without_table_rows")
    accepted = not reject_codes
    reason_codes = ["accepted_from_task169_high_confidence_start_page"] if accepted and high_confidence_start_page else []
    return {
        "accepted": bool(accepted),
        "reject_reason_codes": reject_codes,
        "reason_codes": reason_codes,
        "page_title_detected": title,
        "table_row_candidate_count": int(table_rows),
        "title_match": bool(title_match),
        "required_term_count": int(required_count),
    }


