def _rzd_controlled_value_extraction_toc_text_for_page(
    row: dict[str, Any],
    page_texts: dict[int, dict[str, Any]] | None,
) -> tuple[str, str]:
    page_number = int(row.get("page_number") or 0)
    extracted = (page_texts or {}).get(page_number) if page_number > 0 else None
    if isinstance(extracted, dict) and str(extracted.get("text") or "").strip():
        return str(extracted.get("text") or ""), "full_extracted_page_text"
    for key in ("page_text_sample", "selected_page_text_sample", "detected_section_title", "section_title"):
        value = str(row.get(key) or "")
        if value.strip():
            return value, key
    return "", ""


def _rzd_controlled_value_extraction_discover_toc_source_pages(
    page_map_rows: list[dict[str, Any]],
    page_texts: dict[int, dict[str, Any]] | None,
    *,
    max_early_pages: int = 7,
) -> list[dict[str, Any]]:
    page_texts = page_texts or {}
    max_early_pages = int(max_early_pages or 7)
    by_page = {int(row.get("page_number") or 0): row for row in page_map_rows if isinstance(row, dict) and int(row.get("page_number") or 0) > 0}
    early_pages = sorted(
        page
        for page in set(range(1, max_early_pages + 1)) | {int(page) for page in page_texts if 1 <= int(page) <= max_early_pages}
        if page > 0
    )
    phrases_by_role = _rzd_controlled_value_extraction_toc_title_phrases_by_role()
    primary_roles = (
        "statement_of_financial_position",
        "profit_or_loss",
        "other_comprehensive_income",
        "changes_in_equity",
        "cash_flows",
        "notes_start_page",
    )
    rows: list[dict[str, Any]] = []
    for page_number in early_pages:
        page_row = dict(by_page.get(page_number, {"page_number": page_number}))
        text, text_source = _rzd_controlled_value_extraction_toc_text_for_page(page_row, page_texts)
        prepared = _normalize_pdf_preview_text_for_signal_detection(text)
        normalized = prepared["normalized_text"]
        compact = prepared["compact_text"]
        flag_detected = bool(
            _as_bool(page_row.get("is_contents_page"))
            or str(page_row.get("detected_section_type") or "").casefold() in {"contents", "table_of_contents"}
        )
        contents_marker = _rzd_controlled_value_extraction_phrase_count(_rzd_controlled_value_extraction_toc_contents_terms(), normalized, compact) > 0
        page_marker = _rzd_controlled_value_extraction_phrase_count(_rzd_controlled_value_extraction_toc_page_terms(), normalized, compact) > 0
        title_hits = 0
        title_with_page_refs = 0
        for role in primary_roles:
            phrases = phrases_by_role.get(role, ())
            if _rzd_controlled_value_extraction_phrase_count(phrases, normalized, compact) > 0:
                title_hits += 1
            extraction = _rzd_controlled_value_extraction_extract_toc_page_ref(text, phrases, ())
            if int(extraction.get("parsed_page_ref") or 0) > 0:
                title_with_page_refs += 1
        fragment_hits = _rzd_controlled_value_extraction_phrase_count(
            _rzd_controlled_value_extraction_toc_source_fragment_terms(),
            normalized,
            compact,
        )
        condition_a = bool(contents_marker and page_marker and title_hits >= 3)
        condition_b = bool(title_with_page_refs >= 4)
        condition_c = bool(page_number <= max_early_pages and fragment_hits >= 4)
        text_detected = bool(condition_a or condition_b or condition_c)
        accepted_reason_codes: list[str] = []
        if text_detected:
            accepted_reason_codes.append("early_page_toc_text_detected")
        if flag_detected:
            accepted_reason_codes.append("toc_page_map_flag_detected")
        if contents_marker:
            accepted_reason_codes.append("contents_marker_detected")
        if page_marker:
            accepted_reason_codes.append("page_marker_detected")
        if title_hits >= 3:
            accepted_reason_codes.append("multiple_statement_titles_detected")
        if title_with_page_refs >= 4:
            accepted_reason_codes.append("multiple_statement_titles_with_page_refs_detected")
        if condition_c:
            accepted_reason_codes.append("rzd_toc_title_fragment_cluster_detected")
        reject_reason_codes: list[str] = []
        if not str(text or "").strip():
            reject_reason_codes.append("toc_source_text_missing")
        if not (text_detected or flag_detected):
            reject_reason_codes.append("toc_source_text_evidence_insufficient")
        score = (
            (25 if flag_detected else 0)
            + (30 if contents_marker and page_marker else 0)
            + title_hits * 10
            + title_with_page_refs * 15
            + fragment_hits * 5
        )
        accepted = bool((text_detected or flag_detected) and not reject_reason_codes)
        if not accepted and not reject_reason_codes:
            reject_reason_codes.append("toc_source_not_accepted")
        rows.append(
            {
                "row_type": "source_candidate",
                "toc_diagnostic_id": f"rzd_manual_official_pdf_controlled_value_toc_source:{page_number}",
                "page_number": page_number,
                "toc_source_page": page_number,
                "page_map_detected_section_type": str(page_row.get("detected_section_type") or ""),
                "is_contents_page_flag": _as_bool(page_row.get("is_contents_page")),
                "toc_source_text_detected": bool(text_detected),
                "toc_source_flag_detected": bool(flag_detected),
                "toc_source_score": int(score),
                "primary_title_phrase_hit_count": int(title_hits),
                "title_with_page_ref_count": int(title_with_page_refs),
                "accepted": bool(accepted),
                "accepted_reason_codes": accepted_reason_codes if accepted else [],
                "reject_reason_codes": [] if accepted else reject_reason_codes,
                "inferred": False,
                "inference_reason_codes": [],
                "sample_text": normalized[:1000],
                "text_source": text_source,
                "safe_hint": "TOC source candidate only. Task170 does not import values or mutate downstream systems.",
            }
        )
    return sorted(rows, key=lambda row: (not _as_bool(row.get("accepted")), -int(row.get("toc_source_score") or 0), int(row.get("page_number") or 0)))


def _rzd_controlled_value_extraction_find_toc_phrase(text: str, phrases: Sequence[str], *, start: int = 0) -> tuple[int, int, str]:
    matches: list[tuple[int, int, str]] = []
    for phrase in phrases:
        normalized_phrase = _rzd_controlled_value_extraction_toc_compact_text(str(phrase or ""))
        if not normalized_phrase:
            continue
        index = text.find(normalized_phrase, max(0, int(start)))
        if index >= 0:
            matches.append((index, index + len(normalized_phrase), normalized_phrase))
    if not matches:
        return -1, -1, ""
    return sorted(matches, key=lambda item: (item[0], -(item[1] - item[0])))[0]


def _rzd_controlled_value_extraction_extract_toc_page_ref(
    toc_text: str,
    title_phrases: Sequence[str],
    next_title_phrases: Sequence[str],
) -> dict[str, Any]:
    normalized = _rzd_controlled_value_extraction_toc_compact_text(toc_text)
    start, end, matched_phrase = _rzd_controlled_value_extraction_find_toc_phrase(normalized, title_phrases)
    if start < 0:
        return {
            "matched_phrase": "",
            "text_slice": "",
            "raw_page_ref": "",
            "parsed_page_ref": 0,
            "reject_reason_codes": ["toc_title_phrase_not_found"],
        }
    next_start = len(normalized)
    for phrase in next_title_phrases:
        phrase_start, _phrase_end, _phrase = _rzd_controlled_value_extraction_find_toc_phrase(normalized, [phrase], start=end)
        if phrase_start >= 0:
            next_start = min(next_start, phrase_start)
    text_slice = normalized[end:next_start].strip()
    matches = list(re.finditer(r"(?<!\d)(\d{1,4})(?!\d)", text_slice))
    if not matches:
        return {
            "matched_phrase": matched_phrase,
            "text_slice": text_slice[:500],
            "raw_page_ref": "",
            "parsed_page_ref": 0,
            "reject_reason_codes": ["toc_page_ref_missing"],
        }
    raw_page_ref = matches[-1].group(1)
    return {
        "matched_phrase": matched_phrase,
        "text_slice": text_slice[:500],
        "raw_page_ref": raw_page_ref,
        "parsed_page_ref": int(raw_page_ref),
        "reject_reason_codes": [],
    }


def _rzd_controlled_value_extraction_notes_start_phrases() -> tuple[str, ...]:
    phrases = list(_rzd_controlled_value_extraction_toc_title_phrases_by_role().get("notes_start_page", ()))
    phrases.extend(
        [
            "РїСЂРёРјРµС‡Р°РЅРёСЏ Рє С„РёРЅР°РЅСЃРѕРІРѕР№ РѕС‚С‡РµС‚РЅРѕСЃС‚Рё",
            "РїСЂРёРјРµС‡Р°РЅРёСЏ Рє РєРѕРЅСЃРѕР»РёРґРёСЂРѕРІР°РЅРЅРѕР№ РѕС‚С‡РµС‚РЅРѕСЃС‚Рё",
            "notes to financial statements",
            "notes",
        ]
    )
    return tuple(dict.fromkeys(str(phrase) for phrase in phrases if str(phrase or "").strip()))


def _rzd_controlled_value_extraction_validate_toc_page_ref(
    *,
    target_type: str,
    parsed_page_ref: int,
    toc_source_page: int,
    pdf_page_count: int,
) -> list[str]:
    codes: list[str] = []
    if parsed_page_ref <= 0:
        codes.append("toc_page_ref_missing")
        return codes
    if parsed_page_ref == toc_source_page:
        codes.append("toc_source_page_number_rejected")
    if parsed_page_ref in {2024, 2025, 2026}:
        codes.append("toc_year_number_rejected")
    if parsed_page_ref > 200:
        codes.append("toc_large_number_rejected")
    if pdf_page_count > 0 and parsed_page_ref > pdf_page_count:
        codes.append("toc_candidate_page_ref_rejected")
    if target_type != "notes_start_page" and parsed_page_ref < 3:
        codes.append("toc_candidate_page_ref_rejected")
    return list(dict.fromkeys(codes))


def _rzd_controlled_value_extraction_extract_notes_start_page_ref(
    toc_text: str,
    title_phrases: Sequence[str],
    next_title_phrases: Sequence[str],
    *,
    toc_source_page: int,
    pdf_page_count: int,
) -> dict[str, Any]:
    normalized = _rzd_controlled_value_extraction_toc_compact_text(toc_text)
    phrases = tuple(dict.fromkeys([*title_phrases, *_rzd_controlled_value_extraction_notes_start_phrases()]))
    start, end, matched_phrase = _rzd_controlled_value_extraction_find_toc_phrase(normalized, phrases)
    if start < 0:
        return {
            "matched_phrase": "",
            "text_slice": "",
            "raw_page_ref": "",
            "parsed_page_ref": 0,
            "reject_reason_codes": ["toc_title_phrase_not_found"],
        }
    next_start = len(normalized)
    for phrase in next_title_phrases:
        phrase_start, _phrase_end, _phrase = _rzd_controlled_value_extraction_find_toc_phrase(normalized, [phrase], start=end)
        if phrase_start >= 0:
            next_start = min(next_start, phrase_start)
    text_slice = normalized[end:next_start].strip()
    matches = list(re.finditer(r"(?<!\d)(\d{1,4})(?!\d)", text_slice))
    if not matches:
        return {
            "matched_phrase": matched_phrase,
            "text_slice": text_slice[:500],
            "raw_page_ref": "",
            "parsed_page_ref": 0,
            "reject_reason_codes": ["toc_page_ref_missing"],
        }
    first_invalid: dict[str, Any] | None = None
    for match in matches:
        parsed_page_ref = int(match.group(1))
        reject_codes = _rzd_controlled_value_extraction_validate_toc_page_ref(
            target_type="notes_start_page",
            parsed_page_ref=parsed_page_ref,
            toc_source_page=toc_source_page,
            pdf_page_count=pdf_page_count,
        )
        candidate = {
            "matched_phrase": matched_phrase,
            "text_slice": text_slice[:500],
            "raw_page_ref": match.group(1),
            "parsed_page_ref": parsed_page_ref,
            "reject_reason_codes": reject_codes,
        }
        if not reject_codes:
            return candidate
        if first_invalid is None:
            first_invalid = candidate
    return first_invalid or {
        "matched_phrase": matched_phrase,
        "text_slice": text_slice[:500],
        "raw_page_ref": "",
        "parsed_page_ref": 0,
        "reject_reason_codes": ["toc_page_ref_missing"],
    }


def _rzd_controlled_value_extraction_validate_toc_page_order(values: dict[str, int]) -> tuple[bool, list[str]]:
    reason_codes: list[str] = []
    required = (
        "statement_of_financial_position",
        "profit_or_loss",
        "other_comprehensive_income",
        "cash_flows",
        "notes_start_page",
    )
    for role in required:
        if int(values.get(role) or 0) <= 0:
            reason_codes.append(f"toc_{role}_missing")
    source = int(values.get("toc_source_page") or 0)
    sofp = int(values.get("statement_of_financial_position") or 0)
    pl = int(values.get("profit_or_loss") or 0)
    oci = int(values.get("other_comprehensive_income") or 0)
    changes = int(values.get("changes_in_equity") or 0)
    cash = int(values.get("cash_flows") or 0)
    notes = int(values.get("notes_start_page") or 0)
    if not reason_codes:
        if changes > 0:
            ordered = source < sofp < pl < oci < changes < cash < notes
        else:
            ordered = source < sofp < pl < oci < cash < notes
        if not ordered:
            reason_codes.append("controlled_value_extraction_toc_page_order_invalid")
    elif "controlled_value_extraction_toc_page_order_invalid" not in reason_codes:
        reason_codes.append("controlled_value_extraction_toc_page_order_invalid")
    return not reason_codes, reason_codes


def _rzd_controlled_value_extraction_pdf_page_count_from_context(
    page_map_rows: Sequence[dict[str, Any]],
    *reports: dict[str, Any],
) -> int:
    candidates: list[int] = []
    for report in reports:
        if not isinstance(report, dict):
            continue
        for key in ("pdf_page_count", "page_count", "pdf_extracted_page_count", "extracted_page_count"):
            value = _as_int(report.get(key)) or 0
            if value > 0:
                candidates.append(value)
    for row in page_map_rows or []:
        if not isinstance(row, dict):
            continue
        for key in ("pdf_page_count", "page_count"):
            value = _as_int(row.get(key)) or 0
            if value > 0:
                candidates.append(value)
        page_number = _as_int(row.get("page_number")) or 0
        if page_number > 0:
            candidates.append(page_number)
    return max(candidates) if candidates else 0


def _rzd_controlled_value_extraction_notes_inference_invalid_codes(
    *,
    page_ref: int,
    toc_source_page: int,
    cash_flows_page: int,
    pdf_page_count: int,
    accepted_values: dict[str, int],
) -> list[str]:
    reject_codes = _rzd_controlled_value_extraction_validate_toc_page_ref(
        target_type="notes_start_page",
        parsed_page_ref=page_ref,
        toc_source_page=toc_source_page,
        pdf_page_count=pdf_page_count,
    )
    if page_ref <= cash_flows_page:
        reject_codes.append("toc_notes_start_page_not_after_cash_flows")
    order_valid, order_reject_codes = _rzd_controlled_value_extraction_validate_toc_page_order(
        {**accepted_values, "notes_start_page": page_ref}
    )
    if not order_valid:
        reject_codes.extend(order_reject_codes)
    return list(dict.fromkeys(reject_codes))


def _rzd_controlled_value_extraction_infer_notes_start_page(
    *,
    toc_text: str,
    toc_source_page: int,
    accepted_values: dict[str, int],
    page_map_rows: Sequence[dict[str, Any]],
    page_texts: dict[int, dict[str, Any]],
    target_rows: Sequence[dict[str, Any]],
    pdf_page_count: int,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "page_ref": 0,
        "matched_phrase": "",
        "text_slice": "",
        "raw_page_ref": "",
        "reason_codes": [],
        "attempt_count": 0,
        "success_count": 0,
        "rejected_count": 0,
        "reject_reason_codes": [],
    }
    cash_flows_page = int(accepted_values.get("cash_flows") or 0)
    required_before_notes = (
        "toc_source_page",
        "statement_of_financial_position",
        "profit_or_loss",
        "other_comprehensive_income",
        "cash_flows",
    )
    if any(int(accepted_values.get(role) or 0) <= 0 for role in required_before_notes):
        result["reject_reason_codes"] = ["toc_notes_start_page_primary_pages_incomplete"]
        return result

    def _try_candidate(
        page_ref: int,
        reason_code: str,
        *,
        matched_phrase: str = "",
        text_slice: str = "",
        raw_page_ref: str = "",
    ) -> bool:
        page_ref = int(page_ref or 0)
        if page_ref <= 0:
            return False
        result["attempt_count"] = int(result["attempt_count"] or 0) + 1
        reject_codes = _rzd_controlled_value_extraction_notes_inference_invalid_codes(
            page_ref=page_ref,
            toc_source_page=toc_source_page,
            cash_flows_page=cash_flows_page,
            pdf_page_count=pdf_page_count,
            accepted_values=accepted_values,
        )
        if reject_codes:
            result["rejected_count"] = int(result["rejected_count"] or 0) + 1
            result["reject_reason_codes"] = list(dict.fromkeys([*result.get("reject_reason_codes", []), *reject_codes]))
            return False
        result.update(
            {
                "page_ref": page_ref,
                "matched_phrase": matched_phrase,
                "text_slice": text_slice,
                "raw_page_ref": raw_page_ref or str(page_ref),
                "reason_codes": [reason_code],
                "success_count": 1,
            }
        )
        return True

    broad_extraction = _rzd_controlled_value_extraction_extract_notes_start_page_ref(
        toc_text,
        _rzd_controlled_value_extraction_notes_start_phrases(),
        (),
        toc_source_page=toc_source_page,
        pdf_page_count=pdf_page_count,
    )
    broad_ref = int(broad_extraction.get("parsed_page_ref") or 0)
    if broad_ref > 0 and _try_candidate(
        broad_ref,
        "toc_notes_start_page_inferred_from_toc_broad_phrase",
        matched_phrase=str(broad_extraction.get("matched_phrase") or ""),
        text_slice=str(broad_extraction.get("text_slice") or ""),
        raw_page_ref=str(broad_extraction.get("raw_page_ref") or ""),
    ):
        return result
    if broad_ref > 0 and broad_extraction.get("reject_reason_codes"):
        result["reject_reason_codes"] = list(
            dict.fromkeys([*result.get("reject_reason_codes", []), *list(broad_extraction.get("reject_reason_codes") or [])])
        )

    page_map_list = [row for row in page_map_rows or [] if isinstance(row, dict)]
    for row in sorted(page_map_list, key=lambda item: int(item.get("page_number") or 0)):
        page_ref = int(row.get("page_number") or 0)
        if page_ref <= 0:
            continue
        if _as_bool(row.get("is_notes_page")) and _try_candidate(page_ref, "toc_notes_start_page_inferred_from_first_notes_page"):
            return result
    for row in sorted(page_map_list, key=lambda item: int(item.get("page_number") or 0)):
        page_ref = int(row.get("page_number") or 0)
        detected_type = str(row.get("detected_section_type") or "").casefold()
        if page_ref > 0 and detected_type.startswith("notes") and _try_candidate(page_ref, "toc_notes_start_page_inferred_from_page_map"):
            return result
    for row in sorted(page_map_list, key=lambda item: int(item.get("page_number") or 0)):
        page_ref = int(row.get("page_number") or 0)
        if page_ref <= cash_flows_page:
            continue
        text, _source = _rzd_controlled_value_extraction_toc_text_for_page(row, page_texts)
        prepared = _normalize_pdf_preview_text_for_signal_detection(text)
        if _rzd_controlled_value_extraction_phrase_count(
            _rzd_controlled_value_extraction_notes_start_phrases(),
            prepared["normalized_text"],
            prepared["compact_text"],
        ) > 0 and _try_candidate(page_ref, "toc_notes_start_page_inferred_from_page_map"):
            return result
    for row in sorted((row for row in target_rows or [] if isinstance(row, dict)), key=lambda item: int(item.get("start_page") or 0)):
        target_type = str(row.get("target_type") or row.get("detected_section_type") or "").casefold()
        if "notes" not in target_type:
            continue
        for key in ("start_page", "page_number"):
            page_ref = int(row.get(key) or 0)
            if page_ref > 0 and _try_candidate(page_ref, "toc_notes_start_page_inferred_from_page_map"):
                return result
        for page_ref in _rzd_manual_official_pdf_controlled_value_extraction_page_numbers(row.get("candidate_pages")):
            if _try_candidate(int(page_ref), "toc_notes_start_page_inferred_from_page_map"):
                return result
    return result


def _rzd_controlled_value_extraction_parse_toc_primary_pages(
    page_map_rows: Sequence[dict[str, Any]],
    page_texts: dict[int, dict[str, Any]] | None = None,
    target_rows: Sequence[dict[str, Any]] | None = None,
    *,
    pdf_page_count: int = 0,
) -> dict[str, Any]:
    page_texts = page_texts or {}
    pdf_page_count = int(pdf_page_count or _rzd_controlled_value_extraction_pdf_page_count_from_context(page_map_rows))
    result: dict[str, Any] = {
        "toc_primary_pages_detected": False,
        "toc_primary_page_override_used": False,
        "toc_primary_page_order_valid": False,
        "toc_primary_page_order_reject_reason_codes": [],
        "toc_source_candidate_page_count": 0,
        "toc_source_text_detected_count": 0,
        "toc_source_flag_detected_count": 0,
        "toc_source_candidate_rejected_count": 0,
        "toc_source_detection_failed_reason_codes": [],
        "toc_source_candidate_rows": [],
        "toc_source_page": 0,
        "toc_statement_of_financial_position_page": 0,
        "toc_profit_or_loss_page": 0,
        "toc_other_comprehensive_income_page": 0,
        "toc_changes_in_equity_page": 0,
        "toc_cash_flows_page": 0,
        "toc_notes_start_page": 0,
        "toc_notes_start_page_inferred": False,
        "toc_notes_start_page_inference_reason_codes": [],
        "toc_notes_start_page_inference_attempt_count": 0,
        "toc_notes_start_page_inference_success_count": 0,
        "toc_notes_start_page_inference_rejected_count": 0,
        "toc_role_pages": {},
        "toc_diagnostic_rows": [],
        "toc_candidate_page_ref_rejected_count": 0,
        "toc_year_number_rejected_count": 0,
        "toc_out_of_order_page_ref_rejected_count": 0,
        "toc_source_page_number_rejected_count": 0,
        "toc_large_number_rejected_count": 0,
    }
    roles = (
        "statement_of_financial_position",
        "profit_or_loss",
        "other_comprehensive_income",
        "changes_in_equity",
        "cash_flows",
        "notes_start_page",
    )
    role_to_field = {
        "statement_of_financial_position": "toc_statement_of_financial_position_page",
        "profit_or_loss": "toc_profit_or_loss_page",
        "other_comprehensive_income": "toc_other_comprehensive_income_page",
        "changes_in_equity": "toc_changes_in_equity_page",
        "cash_flows": "toc_cash_flows_page",
        "notes_start_page": "toc_notes_start_page",
    }
    phrases_by_role = _rzd_controlled_value_extraction_toc_title_phrases_by_role()
    page_map_list = [row for row in page_map_rows or [] if isinstance(row, dict)]
    by_page = {int(row.get("page_number") or 0): row for row in page_map_list if int(row.get("page_number") or 0) > 0}
    source_candidates = _rzd_controlled_value_extraction_discover_toc_source_pages(page_map_list, page_texts)
    result["toc_source_candidate_rows"] = source_candidates
    result["toc_source_candidate_page_count"] = len(source_candidates)
    result["toc_source_text_detected_count"] = sum(1 for row in source_candidates if _as_bool(row.get("toc_source_text_detected")))
    result["toc_source_flag_detected_count"] = sum(1 for row in source_candidates if _as_bool(row.get("toc_source_flag_detected")))
    result["toc_source_candidate_rejected_count"] = sum(1 for row in source_candidates if not _as_bool(row.get("accepted")))
    accepted_sources = [row for row in source_candidates if _as_bool(row.get("accepted"))]
    if not accepted_sources:
        failed_codes = sorted(
            {
                str(code)
                for row in source_candidates
                for code in (row.get("reject_reason_codes") or [])
                if str(code)
            }
        )
        result["toc_source_detection_failed_reason_codes"] = failed_codes or ["toc_source_candidates_not_found"]
        return result

    best_invalid: dict[str, Any] | None = None
    for source_candidate in accepted_sources:
        page_number = int(source_candidate.get("page_number") or source_candidate.get("toc_source_page") or 0)
        if page_number <= 0:
            continue
        page_row = by_page.get(page_number, {"page_number": page_number})
        text, _text_source = _rzd_controlled_value_extraction_toc_text_for_page(page_row, page_texts)
        if not text.strip():
            continue
        trial = dict(result)
        trial.update(
            {
                "toc_primary_pages_detected": False,
                "toc_primary_page_override_used": False,
                "toc_primary_page_order_valid": False,
                "toc_primary_page_order_reject_reason_codes": [],
                "toc_source_detection_failed_reason_codes": [],
                "toc_source_page": page_number,
                "toc_statement_of_financial_position_page": 0,
                "toc_profit_or_loss_page": 0,
                "toc_other_comprehensive_income_page": 0,
                "toc_changes_in_equity_page": 0,
                "toc_cash_flows_page": 0,
                "toc_notes_start_page": 0,
                "toc_notes_start_page_inferred": False,
                "toc_notes_start_page_inference_reason_codes": [],
                "toc_notes_start_page_inference_attempt_count": 0,
                "toc_notes_start_page_inference_success_count": 0,
                "toc_notes_start_page_inference_rejected_count": 0,
                "toc_role_pages": {},
                "toc_diagnostic_rows": [],
                "toc_candidate_page_ref_rejected_count": 0,
                "toc_year_number_rejected_count": 0,
                "toc_out_of_order_page_ref_rejected_count": 0,
                "toc_source_page_number_rejected_count": 0,
                "toc_large_number_rejected_count": 0,
            }
        )
        result["toc_source_page"] = page_number
        accepted_values: dict[str, int] = {"toc_source_page": page_number}
        for index, role in enumerate(roles):
            next_roles = roles[index + 1 :]
            if role == "notes_start_page":
                extraction = _rzd_controlled_value_extraction_extract_notes_start_page_ref(
                    text,
                    phrases_by_role.get(role, ()),
                    tuple(phrase for next_role in next_roles for phrase in phrases_by_role.get(next_role, ())),
                    toc_source_page=page_number,
                    pdf_page_count=pdf_page_count,
                )
            else:
                extraction = _rzd_controlled_value_extraction_extract_toc_page_ref(
                    text,
                    phrases_by_role.get(role, ()),
                    tuple(phrase for next_role in next_roles for phrase in phrases_by_role.get(next_role, ())),
                )
            parsed_page_ref = int(extraction.get("parsed_page_ref") or 0)
            reject_codes = list(extraction.get("reject_reason_codes") or [])
            reject_codes.extend(
                _rzd_controlled_value_extraction_validate_toc_page_ref(
                    target_type=role,
                    parsed_page_ref=parsed_page_ref,
                    toc_source_page=page_number,
                    pdf_page_count=pdf_page_count,
                )
            )
            reject_codes = list(dict.fromkeys(reject_codes))
            accepted = parsed_page_ref > 0 and not reject_codes
            field = role_to_field[role]
            if accepted:
                trial[field] = parsed_page_ref
                trial["toc_role_pages"][role] = parsed_page_ref
                accepted_values[role] = parsed_page_ref
            else:
                trial[field] = 0
                if any(code == "toc_year_number_rejected" for code in reject_codes):
                    trial["toc_year_number_rejected_count"] += 1
                if any(code == "toc_source_page_number_rejected" for code in reject_codes):
                    trial["toc_source_page_number_rejected_count"] += 1
                if any(code == "toc_large_number_rejected" for code in reject_codes):
                    trial["toc_large_number_rejected_count"] += 1
                if any(code in {"toc_candidate_page_ref_rejected", "toc_page_ref_missing", "toc_title_phrase_not_found"} for code in reject_codes):
                    trial["toc_candidate_page_ref_rejected_count"] += 1
            trial["toc_diagnostic_rows"].append(
                {
                    "row_type": "page_ref",
                    "toc_diagnostic_id": f"rzd_manual_official_pdf_controlled_value_toc:{page_number}:{role}",
                    "toc_source_page": page_number,
                    "target_type": role,
                    "matched_phrase": str(extraction.get("matched_phrase") or ""),
                    "text_slice": str(extraction.get("text_slice") or ""),
                    "raw_page_ref": str(extraction.get("raw_page_ref") or ""),
                    "parsed_page_ref": parsed_page_ref,
                    "accepted": bool(accepted),
                    "accepted_reason_codes": ["toc_page_ref_accepted"] if accepted else [],
                    "reject_reason_codes": reject_codes,
                    "inferred": False,
                    "inference_reason_codes": [],
                    "safe_hint": "TOC diagnostic only. Task170 does not import values or mutate downstream systems.",
                    "page_number": 0,
                    "page_map_detected_section_type": "",
                    "is_contents_page_flag": False,
                    "toc_source_text_detected": False,
                    "toc_source_flag_detected": False,
                    "toc_source_score": 0,
                    "primary_title_phrase_hit_count": 0,
                    "title_with_page_ref_count": 0,
                    "sample_text": "",
                }
            )
        if int(accepted_values.get("notes_start_page") or 0) <= 0:
            inference = _rzd_controlled_value_extraction_infer_notes_start_page(
                toc_text=text,
                toc_source_page=page_number,
                accepted_values=accepted_values,
                page_map_rows=page_map_list,
                page_texts=page_texts,
                target_rows=target_rows or (),
                pdf_page_count=pdf_page_count,
            )
            trial["toc_notes_start_page_inference_attempt_count"] = int(inference.get("attempt_count") or 0)
            trial["toc_notes_start_page_inference_success_count"] = int(inference.get("success_count") or 0)
            trial["toc_notes_start_page_inference_rejected_count"] = int(inference.get("rejected_count") or 0)
            if int(inference.get("page_ref") or 0) > 0:
                inferred_page = int(inference.get("page_ref") or 0)
                trial["toc_notes_start_page"] = inferred_page
                trial["toc_role_pages"]["notes_start_page"] = inferred_page
                trial["toc_notes_start_page_inferred"] = True
                trial["toc_notes_start_page_inference_reason_codes"] = list(inference.get("reason_codes") or [])
                accepted_values["notes_start_page"] = inferred_page
                for diagnostic in trial["toc_diagnostic_rows"]:
                    if diagnostic.get("target_type") == "notes_start_page":
                        diagnostic.update(
                            {
                                "matched_phrase": str(inference.get("matched_phrase") or diagnostic.get("matched_phrase") or ""),
                                "text_slice": str(inference.get("text_slice") or diagnostic.get("text_slice") or ""),
                                "raw_page_ref": str(inference.get("raw_page_ref") or inferred_page),
                                "parsed_page_ref": inferred_page,
                                "accepted": True,
                                "accepted_reason_codes": ["toc_page_ref_accepted", *list(inference.get("reason_codes") or [])],
                                "reject_reason_codes": [],
                                "inferred": True,
                                "inference_reason_codes": list(inference.get("reason_codes") or []),
                            }
                        )
                        break
            elif inference.get("reject_reason_codes"):
                trial["toc_source_detection_failed_reason_codes"] = list(
                    dict.fromkeys([*trial.get("toc_source_detection_failed_reason_codes", []), *list(inference.get("reject_reason_codes") or [])])
                )
        order_valid, order_reject_codes = _rzd_controlled_value_extraction_validate_toc_page_order(accepted_values)
        if not order_valid:
            trial["toc_out_of_order_page_ref_rejected_count"] += 1
        trial["toc_primary_page_order_valid"] = bool(order_valid)
        trial["toc_primary_page_order_reject_reason_codes"] = order_reject_codes
        trial["toc_primary_pages_detected"] = bool(order_valid)
        trial["toc_primary_page_override_used"] = bool(order_valid)
        if not order_valid and order_reject_codes:
            trial["toc_source_detection_failed_reason_codes"] = order_reject_codes
            for diagnostic in trial["toc_diagnostic_rows"]:
                if diagnostic.get("accepted"):
                    diagnostic["reject_reason_codes"] = list(
                        dict.fromkeys([*(diagnostic.get("reject_reason_codes") or []), *order_reject_codes])
                    )
                    diagnostic["accepted"] = False
        if order_valid:
            return trial
        if best_invalid is None:
            best_invalid = trial
    if best_invalid is not None:
        return best_invalid
    result["toc_source_detection_failed_reason_codes"] = ["toc_source_text_unavailable_for_accepted_candidate"]
    return result


def _rzd_controlled_value_extraction_page_is_in_toc_notes_range(
    page_number: int,
    toc_info: dict[str, Any],
    allow_notes_pages: bool,
) -> bool:
    if allow_notes_pages:
        return False
    notes_start = int(toc_info.get("toc_notes_start_page") or 0)
    return bool(notes_start > 0 and int(page_number or 0) >= notes_start)


def _rzd_manual_official_pdf_controlled_value_extraction_page_candidates(
    args: argparse.Namespace,
    *,
    page_map_rows: list[dict[str, Any]],
    target_rows: list[dict[str, Any]],
    pdf_page_count: int = 0,
    page_texts: dict[int, dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    target_types = _rzd_manual_official_pdf_controlled_value_extraction_target_types(args)
    by_page = {int(row.get("page_number") or 0): row for row in page_map_rows if int(row.get("page_number") or 0) > 0}
    allow_notes = bool(args.rzd_manual_official_pdf_controlled_value_extraction_allow_notes_pages)
    toc_info = _rzd_controlled_value_extraction_parse_toc_primary_pages(
        page_map_rows,
        page_texts=page_texts,
        target_rows=target_rows,
        pdf_page_count=pdf_page_count,
    )
    candidates: list[dict[str, Any]] = []
    seen: set[tuple[str, int]] = set()

    def _add_candidate(
        *,
        target_type: str,
        target: dict[str, Any],
        page_number: int,
        source: str,
        rank: int,
        target_start_page_used: bool = False,
        target_candidate_page_used: bool = False,
        target_exact_page_flag_used: bool = False,
        fallback_page_used: bool = False,
        toc_primary_page_candidate: bool = False,
        toc_primary_page_target_type: str = "",
        toc_primary_page_anchor_used: bool = False,
        toc_primary_page_continuation_used: bool = False,
        toc_notes_range_rejected: bool = False,
        page_map_false_statement_flag_rejected: bool = False,
        contents_page_rejected_as_primary: bool = False,
    ) -> None:
        if page_number <= 0 or (target_type, page_number) in seen:
            return
        page_row = by_page.get(page_number, {})
        if not page_row:
            return
        page_context = " ".join([str(page_row.get("detected_section_title") or ""), str(page_row.get("page_text_sample") or "")])
        toc_source_page = int(toc_info.get("toc_source_page") or 0)
        inferred_contents_page = _as_bool(page_row.get("is_contents_page")) or (
            source != "toc_primary_page"
            and (page_number == toc_source_page or _rzd_controlled_value_extraction_is_toc_page_text(page_context))
        )
        in_notes_range = _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes)
        seen.add((target_type, page_number))
        candidates.append(
            {
                "target_type": target_type,
                "page_number": page_number,
                "page_map_row": page_row,
                "target_row": target,
                "selection_source": source,
                "selection_priority_rank": int(rank),
                "target_start_page_used": bool(target_start_page_used),
                "target_candidate_page_used": bool(target_candidate_page_used),
                "target_exact_page_flag_used": bool(target_exact_page_flag_used),
                "fallback_page_used": bool(fallback_page_used),
                "toc_info": dict(toc_info),
                "toc_primary_page_candidate": bool(toc_primary_page_candidate),
                "toc_primary_page_target_type": str(toc_primary_page_target_type or ""),
                "toc_primary_page_anchor_used": bool(toc_primary_page_anchor_used),
                "toc_primary_page_continuation_used": bool(toc_primary_page_continuation_used),
                "toc_notes_range_rejected": bool(toc_notes_range_rejected or in_notes_range),
                "page_map_false_statement_flag_rejected": bool(page_map_false_statement_flag_rejected),
                "contents_page_rejected_as_primary": bool(contents_page_rejected_as_primary or inferred_contents_page),
            }
        )

    for target_type in target_types:
        target = next((row for row in target_rows if row.get("target_type") == target_type), {})
        toc_detected = _as_bool(toc_info.get("toc_primary_pages_detected"))
        toc_field = f"toc_{target_type}_page"
        toc_page = int(toc_info.get(toc_field) or 0)
        notes_start = int(toc_info.get("toc_notes_start_page") or 0)
        if toc_page > 0:
            _add_candidate(
                target_type=target_type,
                target=target,
                page_number=toc_page,
                source="toc_primary_page",
                rank=1,
                toc_primary_page_candidate=True,
                toc_primary_page_target_type=target_type,
                toc_primary_page_anchor_used=True,
            )
            continuation_limit = 2 if target_type in {"statement_of_financial_position", "profit_or_loss", "other_comprehensive_income"} else 3
            for continuation_page in range(toc_page + 1, toc_page + continuation_limit + 1):
                if notes_start > 0 and continuation_page >= notes_start:
                    break
                _add_candidate(
                    target_type=target_type,
                    target=target,
                    page_number=continuation_page,
                    source="toc_primary_page_continuation",
                    rank=2,
                    target_candidate_page_used=True,
                    toc_primary_page_candidate=True,
                    toc_primary_page_target_type=target_type,
                    toc_primary_page_continuation_used=True,
                )
        start_page = _as_int(target.get("start_page"))
        if start_page and start_page > 0:
            _add_candidate(
                target_type=target_type,
                target=target,
                page_number=start_page,
                source="target_start_page",
                rank=3 if toc_detected else 1,
                target_start_page_used=True,
                toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(start_page, toc_info, allow_notes),
                page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(start_page, toc_info, allow_notes),
            )
            continuation_limit = 6 if target_type == "statement_of_financial_position" else 4 if target_type == "profit_or_loss" else 2
            for adjacent_page in (start_page - 1, *range(start_page + 1, start_page + continuation_limit + 1)):
                _add_candidate(
                    target_type=target_type,
                    target=target,
                    page_number=adjacent_page,
                    source="target_start_adjacent_page",
                    rank=5 if toc_detected else 4,
                    target_candidate_page_used=True,
                    toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(adjacent_page, toc_info, allow_notes),
                    page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(adjacent_page, toc_info, allow_notes),
                )
        exact_flag_pages = [
            int(row.get("page_number") or 0)
            for row in page_map_rows
            if int(row.get("page_number") or 0) > 0
            and _as_bool(row.get(f"is_{target_type}_page"))
        ]
        for page_number in exact_flag_pages:
            _add_candidate(
                target_type=target_type,
                target=target,
                page_number=page_number,
                source="target_exact_page_flag",
                rank=(4 if toc_detected else 2) if not _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes) else 80,
                target_exact_page_flag_used=True,
                toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
            )
        detected_section_pages = [
            int(row.get("page_number") or 0)
            for row in page_map_rows
            if int(row.get("page_number") or 0) > 0 and row.get("detected_section_type") == target_type
        ]
        for page_number in detected_section_pages:
            _add_candidate(
                target_type=target_type,
                target=target,
                page_number=page_number,
                source="target_detected_section_type",
                rank=(5 if toc_detected else 3) if not _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes) else 81,
                toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
            )
        target_candidate_pages = list(
            dict.fromkeys(
                [
                    *_rzd_manual_official_pdf_controlled_value_extraction_page_numbers(target.get("candidate_pages")),
                    *_rzd_controlled_value_extraction_target_range_pages(target),
                ]
            )
        )
        for page_number in target_candidate_pages:
            _add_candidate(
                target_type=target_type,
                target=target,
                page_number=page_number,
                source="target_candidate_page",
                rank=(6 if toc_detected else 5) if not _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes) else 82,
                target_candidate_page_used=True,
                toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
            )
        for page_number, page_row in by_page.items():
            sample_context = " ".join(
                [
                    str(page_row.get("detected_section_title") or ""),
                    str(page_row.get("page_text_sample") or ""),
                ]
            )
            prepared_sample = _normalize_pdf_preview_text_for_signal_detection(sample_context)
            has_target_title = _rzd_controlled_value_extraction_phrase_count(
                _rzd_controlled_value_extraction_statement_title_terms(target_type),
                prepared_sample["normalized_text"],
                prepared_sample["compact_text"],
            ) > 0
            has_metric_label = any(
                _rzd_manual_official_pdf_controlled_value_extraction_line_matches_metric(sample_context, spec)
                for spec in _rzd_manual_official_pdf_controlled_value_extraction_metric_specs().get(target_type, [])
            )
            if _as_bool(page_row.get("future_value_extraction_candidate")) or has_target_title or has_metric_label:
                _add_candidate(
                    target_type=target_type,
                    target=target,
                    page_number=page_number,
                    source="target_sample_or_metric_candidate",
                    rank=(7 if toc_detected else 6) if not _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes) else 83,
                    fallback_page_used=not (_as_bool(page_row.get(f"is_{target_type}_page")) or page_row.get("detected_section_type") == target_type),
                    toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                    page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                )
            score = _rzd_manual_official_pdf_controlled_value_extraction_page_score(
                target_type,
                page_row,
                bool(args.rzd_manual_official_pdf_controlled_value_extraction_allow_notes_pages),
            )
            if score > 0:
                _add_candidate(
                    target_type=target_type,
                    target=target,
                    page_number=page_number,
                    source="fallback_score",
                    rank=(8 if toc_detected else 7) if not _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes) else 84,
                    fallback_page_used=True,
                    toc_notes_range_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                    page_map_false_statement_flag_rejected=_rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes),
                )
    return candidates


def _rzd_manual_official_pdf_controlled_value_extraction_finalize_selected_pages(
    args: argparse.Namespace,
    *,
    candidates: list[dict[str, Any]],
    text_by_page: dict[int, dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    max_pages = int(args.rzd_manual_official_pdf_controlled_value_extraction_max_pages_per_target or 0)
    allow_notes = bool(args.rzd_manual_official_pdf_controlled_value_extraction_allow_notes_pages)
    selected: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    target_group_rows: list[dict[str, Any]] = []
    for target_type in _rzd_manual_official_pdf_controlled_value_extraction_target_types(args):
        target_candidates = [item for item in candidates if item.get("target_type") == target_type]
        scored: list[dict[str, Any]] = []
        for item in target_candidates:
            page_number = int(item.get("page_number") or 0)
            page_row = item.get("page_map_row") if isinstance(item.get("page_map_row"), dict) else {}
            text = str((text_by_page.get(page_number) or {}).get("text") or page_row.get("page_text_sample") or "")
            assessment = _rzd_controlled_value_extraction_primary_statement_assessment(
                target_type,
                text=text,
                page_row=page_row,
                target_row=item.get("target_row") if isinstance(item.get("target_row"), dict) else {},
                selection_source=str(item.get("selection_source") or ""),
                allow_notes=allow_notes,
            )
            base_score = _rzd_manual_official_pdf_controlled_value_extraction_page_score(target_type, page_row, allow_notes)
            score = base_score + (1000 if assessment["accepted"] else 0) + int(assessment.get("table_row_candidate_count") or 0)
            scored.append({**item, "selection_score": score, "primary_assessment": assessment})

        scored_by_page = {int(item.get("page_number") or 0): item for item in scored if int(item.get("page_number") or 0) > 0}
        group_candidates: list[list[dict[str, Any]]] = []
        seen_groups: set[tuple[int, ...]] = set()

        def _add_group(items: Sequence[dict[str, Any]]) -> None:
            pages = tuple(dict.fromkeys(int(item.get("page_number") or 0) for item in items if int(item.get("page_number") or 0) > 0))
            if not pages or pages in seen_groups:
                return
            seen_groups.add(pages)
            group_candidates.append([scored_by_page[page] for page in pages if page in scored_by_page])

        for item in sorted(scored, key=lambda row: (int(row.get("selection_priority_rank") or 99), int(row.get("page_number") or 0))):
            page_number = int(item.get("page_number") or 0)
            if page_number <= 0:
                continue
            _add_group([item])
            next_item = scored_by_page.get(page_number + 1)
            if next_item and (target_type == "cash_flows" or _as_bool(item.get("target_start_page_used"))):
                _add_group([item, next_item])

        evaluated_groups: list[dict[str, Any]] = []
        for index, group in enumerate(group_candidates, start=1):
            pages = [int(item.get("page_number") or 0) for item in group if int(item.get("page_number") or 0) > 0]
            combined_text = "\n".join(
                str((text_by_page.get(page) or {}).get("text") or (scored_by_page.get(page, {}).get("page_map_row") or {}).get("page_text_sample") or "")
                for page in pages
            )
            group_page_row = {
                "page_number": pages[0] if pages else 0,
                "detected_section_title": " ".join(
                    str((item.get("page_map_row") or {}).get("detected_section_title") or "")
                    for item in group
                    if isinstance(item.get("page_map_row"), dict)
                ),
                "detected_section_type": target_type if any((item.get("page_map_row") or {}).get("detected_section_type") == target_type for item in group) else "",
                f"is_{target_type}_page": any(_as_bool((item.get("page_map_row") or {}).get(f"is_{target_type}_page")) for item in group),
                "is_contents_page": any(_as_bool((item.get("page_map_row") or {}).get("is_contents_page")) for item in group),
                "is_notes_page": any(_as_bool((item.get("page_map_row") or {}).get("is_notes_page")) for item in group),
                "is_auditor_report_page": any(_as_bool((item.get("page_map_row") or {}).get("is_auditor_report_page")) for item in group),
            }
            assessment = _rzd_controlled_value_extraction_verify_table_bearing_primary_page(
                target_type,
                combined_text,
                group_page_row,
                group[0].get("target_row") if group and isinstance(group[0].get("target_row"), dict) else {},
                selection_source=str(group[0].get("selection_source") or "") if group else "",
                allow_notes=allow_notes,
            )
            accepted = _as_bool(assessment.get("accepted"))
            reject_codes = list(assessment.get("reject_reason_codes") or [])
            if any(_rzd_controlled_value_extraction_is_tax_note_context(str((text_by_page.get(page) or {}).get("text") or ""), scored_by_page.get(page, {}).get("page_map_row") or {}) for page in pages):
                if target_type == "profit_or_loss" and "primary_profit_or_loss_page_tax_note_only" not in reject_codes:
                    reject_codes.append("primary_profit_or_loss_page_tax_note_only")
                accepted = False
            group_row = {
                "target_group_id": f"rzd_manual_official_pdf_controlled_value_target_group:{target_type}:{','.join(str(page) for page in pages) or index}",
                "target_type": target_type,
                "selected_pages": pages,
                "primary_statement_group_accepted": bool(accepted),
                "primary_statement_group_rejected": not bool(accepted),
                "row_score": int(assessment.get("table_bearing_primary_page_score") or 0)
                + sum(int(item.get("selection_score") or 0) for item in group),
                "value_count": int(assessment.get("target_specific_value_row_count") or 0),
                "target_specific_required_metric_count": int(assessment.get("target_specific_required_metric_count") or 0),
                "reason_codes": list(assessment.get("accepted_reason_codes") or assessment.get("reason_codes") or []),
                "reject_reason_codes": reject_codes,
                "tax_note_group": any(
                    _rzd_controlled_value_extraction_is_tax_note_context(
                        str((text_by_page.get(page) or {}).get("text") or ""),
                        scored_by_page.get(page, {}).get("page_map_row") or {},
                    )
                    for page in pages
                ),
                "safe_hint": "Target group is a static preview selection only; Task170 does not import values.",
            }
            evaluated_groups.append({"row": group_row, "items": group, "accepted": accepted})
            target_group_rows.append(group_row)

        accepted_groups = [group for group in evaluated_groups if _as_bool((group.get("row") or {}).get("primary_statement_group_accepted"))]
        pool: list[dict[str, Any]] = []
        selected_group_row: dict[str, Any] | None = None
        if accepted_groups:
            chosen_group = sorted(
                accepted_groups,
                key=lambda group: (
                    min(int(item.get("selection_priority_rank") or 99) for item in group["items"]),
                    len(group["items"]),
                    -int((group.get("row") or {}).get("row_score") or 0),
                    min(int(item.get("page_number") or 0) for item in group["items"]),
                ),
            )[0]
            selected_group_row = chosen_group.get("row") if isinstance(chosen_group.get("row"), dict) else None
            pool = list(chosen_group.get("items") or [])
        if not pool:
            warnings.append({"message": "controlled_value_extraction_target_missing_selected_pages", "target_type": target_type})
            pool = [
                item
                for item in scored
                if int(item.get("selection_score") or 0) > 0
                and not _as_bool((item.get("page_map_row") or {}).get("is_contents_page"))
                and not _as_bool((item.get("page_map_row") or {}).get("is_auditor_report_page"))
                and (allow_notes or not _as_bool((item.get("page_map_row") or {}).get("is_notes_page")))
            ]
        for item in sorted(
            pool,
            key=lambda row: (
                int(row.get("selection_priority_rank") or 99),
                -int(row.get("selection_score") or 0),
                int(row.get("page_number") or 0),
            ),
        )[:max_pages]:
            selected.append(
                {
                    **item,
                    "target_group_id": (selected_group_row or {}).get("target_group_id") or "",
                    "primary_statement_group_accepted": bool(selected_group_row),
                    "primary_statement_group_reject_reason_codes": (selected_group_row or {}).get("reject_reason_codes") or [],
                    "primary_statement_group_reason_codes": (selected_group_row or {}).get("reason_codes") or [],
                }
            )
    return selected, warnings, target_group_rows


def _rzd_controlled_value_extraction_group_acceptance(
    target_type: str,
    pages: Sequence[int],
    discovery: dict[str, Any],
) -> dict[str, Any]:
    candidate_rows_by_page = discovery.get("candidate_rows_by_page") if isinstance(discovery.get("candidate_rows_by_page"), dict) else {}
    title_matches_by_page = discovery.get("title_matches_by_page") if isinstance(discovery.get("title_matches_by_page"), dict) else {}
    page_scores = discovery.get("page_scores") if isinstance(discovery.get("page_scores"), dict) else {}
    rows: list[dict[str, Any]] = []
    for page in pages:
        rows.extend(candidate_rows_by_page.get(int(page)) or [])
    metric_keys = {str(row.get("metric_key") or "") for row in rows}
    broad_pl_keys = metric_keys & _rzd_controlled_value_extraction_profit_or_loss_broad_metric_keys()
    generic_pl_row_count = sum(
        1
        for row in rows
        if target_type == "profit_or_loss" and _as_bool(row.get("generic_metric"))
    )
    required_count = 1 if target_type == "cash_flows" else _rzd_controlled_value_extraction_target_required_metric_count(target_type)
    reject_codes: list[str] = []
    title_anchor_pages = [
        int(page)
        for page in pages
        if (
            _as_bool((title_matches_by_page.get(int(page)) or {}).get("target_title_matched"))
            or _as_bool((page_scores.get(int(page)) or {}).get("toc_primary_page_enforced_extraction"))
        )
        and not _as_bool((title_matches_by_page.get(int(page)) or {}).get("cross_target_title_detected"))
    ]
    cross_target_pages = [
        int(page)
        for page in pages
        if _as_bool((title_matches_by_page.get(int(page)) or {}).get("cross_target_title_detected"))
    ]
    value_pages = sorted({int(row.get("page_number") or row.get("statement_page") or 0) for row in rows if int(row.get("page_number") or row.get("statement_page") or 0) > 0})
    if not title_anchor_pages:
        reject_codes.append("target_statement_title_missing")
        reject_codes.append("title_anchor_missing_group")
    if cross_target_pages:
        reject_codes.append("controlled_value_extraction_cross_target_page_rejected")
    if title_anchor_pages:
        allowed_value_pages = set(title_anchor_pages)
        continuation_limit = 6 if target_type == "statement_of_financial_position" else 4 if target_type == "profit_or_loss" else 2
        for anchor in title_anchor_pages:
            allowed_value_pages.update(range(anchor + 1, anchor + continuation_limit + 1))
        if any(page not in allowed_value_pages for page in value_pages):
            reject_codes.append("target_statement_title_anchor_missing_for_value_page")
    if len(metric_keys) < required_count:
        reject_codes.append("primary_statement_table_rows_missing")
    if target_type == "profit_or_loss" and len(broad_pl_keys) < 1 and generic_pl_row_count < 1:
        reject_codes.append("primary_profit_or_loss_group_tax_note_only")
    accepted = not reject_codes
    representative_title = next((title_matches_by_page.get(page) for page in title_anchor_pages if isinstance(title_matches_by_page.get(page), dict)), {})
    if not representative_title and pages:
        representative_title = title_matches_by_page.get(int(pages[0])) if isinstance(title_matches_by_page.get(int(pages[0])), dict) else {}
    cross_title_type = ""
    for page in cross_target_pages:
        cross_title_type = str((title_matches_by_page.get(page) or {}).get("cross_target_title_type") or "")
        if cross_title_type:
            break
    inherited_title_anchor = bool(title_anchor_pages and any(page not in title_anchor_pages for page in value_pages))
    reason_codes = ["extract_first_primary_group_discovered", "target_metric_rows_verified", "target_statement_title_anchored"] if accepted else []
    if accepted and inherited_title_anchor:
        reason_codes.append("target_statement_title_anchor_inherited_from_previous_page")
    if accepted and any(_as_bool((page_scores.get(int(page)) or {}).get("toc_primary_page_anchor_used")) for page in pages):
        reason_codes.append("toc_primary_page_anchor_used")
    if accepted and any(_as_bool((page_scores.get(int(page)) or {}).get("toc_primary_page_continuation_used")) for page in pages):
        reason_codes.append("toc_primary_page_continuation_used")
    if accepted and any(_as_bool((page_scores.get(int(page)) or {}).get("toc_primary_page_enforced_extraction")) for page in pages):
        reason_codes.append("toc_primary_page_enforced_extraction")
    return {
        "accepted": bool(accepted),
        "value_count": len(rows),
        "metric_keys": sorted(metric_keys),
        "broad_metric_keys": sorted(broad_pl_keys),
        "generic_profit_or_loss_row_count": generic_pl_row_count,
        "required_metric_count": required_count,
        "reject_reason_codes": reject_codes,
        "reason_codes": reason_codes,
        "candidate_rows": rows,
        "title_anchor_pages": title_anchor_pages,
        "value_pages": value_pages,
        "target_title_matched": bool(title_anchor_pages),
        "matched_title": str(representative_title.get("matched_title") or ""),
        "matched_title_line_number": int(representative_title.get("matched_title_line_number") or 0),
        "cross_target_title_detected": bool(cross_target_pages),
        "cross_target_title_type": cross_title_type,
        "target_statement_title_anchor_inherited_from_previous_page": bool(inherited_title_anchor),
    }


def _rzd_manual_official_pdf_controlled_value_extraction_finalize_selected_pages_extract_first(
    args: argparse.Namespace,
    *,
    candidates: list[dict[str, Any]],
    text_by_page: dict[int, dict[str, Any]],
    discovery_by_target: dict[str, dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    max_pages = int(args.rzd_manual_official_pdf_controlled_value_extraction_max_pages_per_target or 0)
    allow_notes = bool(args.rzd_manual_official_pdf_controlled_value_extraction_allow_notes_pages)
    selected: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    target_group_rows: list[dict[str, Any]] = []
    for target_type in _rzd_manual_official_pdf_controlled_value_extraction_target_types(args):
        target_candidates = [item for item in candidates if item.get("target_type") == target_type]
        by_page: dict[int, dict[str, Any]] = {}
        for item in target_candidates:
            page_number = int(item.get("page_number") or 0)
            if page_number > 0 and page_number not in by_page:
                by_page[page_number] = item
        discovery = discovery_by_target.get(target_type) or {}
        candidate_rows_by_page = discovery.get("candidate_rows_by_page") if isinstance(discovery.get("candidate_rows_by_page"), dict) else {}
        page_scores = discovery.get("page_scores") if isinstance(discovery.get("page_scores"), dict) else {}
        page_rejects = discovery.get("page_reject_reason_codes") if isinstance(discovery.get("page_reject_reason_codes"), dict) else {}
        ranked_pages = sorted(
            by_page,
            key=lambda page: (
                int(by_page[page].get("selection_priority_rank") or 99),
                -int((page_scores.get(page) or {}).get("page_total_discovery_score") or 0),
                page,
            ),
        )
        value_pages = [
            page
            for page in sorted(
                candidate_rows_by_page,
                key=lambda page: (
                    -int((page_scores.get(page) or {}).get("page_total_discovery_score") or 0),
                    int(by_page.get(page, {}).get("selection_priority_rank") or 99),
                    int(page),
                ),
            )
            if candidate_rows_by_page.get(page)
        ]
        group_page_sets: list[list[int]] = []
        seen_groups: set[tuple[int, ...]] = set()

        def _add_group(pages: Sequence[int]) -> None:
            group = [page for page in dict.fromkeys(int(page) for page in pages if int(page) in by_page)]
            if not group:
                return
            key = tuple(group)
            if key in seen_groups:
                return
            seen_groups.add(key)
            group_page_sets.append(group)

        if value_pages:
            _add_group(value_pages[:max_pages])
        for page in ranked_pages:
            _add_group([page])
            if page + 1 in by_page:
                _add_group([page, page + 1])
            title_match = (discovery.get("title_matches_by_page") or {}).get(page) if isinstance(discovery.get("title_matches_by_page"), dict) else {}
            if isinstance(title_match, dict) and _as_bool(title_match.get("target_title_matched")) and not _as_bool(title_match.get("cross_target_title_detected")):
                continuation_limit = 6 if target_type == "statement_of_financial_position" else 4 if target_type == "profit_or_loss" else 2
                for offset in range(2, continuation_limit + 1):
                    continuation_page = page + offset
                    if continuation_page not in by_page:
                        continue
                    continuation_title = (discovery.get("title_matches_by_page") or {}).get(continuation_page) if isinstance(discovery.get("title_matches_by_page"), dict) else {}
                    if isinstance(continuation_title, dict) and _as_bool(continuation_title.get("cross_target_title_detected")):
                        break
                    _add_group([page, continuation_page])
                    if offset <= max_pages - 1:
                        _add_group(range(page, continuation_page + 1))
        evaluated_groups: list[dict[str, Any]] = []
        for group_pages in group_page_sets:
            acceptance = _rzd_controlled_value_extraction_group_acceptance(target_type, group_pages, discovery)
            row_score = sum(int((page_scores.get(page) or {}).get("page_total_discovery_score") or 0) for page in group_pages)
            tax_note_group = any(
                _rzd_controlled_value_extraction_is_tax_note_context(
                    str((text_by_page.get(page) or {}).get("text") or ((by_page.get(page) or {}).get("page_map_row") or {}).get("page_text_sample") or ""),
                    (by_page.get(page) or {}).get("page_map_row") or {},
                )
                for page in group_pages
            )
            reject_codes = list(acceptance.get("reject_reason_codes") or [])
            if (
                target_type == "profit_or_loss"
                and tax_note_group
                and not acceptance.get("broad_metric_keys")
                and int(acceptance.get("generic_profit_or_loss_row_count") or 0) < 1
            ):
                reject_codes = list(dict.fromkeys([*reject_codes, "primary_profit_or_loss_group_tax_note_only"]))
            accepted = _as_bool(acceptance.get("accepted")) and not reject_codes
            group_row = {
                "target_group_id": f"rzd_manual_official_pdf_controlled_value_target_group:{target_type}:{','.join(str(page) for page in group_pages)}",
                "target_type": target_type,
                "selected_pages": group_pages,
                "primary_statement_group_accepted": bool(accepted),
                "primary_statement_group_rejected": not bool(accepted),
                "row_score": int(row_score),
                "group_statement_row_score": int(row_score),
                "value_count": int(acceptance.get("value_count") or 0),
                "group_value_candidate_count": int(acceptance.get("value_count") or 0),
                "target_specific_required_metric_count": int(acceptance.get("required_metric_count") or 0),
                "metric_keys": acceptance.get("metric_keys") or [],
                "reason_codes": list(acceptance.get("reason_codes") or []) if accepted else [],
                "group_accepted_reason_codes": list(acceptance.get("reason_codes") or []) if accepted else [],
                "reject_reason_codes": reject_codes,
                "group_reject_reason_codes": reject_codes,
                "tax_note_group": bool(tax_note_group),
                "target_title_matched": _as_bool(acceptance.get("target_title_matched")),
                "target_statement_title_anchor_inherited_from_previous_page": _as_bool(
                    acceptance.get("target_statement_title_anchor_inherited_from_previous_page")
                ),
                "matched_title": str(acceptance.get("matched_title") or ""),
                "matched_title_line_number": int(acceptance.get("matched_title_line_number") or 0),
                "cross_target_title_detected": _as_bool(acceptance.get("cross_target_title_detected")),
                "cross_target_title_type": str(acceptance.get("cross_target_title_type") or ""),
                "title_anchor_pages": list(acceptance.get("title_anchor_pages") or []),
                "target_group_diagnostics_truncated": False,
                "safe_hint": "Target group is a static preview selection only; Task170 does not import values.",
            }
            evaluated_groups.append({"row": group_row, "pages": group_pages, "accepted": accepted, "candidate_rows": acceptance.get("candidate_rows") or []})
        accepted_groups = [group for group in evaluated_groups if _as_bool((group.get("row") or {}).get("primary_statement_group_accepted"))]
        selected_group = None
        if accepted_groups:
            def _accepted_group_sort_key(group: dict[str, Any]) -> tuple[Any, ...]:
                row = group.get("row") or {}
                pages = group.get("pages") or [9999]
                missing_row_pages = sum(
                    1
                    for page in pages
                    if not (candidate_rows_by_page.get(int(page)) or [])
                )
                if target_type == "statement_of_financial_position":
                    metric_keys = {str(key or "") for key in (row.get("metric_keys") or [])}
                    asset_keys = {"non_current_assets", "current_assets", "total_assets", "cash_and_cash_equivalents"}
                    equity_liability_keys = {
                        "total_equity",
                        "non_current_liabilities",
                        "current_liabilities",
                        "total_liabilities",
                        "total_equity_and_liabilities",
                    }
                    return (
                        missing_row_pages,
                        -len(metric_keys & asset_keys),
                        -len(metric_keys & equity_liability_keys),
                        -len(metric_keys),
                        min(int(by_page.get(page, {}).get("selection_priority_rank") or 99) for page in pages),
                        -int(row.get("row_score") or 0),
                        len(pages),
                        min(pages),
                    )
                return (
                    missing_row_pages if target_type != "cash_flows" else 0,
                    min(int(by_page.get(page, {}).get("selection_priority_rank") or 99) for page in pages),
                    len(pages),
                    -int(row.get("row_score") or 0),
                    min(pages),
                )
            selected_group = sorted(
                accepted_groups,
                key=_accepted_group_sort_key,
            )[0]
            target_group_rows.append(selected_group["row"])
        rejected_groups = [group for group in evaluated_groups if group is not selected_group and not _as_bool((group.get("row") or {}).get("primary_statement_group_accepted"))]
        rejected_groups = sorted(
            rejected_groups,
            key=lambda group: (
                -int((group.get("row") or {}).get("row_score") or 0),
                min(group.get("pages") or [9999]),
            ),
        )
        truncated = len(rejected_groups) > RZD_CONTROLLED_VALUE_EXTRACTION_REJECTED_GROUP_DIAGNOSTIC_LIMIT
        for group in rejected_groups[:RZD_CONTROLLED_VALUE_EXTRACTION_REJECTED_GROUP_DIAGNOSTIC_LIMIT]:
            row = dict(group["row"])
            row["target_group_diagnostics_truncated"] = bool(truncated)
            target_group_rows.append(row)
        if not selected_group:
            toc_enforced_scores = [
                score
                for score in page_scores.values()
                if _as_bool(score.get("toc_primary_page_enforced_extraction"))
                and _as_bool(score.get("primary_statement_table_row_parser_attempted"))
            ]
            if toc_enforced_scores:
                warnings.append({"message": "controlled_value_extraction_primary_statement_parser_zero_values", "target_type": target_type})
            else:
                warnings.append({"message": "controlled_value_extraction_target_missing_selected_pages", "target_type": target_type})
            diagnostic_pages = ranked_pages[:max_pages]
        else:
            diagnostic_pages = list(selected_group.get("pages") or [])[:max_pages]
        for page in diagnostic_pages:
            item = by_page.get(page)
            if not item:
                continue
            page_row = item.get("page_map_row") if isinstance(item.get("page_map_row"), dict) else {}
            text = str((text_by_page.get(page) or {}).get("text") or page_row.get("page_text_sample") or "")
            page_score = page_scores.get(page) or {}
            title_match = (discovery.get("title_matches_by_page") or {}).get(page) if isinstance(discovery.get("title_matches_by_page"), dict) else {}
            if not isinstance(title_match, dict):
                title_match = {}
            rows_for_page = candidate_rows_by_page.get(page) or []
            accepted_page = bool(selected_group and page in (selected_group.get("pages") or []) and rows_for_page)
            assessment = {
                "accepted": accepted_page,
                "table_bearing_primary_page": accepted_page,
                "reject_reason_codes": list(page_rejects.get(page) or ([] if accepted_page else ["primary_statement_table_rows_missing"])),
                "reason_codes": ["extract_first_page_in_accepted_primary_group"] if accepted_page else [],
                "accepted_reason_codes": ["extract_first_page_in_accepted_primary_group"] if accepted_page else [],
                "page_title_detected": _rzd_controlled_value_extraction_page_title(target_type, text, page_row),
                "title_match": title_match,
                "table_row_candidate_count": len(rows_for_page),
                "target_specific_value_row_count": len(rows_for_page),
                "target_specific_required_metric_count": 1 if target_type == "cash_flows" else _rzd_controlled_value_extraction_target_required_metric_count(target_type),
                "table_bearing_primary_page_score": int(page_score.get("page_total_discovery_score") or 0),
                "scan_diagnostics": {
                    "candidate_line_scanned_count": int(page_score.get("candidate_line_scanned_count") or 0),
                    "candidate_line_matched_count": int(page_score.get("candidate_line_matched_count") or 0),
                    "candidate_line_rejected_count": int(page_score.get("candidate_line_rejected_count") or 0),
                    "contents_navigation_line_rejected_count": int(page_score.get("contents_navigation_line_rejected_count") or 0),
                    "page_number_value_rejected_count": int(page_score.get("page_number_value_rejected_count") or 0),
                    "date_period_line_rejected_count": int(page_score.get("date_period_line_rejected_count") or 0),
                    "date_number_value_rejected_count": int(page_score.get("date_number_value_rejected_count") or 0),
                    "small_page_or_note_number_value_rejected_count": int(page_score.get("small_page_or_note_number_value_rejected_count") or 0),
                    "wide_equity_movement_line_rejected_count": int(page_score.get("wide_equity_movement_line_rejected_count") or 0),
                    "wide_equity_movement_value_rejected_count": int(page_score.get("wide_equity_movement_value_rejected_count") or 0),
                    "false_generic_statement_row_rejected_count": int(page_score.get("false_generic_statement_row_rejected_count") or 0),
                    "generic_row_fx_rate_rejected_count": int(page_score.get("generic_row_fx_rate_rejected_count") or 0),
                    "generic_row_percent_or_discount_rejected_count": int(page_score.get("generic_row_percent_or_discount_rejected_count") or 0),
                    "generic_row_statement_reference_rejected_count": int(page_score.get("generic_row_statement_reference_rejected_count") or 0),
                    "generic_row_date_or_period_rejected_count": int(page_score.get("generic_row_date_or_period_rejected_count") or 0),
                    "semantic_component_oci_row_rejected_count": int(page_score.get("semantic_component_oci_row_rejected_count") or 0),
                    "semantic_wrong_aggregate_row_rejected_count": int(page_score.get("semantic_wrong_aggregate_row_rejected_count") or 0),
                    "semantic_cash_flow_starting_profit_row_rejected_count": int(
                        page_score.get("semantic_cash_flow_starting_profit_row_rejected_count") or 0
                    ),
                    "semantic_cash_flow_component_row_rejected_count": int(
                        page_score.get("semantic_cash_flow_component_row_rejected_count") or 0
                    ),
                "body_reference_title_rejected_count": int(page_score.get("body_reference_title_rejected_count") or 0),
                "body_reference_title_value_rejected_count": int(page_score.get("body_reference_title_value_rejected_count") or 0),
                "primary_statement_table_row_parser_attempted": _as_bool(page_score.get("primary_statement_table_row_parser_attempted")),
                "primary_statement_table_row_parser_success": _as_bool(page_score.get("primary_statement_table_row_parser_success")),
                "primary_statement_table_row_parser_value_count": int(page_score.get("primary_statement_table_row_parser_value_count") or 0),
                "primary_statement_table_row_parser_failure_reason_codes": list(
                    page_score.get("primary_statement_table_row_parser_failure_reason_codes") or []
                ),
                "toc_notes_range_page_rejected_count": 1 if _as_bool(page_score.get("toc_notes_range_rejected")) else 0,
                    "toc_notes_range_value_rejected_count": int(page_score.get("toc_notes_range_value_rejected_count") or 0),
                    "page_map_false_statement_flag_rejected_count": 1 if _as_bool(page_score.get("page_map_false_statement_flag_rejected")) else 0,
                    "contents_page_primary_rejected_count": 1 if _as_bool(page_score.get("contents_page_rejected_as_primary")) else 0,
                },
            }
            selected.append(
                {
                    **item,
                    "selection_score": int(page_score.get("page_total_discovery_score") or item.get("selection_score") or 0),
                    "primary_assessment": assessment,
                    "target_group_id": (selected_group or {}).get("row", {}).get("target_group_id") if selected_group else "",
                    "primary_statement_group_accepted": bool(selected_group),
                    "primary_statement_group_reject_reason_codes": (selected_group or {}).get("row", {}).get("reject_reason_codes", []) if selected_group else [],
                    "primary_statement_group_reason_codes": (selected_group or {}).get("row", {}).get("reason_codes", []) if selected_group else [],
                    "primary_statement_group_title_matched": _as_bool((selected_group or {}).get("row", {}).get("target_title_matched")),
                    "primary_statement_group_cross_target_title_detected": _as_bool((selected_group or {}).get("row", {}).get("cross_target_title_detected")),
                    "internal_candidate_rows": rows_for_page if selected_group and page in (selected_group.get("pages") or []) else [],
                }
            )
    return selected, warnings, target_group_rows


def _rzd_manual_official_pdf_controlled_value_extraction_selected_pages(
    args: argparse.Namespace,
    *,
    page_map_rows: list[dict[str, Any]],
    target_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    max_pages = int(args.rzd_manual_official_pdf_controlled_value_extraction_max_pages_per_target or 0)
    allow_notes = bool(args.rzd_manual_official_pdf_controlled_value_extraction_allow_notes_pages)
    target_types = _rzd_manual_official_pdf_controlled_value_extraction_target_types(args)
    by_page = {int(row.get("page_number") or 0): row for row in page_map_rows if int(row.get("page_number") or 0) > 0}
    selected: list[dict[str, Any]] = []
    seen: set[tuple[str, int]] = set()
    for target_type in target_types:
        target = next((row for row in target_rows if row.get("target_type") == target_type), {})
        target_candidate_pages = set(_rzd_manual_official_pdf_controlled_value_extraction_page_numbers(target.get("candidate_pages")))
        exact_pages = [
            int(row.get("page_number") or 0)
            for row in page_map_rows
            if int(row.get("page_number") or 0) > 0
            and (row.get("detected_section_type") == target_type or _as_bool(row.get(f"is_{target_type}_page")))
        ]
        candidate_pages = list(dict.fromkeys([*exact_pages, *target_candidate_pages]))
        if not candidate_pages and target:
            candidate_pages = _rzd_manual_official_pdf_controlled_value_extraction_page_numbers(target.get("candidate_pages"))
        if not candidate_pages:
            candidate_pages = [
                int(row.get("page_number") or 0)
                for row in page_map_rows
                if row.get("detected_section_type") == target_type
                or _as_bool(row.get(f"is_{target_type}_page"))
            ]
        scored: list[tuple[int, int, dict[str, Any]]] = []
        for page_number in candidate_pages:
            page_row = by_page.get(page_number, {})
            if not page_row:
                continue
            score = _rzd_manual_official_pdf_controlled_value_extraction_page_score(target_type, page_row, allow_notes)
            if _as_bool(page_row.get("is_auditor_report_page")) or _as_bool(page_row.get("is_contents_page")):
                continue
            if _as_bool(page_row.get("is_notes_page")) and not allow_notes:
                continue
            if score <= 0:
                continue
            scored.append((score, page_number, page_row))
        chosen_for_target = 0
        for score, page_number, page_row in sorted(scored, key=lambda item: (-item[0], item[1])):
            if chosen_for_target >= max_pages:
                break
            key = (target_type, page_number)
            if key in seen:
                continue
            seen.add(key)
            selected.append({"target_type": target_type, "page_number": page_number, "page_map_row": page_row, "target_row": target, "selection_score": score})
            chosen_for_target += 1
    return selected


def _rzd_manual_official_pdf_controlled_value_extraction_extract_page_texts(
    path: Path,
    pages: Sequence[int],
    backend: str = "auto",
) -> dict[int, dict[str, Any]]:
    backend = str(backend or "auto")
    unique_pages = [page for page in dict.fromkeys(int(page) for page in pages if int(page) > 0)]
    results: dict[int, dict[str, Any]] = {}
    if backend in {"auto", "pdftotext"}:
        executable = shutil.which("pdftotext")
        if executable:
            for page in unique_pages:
                try:
                    result = subprocess.run(
                        [executable, "-f", str(page), "-l", str(page), "-layout", "-enc", "UTF-8", str(path), "-"],
                        check=False,
                        capture_output=True,
                        timeout=30,
                    )
                except (OSError, subprocess.SubprocessError):
                    continue
                text = result.stdout.decode("utf-8", errors="replace") if result.stdout else ""
                if text.strip() and not _rzd_pdf_preview_text_looks_like_raw_pdf(text):
                    results[page] = {"text": text, "backend": "pdftotext"}
            if results or backend == "pdftotext":
                return results
    for module_name in ("pypdf", "PyPDF2"):
        if backend not in {"auto", module_name}:
            continue
        try:
            module = __import__(module_name)
            reader = module.PdfReader(str(path))
            for page in unique_pages:
                try:
                    text = reader.pages[page - 1].extract_text() or ""
                except Exception:
                    text = ""
                if text.strip() and not _rzd_pdf_preview_text_looks_like_raw_pdf(text):
                    results[page] = {"text": text, "backend": module_name}
            if results or backend == module_name:
                return results
        except Exception:
            continue
    if backend in {"auto", "pymupdf"}:
        try:
            fitz = __import__("fitz")
            document = fitz.open(str(path))
            try:
                for page in unique_pages:
                    if 1 <= page <= int(getattr(document, "page_count", len(document))):
                        text = document[page - 1].get_text() or ""
                        if text.strip() and not _rzd_pdf_preview_text_looks_like_raw_pdf(text):
                            results[page] = {"text": text, "backend": "pymupdf"}
            finally:
                document.close()
        except Exception:
            pass
    return results


def _rzd_controlled_value_extraction_text_profile(text: str) -> dict[str, int | bool]:
    text = str(text or "")
    nonempty_lines = [line.strip() for line in text.splitlines() if line.strip()]
    table_like_lines = 0
    for line in nonempty_lines:
        numbers = _rzd_manual_official_pdf_controlled_value_extraction_line_numbers(line)
        if len([value for _raw, value in numbers if isinstance(value, int)]) >= 2:
            table_like_lines += 1
    prepared = _normalize_pdf_preview_text_for_signal_detection(text)
    return {
        "char_count": len(text),
        "nonempty_line_count": len(nonempty_lines),
        "table_like_line_count": table_like_lines,
        "has_2025_column": "2025" in prepared["normalized_text"],
        "has_2024_column": "2024" in prepared["normalized_text"],
    }


def _rzd_controlled_value_extraction_toc_ocr_allowed_page(
    *,
    target_type: str,
    page_number: int,
    toc_info: dict[str, Any],
    allow_notes_pages: bool,
) -> bool:
    if page_number <= 0:
        return False
    if _rzd_controlled_value_extraction_page_is_in_toc_notes_range(page_number, toc_info, allow_notes_pages):
        return False
    anchor = int(toc_info.get(f"toc_{target_type}_page") or 0)
    if anchor <= 0:
        return False
    allowed_offsets = {
        "statement_of_financial_position": {0, 1},
        "profit_or_loss": {0},
        "other_comprehensive_income": {0},
        "cash_flows": {0, 1},
    }.get(target_type, {0})
    return page_number - anchor in allowed_offsets


def _rzd_controlled_value_extraction_page_text_probe(
    *,
    target_type: str,
    text: str,
    page_row: dict[str, Any],
    toc_primary: bool,
) -> dict[str, Any]:
    profile = _rzd_controlled_value_extraction_text_profile(text)
    prepared = _normalize_pdf_preview_text_for_signal_detection(
        " ".join([str(page_row.get("detected_section_title") or ""), str(text or "")])
    )
    title_matched = _rzd_controlled_value_extraction_phrase_count(
        _rzd_controlled_value_extraction_statement_title_terms(target_type),
        prepared["normalized_text"],
        prepared["compact_text"],
    ) > 0
    empty = int(profile["char_count"]) == 0 or int(profile["nonempty_line_count"]) == 0
    weak = bool(
        empty
        or int(profile["char_count"]) < 200
        or int(profile["nonempty_line_count"]) < 5
        or int(profile["table_like_line_count"]) < 1
        or not (_as_bool(profile["has_2025_column"]) and _as_bool(profile["has_2024_column"]))
        or (toc_primary and not title_matched)
    )
    if empty:
        result = "empty"
    elif weak:
        result = "weak"
    elif int(profile["table_like_line_count"]) > 0:
        result = "table_like"
    else:
        result = "strong"
    return {
        **profile,
        "target_title_matched": bool(title_matched),
        "page_text_empty_or_weak": bool(weak),
        "toc_primary_page_text_probe_result": result,
    }


def _rzd_controlled_value_extraction_ocr_diagnostic_row(
    *,
    page_number: int,
    target_type: str,
    attempted: bool,
    success: bool,
    text: str = "",
    error: str = "",
    render_available: bool = False,
    render_backend: str = "",
    render_attempted: bool = False,
    render_success: bool = False,
    effective_source: str = "",
    effective_backend: str = "",
) -> dict[str, Any]:
    profile = _rzd_controlled_value_extraction_text_profile(text)
    return {
        "ocr_diagnostic_id": f"rzd_manual_official_pdf_controlled_value_ocr:{target_type or 'unknown'}:{page_number}",
        "page_number": int(page_number or 0),
        "target_type": str(target_type or ""),
        "ocr_attempted": bool(attempted),
        "ocr_success": bool(success),
        "ocr_text_char_count": int(profile.get("char_count") or 0),
        "ocr_text_nonempty_line_count": int(profile.get("nonempty_line_count") or 0),
        "ocr_error": str(error or ""),
        "local_pdf_page_render_available": bool(render_available),
        "local_pdf_page_render_backend": str(render_backend or ""),
        "local_pdf_page_render_attempted": bool(render_attempted),
        "local_pdf_page_render_success": bool(render_success),
        "effective_page_text_source": str(effective_source or ""),
        "effective_page_text_backend": str(effective_backend or ""),
        "safe_hint": "Local OCR diagnostic only. Task170 does not fetch, download, import, score, trade, or mutate production state.",
    }


def _rzd_controlled_value_extraction_ocr_local_pdf_pages(
    pdf_path: Path,
    page_numbers: Sequence[int],
    output_dir: Path,
    languages: str = "rus+eng",
) -> dict[int, dict[str, Any]]:
    unique_pages = [page for page in dict.fromkeys(int(page) for page in page_numbers if int(page) > 0)]
    rows: dict[int, dict[str, Any]] = {}
    pdftoppm = shutil.which("pdftoppm")
    tesseract = shutil.which("tesseract")
    tools_available = bool(pdftoppm and tesseract)
    if not tools_available:
        for page in unique_pages:
            rows[page] = _rzd_controlled_value_extraction_ocr_diagnostic_row(
                page_number=page,
                target_type="",
                attempted=True,
                success=False,
                error="local_pdf_ocr_tools_unavailable",
                render_available=bool(pdftoppm),
                render_backend="pdftoppm" if pdftoppm else "",
                render_attempted=False,
                render_success=False,
            )
        return rows
    try:
        output_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        for page in unique_pages:
            rows[page] = _rzd_controlled_value_extraction_ocr_diagnostic_row(
                page_number=page,
                target_type="",
                attempted=True,
                success=False,
                error=f"local_pdf_ocr_output_dir_failed:{exc}",
                render_available=True,
                render_backend="pdftoppm",
                render_attempted=False,
                render_success=False,
            )
        return rows
    for page in unique_pages:
        prefix = output_dir / f"task170_ocr_page_{page}"
        try:
            render = subprocess.run(
                [pdftoppm, "-f", str(page), "-l", str(page), "-png", str(pdf_path), str(prefix)],
                check=False,
                capture_output=True,
                timeout=60,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            rows[page] = _rzd_controlled_value_extraction_ocr_diagnostic_row(
                page_number=page,
                target_type="",
                attempted=True,
                success=False,
                error=f"local_pdf_render_failed:{exc}",
                render_available=True,
                render_backend="pdftoppm",
                render_attempted=True,
                render_success=False,
            )
            continue
        image_candidates = sorted(output_dir.glob(f"{prefix.name}*.png"))
        if render.returncode != 0 or not image_candidates:
            error = (render.stderr or b"").decode("utf-8", errors="replace")[:300]
            rows[page] = _rzd_controlled_value_extraction_ocr_diagnostic_row(
                page_number=page,
                target_type="",
                attempted=True,
                success=False,
                error=f"local_pdf_render_failed:{error}",
                render_available=True,
                render_backend="pdftoppm",
                render_attempted=True,
                render_success=False,
            )
            continue
        image_path = image_candidates[0]
        try:
            ocr = subprocess.run(
                [tesseract, str(image_path), "stdout", "-l", languages],
                check=False,
                capture_output=True,
                timeout=90,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            rows[page] = _rzd_controlled_value_extraction_ocr_diagnostic_row(
                page_number=page,
                target_type="",
                attempted=True,
                success=False,
                error=f"local_pdf_ocr_failed:{exc}",
                render_available=True,
                render_backend="pdftoppm",
                render_attempted=True,
                render_success=True,
            )
            continue
        text = ocr.stdout.decode("utf-8", errors="replace") if ocr.stdout else ""
        success = ocr.returncode == 0 and bool(text.strip()) and not _rzd_pdf_preview_text_looks_like_raw_pdf(text)
        error = "" if success else (ocr.stderr or b"").decode("utf-8", errors="replace")[:300] or "local_pdf_ocr_empty_text"
        row = _rzd_controlled_value_extraction_ocr_diagnostic_row(
            page_number=page,
            target_type="",
            attempted=True,
            success=success,
            text=text if success else "",
            error=error,
            render_available=True,
            render_backend="pdftoppm",
            render_attempted=True,
            render_success=True,
            effective_source="ocr_tesseract" if success else "",
            effective_backend="ocr_tesseract" if success else "",
        )
        row["text"] = text if success else ""
        row["backend"] = "ocr_tesseract" if success else ""
        rows[page] = row
    return rows


def _rzd_controlled_value_extraction_apply_toc_ocr_fallback(
    *,
    args: argparse.Namespace,
    controlled_pdf_path: Path,
    candidate_pages: Sequence[dict[str, Any]],
    page_map_by_page: dict[int, dict[str, Any]],
    text_by_page: dict[int, dict[str, Any]],
    toc_info: dict[str, Any],
    allow_notes_pages: bool,
) -> tuple[dict[int, dict[str, Any]], dict[str, Any], list[dict[str, Any]]]:
    stats: dict[str, Any] = {
        "toc_primary_page_text_probe_count": 0,
        "toc_primary_page_text_probe_empty_count": 0,
        "toc_primary_page_text_probe_weak_count": 0,
        "toc_primary_page_text_probe_table_like_count": 0,
        "local_pdf_page_render_available": False,
        "local_pdf_page_render_backend": "",
        "local_pdf_page_render_attempt_count": 0,
        "local_pdf_page_render_success_count": 0,
        "local_pdf_page_render_failed_count": 0,
        "ocr_text_extraction_available": False,
        "ocr_text_extraction_backend": "",
        "ocr_text_extraction_languages": "rus+eng",
        "ocr_page_attempt_count": 0,
        "ocr_page_success_count": 0,
        "ocr_page_failed_count": 0,
        "ocr_primary_statement_page_count": 0,
        "ocr_text_char_count_total": 0,
        "ocr_diagnostic_rows": [],
    }
    page_targets: dict[int, str] = {}
    probe_pages: set[int] = set()
    for item in candidate_pages:
        if not _as_bool(item.get("toc_primary_page_candidate")):
            continue
        target_type = str(item.get("target_type") or item.get("toc_primary_page_target_type") or "")
        page_number = int(item.get("page_number") or 0)
        if not _rzd_controlled_value_extraction_toc_ocr_allowed_page(
            target_type=target_type,
            page_number=page_number,
            toc_info=toc_info,
            allow_notes_pages=allow_notes_pages,
        ):
            continue
        probe_pages.add(page_number)
        page_targets.setdefault(page_number, target_type)
    ocr_needed: list[int] = []
    for page_number in sorted(probe_pages):
        target_type = page_targets.get(page_number, "")
        page_row = page_map_by_page.get(page_number) or {}
        existing = dict(text_by_page.get(page_number) or {})
        original_text = str(existing.get("text") or "")
        original_backend = str(existing.get("backend") or "")
        probe = _rzd_controlled_value_extraction_page_text_probe(
            target_type=target_type,
            text=original_text,
            page_row=page_row,
            toc_primary=True,
        )
        stats["toc_primary_page_text_probe_count"] = int(stats["toc_primary_page_text_probe_count"]) + 1
        result = str(probe.get("toc_primary_page_text_probe_result") or "")
        if result == "empty":
            stats["toc_primary_page_text_probe_empty_count"] = int(stats["toc_primary_page_text_probe_empty_count"]) + 1
        if _as_bool(probe.get("page_text_empty_or_weak")):
            stats["toc_primary_page_text_probe_weak_count"] = int(stats["toc_primary_page_text_probe_weak_count"]) + 1
            ocr_needed.append(page_number)
        if int(probe.get("table_like_line_count") or 0) > 0:
            stats["toc_primary_page_text_probe_table_like_count"] = int(stats["toc_primary_page_text_probe_table_like_count"]) + 1
            parser_rows, _parser_diagnostics = _rzd_controlled_value_extraction_parse_primary_statement_table_rows(
                target_type=target_type,
                page_number=page_number,
                page_text=original_text,
                text_source="controlled_pdf_selected_page_text" if original_text.strip() else "",
                text_backend=original_backend,
                is_contents_page=_as_bool(page_row.get("is_contents_page")),
            )
            if not parser_rows and page_number not in ocr_needed:
                result = "table_like_parser_zero_values"
                stats["toc_primary_page_text_probe_weak_count"] = int(stats["toc_primary_page_text_probe_weak_count"]) + 1
                ocr_needed.append(page_number)
        text_by_page[page_number] = {
            **existing,
            "text": original_text,
            "backend": original_backend,
            "page_text_backend": original_backend,
            "page_text_nonempty_line_count": int(probe.get("nonempty_line_count") or 0),
            "page_text_table_like_line_count": int(probe.get("table_like_line_count") or 0),
            "page_text_empty_or_weak": _as_bool(probe.get("page_text_empty_or_weak")),
            "toc_primary_page_text_probe": True,
            "toc_primary_page_text_probe_target_type": target_type,
            "toc_primary_page_text_probe_result": result,
            "effective_page_text_source": "controlled_pdf_selected_page_text" if original_text.strip() else "",
            "effective_page_text_backend": original_backend,
        }
    if not ocr_needed:
        return text_by_page, stats, []
    output_dir = (
        args.operator_resolution_chain_output_dir / "rzd_manual_official_pdf_controlled_value_extraction_ocr_work_task170"
        if args.operator_resolution_chain_output_dir
        else Path(tempfile.gettempdir()) / "rzd_manual_official_pdf_controlled_value_extraction_ocr_work_task170"
    )
    ocr_results = _rzd_controlled_value_extraction_ocr_local_pdf_pages(
        controlled_pdf_path,
        sorted(ocr_needed),
        output_dir,
        languages="rus+eng",
    )
    warnings: list[dict[str, Any]] = []
    for page_number in sorted(ocr_needed):
        target_type = page_targets.get(page_number, "")
        ocr_row = dict(ocr_results.get(page_number) or {})
        ocr_row["target_type"] = target_type
        ocr_row["ocr_diagnostic_id"] = f"rzd_manual_official_pdf_controlled_value_ocr:{target_type or 'unknown'}:{page_number}"
        attempted = _as_bool(ocr_row.get("ocr_attempted")) or True
        success = _as_bool(ocr_row.get("ocr_success"))
        text = str(ocr_row.get("text") or "")
        stats["ocr_page_attempt_count"] = int(stats["ocr_page_attempt_count"]) + 1
        stats["local_pdf_page_render_attempt_count"] = int(stats["local_pdf_page_render_attempt_count"]) + (1 if _as_bool(ocr_row.get("local_pdf_page_render_attempted")) else 0)
        if _as_bool(ocr_row.get("local_pdf_page_render_available")):
            stats["local_pdf_page_render_available"] = True
            stats["local_pdf_page_render_backend"] = str(ocr_row.get("local_pdf_page_render_backend") or "pdftoppm")
        if _as_bool(ocr_row.get("local_pdf_page_render_success")):
            stats["local_pdf_page_render_success_count"] = int(stats["local_pdf_page_render_success_count"]) + 1
        elif _as_bool(ocr_row.get("local_pdf_page_render_attempted")):
            stats["local_pdf_page_render_failed_count"] = int(stats["local_pdf_page_render_failed_count"]) + 1
        existing = dict(text_by_page.get(page_number) or {})
        if success and text.strip():
            ocr_profile = _rzd_controlled_value_extraction_text_profile(text)
            stats["ocr_page_success_count"] = int(stats["ocr_page_success_count"]) + 1
            stats["ocr_primary_statement_page_count"] = int(stats["ocr_primary_statement_page_count"]) + 1
            stats["ocr_text_char_count_total"] = int(stats["ocr_text_char_count_total"]) + int(ocr_profile.get("char_count") or 0)
            stats["ocr_text_extraction_available"] = True
            stats["ocr_text_extraction_backend"] = "ocr_tesseract"
            text_by_page[page_number] = {
                **existing,
                "text": text,
                "backend": "ocr_tesseract",
                "ocr_attempted": attempted,
                "ocr_success": True,
                "ocr_text_char_count": int(ocr_profile.get("char_count") or 0),
                "ocr_text_nonempty_line_count": int(ocr_profile.get("nonempty_line_count") or 0),
                "ocr_error": "",
                "effective_page_text_source": "ocr_tesseract",
                "effective_page_text_backend": "ocr_tesseract",
            }
            ocr_row["effective_page_text_source"] = "ocr_tesseract"
            ocr_row["effective_page_text_backend"] = "ocr_tesseract"
        else:
            stats["ocr_page_failed_count"] = int(stats["ocr_page_failed_count"]) + 1
            if not any(warning.get("message") == "controlled_value_extraction_ocr_unavailable_or_failed" for warning in warnings):
                warnings.append({"message": "controlled_value_extraction_ocr_unavailable_or_failed"})
            sample = str((page_map_by_page.get(page_number) or {}).get("page_text_sample") or "")
            fallback_source = "task169_page_map_sample" if sample.strip() and not str(existing.get("text") or "").strip() else existing.get("effective_page_text_source") or ""
            fallback_backend = "task169_page_sample" if fallback_source == "task169_page_map_sample" else existing.get("effective_page_text_backend") or ""
            text_by_page[page_number] = {
                **existing,
                "ocr_attempted": attempted,
                "ocr_success": False,
                "ocr_text_char_count": 0,
                "ocr_text_nonempty_line_count": 0,
                "ocr_error": str(ocr_row.get("ocr_error") or "local_pdf_ocr_failed"),
                "effective_page_text_source": fallback_source,
                "effective_page_text_backend": fallback_backend,
            }
            ocr_row["effective_page_text_source"] = str(fallback_source or "")
            ocr_row["effective_page_text_backend"] = str(fallback_backend or "")
        if "safe_hint" not in ocr_row:
            ocr_row["safe_hint"] = "Local OCR diagnostic only. Task170 does not fetch, download, import, score, trade, or mutate production state."
        stats["ocr_diagnostic_rows"].append(ocr_row)
    return text_by_page, stats, warnings


