def _rzd_controlled_values_financial_ratio_interpretation_review_failed_report(
    errors: list[dict[str, Any]],
    *,
    artifacts: dict[str, Path | None],
    write_outputs: bool = True,
) -> dict[str, Any]:
    blocker_rows = [
        _rzd_controlled_values_financial_ratio_interpretation_review_blocker_row(
            str(error.get("message") or "controlled_values_financial_ratio_interpretation_review_failed"),
            details=dict(error),
        )
        for error in errors
    ]
    report: dict[str, Any] = {
        "mode": "rzd-manual-official-pdf-controlled-values-financial-ratio-interpretation-review",
        "status": "failed",
        "financial_ratio_interpretation_review_status": "failed",
        "expected_revision": RZD_CONTROLLED_VALUES_MIGRATION_READINESS_DEFAULT_REVISION,
        "expected_table": RZD_CONTROLLED_VALUES_MIGRATION_READINESS_DEFAULT_TABLE,
        "expected_import_row_count": RZD_CONTROLLED_VALUES_IMPORT_APPLY_PLAN_DEFAULT_ROW_COUNT,
        "blocker_rows": blocker_rows,
        "verification_check_rows": [],
        "reviewed_ratio_rows": [],
        "unavailable_ratio_review_rows": [],
        "methodology_action_rows": [],
        "review_warning_rows": [],
        "review_category_rows": [],
        "safety_flags": _rzd_controlled_values_financial_ratio_interpretation_review_safety_flags(),
        **_rzd_controlled_values_financial_ratio_interpretation_review_safety_flags(),
        "recommendation_generated": False,
        "safe_hint": "Task189 failed before read-only financial ratio interpretation review completed.",
        "next_step": "Fix Task189 input/output errors before retrying.",
        "next_steps": _next_steps("rzd-manual-official-pdf-controlled-values-financial-ratio-interpretation-review", "failed"),
        "errors": errors,
    }
    _rzd_controlled_values_financial_ratio_interpretation_review_normalize_report(report)
    if write_outputs:
        try:
            _rzd_controlled_values_financial_ratio_interpretation_review_write_outputs(report, artifacts)
        except OSError as exc:
            report["errors"] = [*report.get("errors", []), {"message": "controlled_values_financial_ratio_interpretation_review_write_failed", "error": str(exc)}]
    return report


def _rzd_controlled_values_financial_ratio_interpretation_review_write_outputs(
    report: dict[str, Any],
    artifacts: dict[str, Path | None],
) -> None:
    if artifacts.get("review_json"):
        write_json_report(report, artifacts["review_json"])
    if artifacts.get("review_markdown"):
        write_rzd_manual_official_pdf_controlled_values_financial_ratio_interpretation_review_markdown(report, artifacts["review_markdown"])
    if artifacts.get("checks_json"):
        write_json_report({"verification_check_count": report.get("verification_check_count", 0), "verification_check_rows": report.get("verification_check_rows") or [], "safe_hint": report.get("safe_hint") or ""}, artifacts["checks_json"])
    if artifacts.get("blockers_json"):
        write_json_report({"blocker_count": report.get("blocker_count", 0), "blocker_rows": report.get("blocker_rows") or [], "safe_hint": report.get("safe_hint") or ""}, artifacts["blockers_json"])
    if artifacts.get("review_rows_json"):
        write_json_report({"reviewed_ratio_count": report.get("reviewed_ratio_count", 0), "reviewed_ratio_rows": report.get("reviewed_ratio_rows") or [], "unavailable_ratio_review_rows": report.get("unavailable_ratio_review_rows") or [], "safe_hint": report.get("safe_hint") or ""}, artifacts["review_rows_json"])
    if artifacts.get("summary_json"):
        write_json_report({"review_category_rows": report.get("review_category_rows") or [], "interpretation_review_checksum_sha256": report.get("interpretation_review_checksum_sha256", ""), "safe_hint": report.get("safe_hint") or ""}, artifacts["summary_json"])
    if artifacts.get("warnings_json"):
        write_json_report({"review_warning_count": report.get("review_warning_count", 0), "review_warning_rows": report.get("review_warning_rows") or [], "safe_hint": report.get("safe_hint") or ""}, artifacts["warnings_json"])
    if artifacts.get("actions_json"):
        write_json_report({"methodology_action_count": report.get("methodology_action_count", 0), "methodology_action_rows": report.get("methodology_action_rows") or [], "safe_hint": report.get("safe_hint") or ""}, artifacts["actions_json"])
    if artifacts.get("safety_json"):
        write_json_report({
            "database_mutated": False,
            "migration_executed": False,
            "import_executed": False,
            "scoring_executed": False,
            "trading_executed": False,
            "paper_trading_executed": False,
            "recommendation_generated": False,
            "ready_for_controlled_import_apply": False,
            "ready_for_controlled_import": False,
            "ready_for_scoring": False,
            "ready_for_trading": False,
            "ready_for_paper_trading": False,
            "safety_flags": report.get("safety_flags") or {},
            "safe_hint": report.get("safe_hint") or "",
        }, artifacts["safety_json"])


def run_rzd_manual_official_pdf_controlled_values_financial_ratio_interpretation_review(args: argparse.Namespace) -> dict[str, Any]:
    inputs = _rzd_controlled_values_financial_ratio_interpretation_review_inputs(args)
    artifacts = _rzd_controlled_values_financial_ratio_interpretation_review_artifacts(args)
    output_errors = _rzd_controlled_values_financial_ratio_interpretation_review_output_errors(
        args,
        inputs=inputs,
        artifacts=artifacts,
    )
    if output_errors:
        return _rzd_controlled_values_financial_ratio_interpretation_review_failed_report(output_errors, artifacts=artifacts, write_outputs=False)
    try:
        task188 = _load_json_object(inputs["task188"]) if inputs.get("task188") and inputs["task188"].is_file() else {}
        task187 = _load_json_object(inputs["task187"]) if inputs.get("task187") and inputs["task187"].is_file() else {}
        task186 = _load_json_object(inputs["task186"]) if inputs.get("task186") and inputs["task186"].is_file() else {}
        task185 = _load_json_object(inputs["task185"]) if inputs.get("task185") and inputs["task185"].is_file() else {}
        task184 = _load_json_object(inputs["task184"]) if inputs.get("task184") and inputs["task184"].is_file() else {}
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return _rzd_controlled_values_financial_ratio_interpretation_review_failed_report(
            [{"message": "controlled_values_financial_ratio_interpretation_review_input_required", "error": str(exc)}],
            artifacts=artifacts,
        )
    report = _build_rzd_controlled_values_financial_ratio_interpretation_review_report(
        task188,
        task187=task187,
        task186=task186,
        task185=task185,
        task184=task184,
        inputs=inputs,
        args=args,
    )
    report["artifacts"] = {key: str(path or "") for key, path in artifacts.items()}
    try:
        _rzd_controlled_values_financial_ratio_interpretation_review_write_outputs(report, artifacts)
    except OSError as exc:
        report["status"] = "failed"
        report["financial_ratio_interpretation_review_status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": "controlled_values_financial_ratio_interpretation_review_write_failed", "error": str(exc)}]
        _rzd_controlled_values_financial_ratio_interpretation_review_normalize_report(report)
    return report


