def _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_output_errors(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
) -> list[dict[str, Any]]:
    seen: dict[Path, str] = {}
    for key, path in artifacts.items():
        if path is None:
            continue
        for input_key, input_path in inputs.items():
            if input_path and path == input_path:
                return [{"message": "rzd_controlled_values_multi_issuer_evidence_source_selection_plan_output_must_not_equal_input", "output": key, "input": input_key}]
        if path in seen:
            return [{"message": "rzd_controlled_values_multi_issuer_evidence_source_selection_plan_output_must_not_equal_input", "output": key, "duplicate_output": seen[path]}]
        seen[path] = key
    return []


