def run_rzd_manual_official_pdf_controlled_values_multi_issuer_evidence_source_selection_plan(args: argparse.Namespace) -> dict[str, Any]:
    inputs = _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_inputs(args)
    artifacts = _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_artifacts(args)
    output_errors = _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_output_errors(args, inputs=inputs, artifacts=artifacts)
    if output_errors:
        return _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_failed_report(output_errors, artifacts=artifacts, write_outputs=False)
    try:
        task208_path = inputs.get("task208")
        task208 = _load_json_object(task208_path) if task208_path is not None and task208_path.is_file() else {}
    except Exception as exc:
        return _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_failed_report(
            [{"message": "controlled_values_multi_issuer_evidence_source_selection_plan_input_required", "error": str(exc)}],
            artifacts=artifacts,
        )
    report = _build_rzd_controlled_values_multi_issuer_evidence_source_selection_plan_report(task208, inputs=inputs, args=args)
    try:
        _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_write_outputs(report, artifacts)
    except Exception as exc:
        report["status"] = "failed"
        report["multi_issuer_evidence_source_selection_plan_status"] = "failed"
        report["errors"] = [*report.get("errors", []), {"message": "controlled_values_multi_issuer_evidence_source_selection_plan_write_failed", "error": str(exc)}]
        _rzd_controlled_values_multi_issuer_evidence_source_selection_plan_normalize_report(report)
    return report


